:root {
  --green-950: #06281b;
  --green-900: #083b29;
  --green-850: #0a4933;
  --green-800: #0b5b3d;
  --green-700: #0d704a;
  --green-600: #108052;
  --green-500: #1b9562;
  --green-300: #83d6a3;
  --green-100: #e4f4e8;
  --cream: #f7faf5;
  --ink: #0a3022;
  --muted: #70847a;
  --line: #dce8df;
  --white: #ffffff;
}

/* =========================================================
   GLOBAL
   ========================================================= */

* {
  box-sizing: border-box;
}

body {
  overflow-x: hidden;
}

main {
  overflow: hidden;
}

.home-container,
.shop-container,
.product-details-container {
  width: min(1240px, calc(100% - 64px));
  margin: 0 auto;
}

/* =========================================================
   HOME
   ========================================================= */

.home-page {
  background: var(--cream);
  color: var(--ink);
}

.home-hero {
  position: relative;
  min-height: 760px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #073a29;
  color: white;
}

.home-hero-background {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 78% 42%, rgba(80, 210, 126, 0.27), transparent 30%),
    radial-gradient(circle at 15% 90%, rgba(32, 150, 94, 0.28), transparent 32%),
    linear-gradient(135deg, #052d20 0%, #0a4d35 58%, #08714b 100%);
}

.home-hero-grid {
  position: absolute;
  inset: 0;
  opacity: 0.12;
  background-image:
    linear-gradient(rgba(255,255,255,.12) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.12) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: linear-gradient(to right, transparent, black 40%, black 85%, transparent);
}

.home-hero-layout {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(420px, .98fr);
  gap: 50px;
  align-items: center;
  padding: 90px 0;
}

.home-hero-content {
  max-width: 650px;
}

.home-eyebrow,
.shop-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .17em;
}

.home-eyebrow span,
.shop-eyebrow span {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 50%;
  background: rgba(255,255,255,.08);
}

.home-hero h1 {
  max-width: 700px;
  margin: 25px 0 22px;
  font-size: clamp(52px, 6.5vw, 88px);
  line-height: .96;
  letter-spacing: -.065em;
}

.home-highlight,
.home-hero h1 em,
.home-section-heading em,
.home-materials-header em,
.home-cta em,
.shop-hero h1 em,
.shop-results-heading em {
  color: #83dfa5;
  font-family: "Playfair Display", serif;
  font-style: italic;
  font-weight: 600;
}

.home-hero-content > p {
  max-width: 570px;
  margin: 0;
  color: rgba(255,255,255,.72);
  font-size: 16px;
  line-height: 1.75;
}

.home-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 32px;
}

.home-primary-button,
.home-secondary-button,
.home-cta-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 20px;
  border-radius: 15px;
  font-size: 12px;
  font-weight: 850;
  transition: .25s ease;
}

.home-primary-button {
  background: #e9f9ee;
  color: #0a4d35;
  box-shadow: 0 14px 35px rgba(0,0,0,.14);
}

.home-primary-button:hover {
  transform: translateY(-3px);
  background: white;
}

.home-secondary-button {
  border: 1px solid rgba(255,255,255,.2);
  color: white;
  background: rgba(255,255,255,.06);
  backdrop-filter: blur(12px);
}

.home-secondary-button:hover {
  border-color: rgba(255,255,255,.4);
  background: rgba(255,255,255,.12);
}

.home-proof {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 34px;
}

.home-proof-avatars {
  display: flex;
}

.home-proof-avatars span {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  margin-left: -6px;
  border: 2px solid #0a4933;
  border-radius: 50%;
  background: #d8f1df;
  color: #0a5539;
  font-size: 9px;
  font-weight: 900;
}

.home-proof-avatars span:first-child {
  margin-left: 0;
}

.home-proof strong,
.home-proof small {
  display: block;
}

.home-proof strong {
  font-size: 11px;
}

.home-proof small {
  margin-top: 3px;
  color: rgba(255,255,255,.56);
  font-size: 9px;
}

.home-hero-art {
  position: relative;
  min-height: 520px;
  display: grid;
  place-items: center;
}

.home-art-glow {
  position: absolute;
  width: 390px;
  height: 390px;
  border-radius: 50%;
  background: rgba(111, 229, 147, .18);
  filter: blur(50px);
}

.home-art-ring {
  position: absolute;
  border: 1px solid rgba(169,244,192,.18);
  border-radius: 50%;
}

.home-art-ring-one {
  width: 430px;
  height: 430px;
}

.home-art-ring-two {
  width: 340px;
  height: 340px;
  border-style: dashed;
  opacity: .7;
}

.home-art-orb {
  position: relative;
  z-index: 2;
  width: 275px;
  height: 275px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 28%, #d4f7dd, #75d39a 48%, #178052 100%);
  box-shadow:
    0 45px 100px rgba(0,0,0,.22),
    inset -20px -25px 50px rgba(3,61,38,.18);
}

.home-art-orb-inner {
  width: 215px;
  height: 215px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.48);
  border-radius: 50%;
  color: #075337;
  background: rgba(255,255,255,.16);
  backdrop-filter: blur(5px);
}

.home-floating-card {
  position: absolute;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 15px;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 17px;
  background: rgba(4,45,31,.62);
  box-shadow: 0 20px 45px rgba(0,0,0,.18);
  backdrop-filter: blur(15px);
}

.home-floating-card-top {
  top: 65px;
  left: 4%;
}

.home-floating-card-bottom {
  right: 0;
  bottom: 60px;
  color: #a9ebbe;
}

.home-floating-icon {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: rgba(111,229,147,.13);
  color: #8de4aa;
}

.home-floating-card span,
.home-floating-card strong {
  display: block;
}

.home-floating-card span {
  color: rgba(255,255,255,.45);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .13em;
}

.home-floating-card strong {
  margin-top: 3px;
  color: white;
  font-size: 11px;
}

.home-art-tag {
  position: absolute;
  right: 9%;
  top: 22%;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border: 1px solid rgba(133,229,161,.2);
  border-radius: 999px;
  background: rgba(4,45,31,.55);
  color: #9be9b4;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .13em;
  backdrop-filter: blur(12px);
}

.home-scroll-cue {
  position: absolute;
  left: 50%;
  bottom: 22px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 9px;
  transform: translateX(-50%);
  color: rgba(255,255,255,.4);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .18em;
}

.home-scroll-cue span {
  width: 25px;
  height: 1px;
  background: rgba(255,255,255,.3);
}

.home-stats {
  border-bottom: 1px solid var(--line);
  background: white;
}

.home-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.home-stats-grid > div {
  padding: 27px 24px;
  border-right: 1px solid var(--line);
}

.home-stats-grid > div:last-child {
  border-right: 0;
}

.home-stats strong,
.home-stats span {
  display: block;
}

.home-stats strong {
  color: var(--green-700);
  font-size: 27px;
  letter-spacing: -.05em;
}

.home-stats span {
  margin-top: 4px;
  color: #87978f;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.home-section {
  padding: 110px 0;
}

.home-section-heading,
.home-materials-header {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 40px;
}

.home-kicker,
.shop-kicker {
  margin: 0 0 10px;
  color: var(--green-600);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .18em;
}

.home-section-heading h2,
.home-materials-header h2,
.home-cta h2,
.shop-results-heading h2 {
  max-width: 650px;
  margin: 0;
  color: #0a3324;
  font-size: clamp(36px, 4.5vw, 60px);
  line-height: 1;
  letter-spacing: -.055em;
}

.home-section-heading > p {
  max-width: 390px;
  margin: 0;
  color: #7c8d84;
  font-size: 13px;
  line-height: 1.8;
}

.home-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 55px;
}

.home-benefit-card {
  position: relative;
  min-height: 300px;
  padding: 27px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 25px;
  background: white;
  box-shadow: 0 15px 50px rgba(24,73,46,.04);
  transition: border-color .25s ease;
}

.home-benefit-card:hover {
  border-color: #b8ddc4;
}

.home-benefit-number {
  position: absolute;
  right: 25px;
  top: 22px;
  color: #d9e9dd;
  font-size: 38px;
  font-weight: 900;
}

.home-benefit-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: var(--green-100);
  color: var(--green-600);
}

.home-benefit-card h3 {
  margin: 45px 0 9px;
  color: #173e2e;
  font-size: 18px;
  letter-spacing: -.03em;
}

.home-benefit-card p {
  max-width: 280px;
  margin: 0;
  color: #7d8e85;
  font-size: 12px;
  line-height: 1.75;
}

.home-card-arrow {
  position: absolute;
  right: 25px;
  bottom: 24px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #f1f7f2;
  color: var(--green-600);
}

.home-materials {
  padding: 100px 0;
  background: #eef6ef;
}

.home-text-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--green-700);
  font-size: 11px;
  font-weight: 850;
}

.home-materials-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-top: 48px;
}

.home-material-card {
  position: relative;
  min-height: 330px;
  padding: 24px;
  overflow: hidden;
  border-radius: 25px;
  background: white;
  box-shadow: 0 18px 50px rgba(22,76,46,.06);
}

.home-material-card::after {
  content: "";
  position: absolute;
  width: 190px;
  height: 190px;
  right: -55px;
  top: -55px;
  border-radius: 50%;
  background: #dff2e3;
}

.home-material-2 {
  background: #e2f1e3;
}

.home-material-3 {
  background: #eaf4ef;
}

.home-material-4 {
  background: #e7f0e6;
}

.home-material-number {
  position: relative;
  z-index: 2;
  color: #90a89b;
  font-size: 10px;
  font-weight: 900;
}

.home-material-symbol {
  position: relative;
  z-index: 2;
  width: 75px;
  height: 75px;
  margin-top: 55px;
  display: grid;
  place-items: center;
  border-radius: 24px;
  background: rgba(255,255,255,.62);
  color: var(--green-600);
}

.home-material-copy {
  position: absolute;
  left: 24px;
  bottom: 24px;
}

.home-material-copy span {
  color: #82958a;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .14em;
}

.home-material-copy h3 {
  margin: 5px 0 0;
  color: #173e2e;
  font-size: 24px;
  letter-spacing: -.045em;
}

.home-material-card > strong {
  position: absolute;
  right: 24px;
  bottom: 27px;
  z-index: 2;
  color: #9ab0a2;
  font-size: 16px;
}

.circle-material-icon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  border: 2px solid currentColor;
  border-radius: 50%;
}

.circle-material-icon span {
  width: 17px;
  height: 17px;
  border: 2px solid currentColor;
  border-radius: 50%;
}

.home-cta {
  position: relative;
  overflow: hidden;
  padding: 90px 0;
  background: var(--green-950);
  color: white;
}

.home-cta-glow {
  position: absolute;
  width: 500px;
  height: 500px;
  right: -120px;
  top: -240px;
  border-radius: 50%;
  background: rgba(72, 202, 115, .15);
  filter: blur(20px);
}

.home-cta-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 25px;
}

.home-cta-icon {
  width: 62px;
  height: 62px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 19px;
  background: rgba(255,255,255,.06);
  color: #8be3a8;
}

.home-cta h2 {
  color: white;
  font-size: clamp(31px, 4vw, 51px);
}

.home-cta-button {
  background: #e7f8ec;
  color: #0a5137;
}

.home-cta-button:hover {
  transform: translateY(-3px);
  background: white;
}

.home-footer {
  padding: 65px 0 22px;
  background: #f5f9f5;
}

.home-footer-top {
  display: grid;
  grid-template-columns: 1.5fr .7fr .7fr 1.2fr;
  gap: 50px;
}

.home-footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #0a3d2a;
  font-size: 21px;
  font-weight: 900;
  letter-spacing: -.05em;
}

.home-footer-logo > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: var(--green-800);
  color: white;
}

.home-footer-logo > span + span {
  color: var(--green-600);
}

.home-footer-brand p,
.home-footer-column p {
  max-width: 250px;
  color: #829188;
  font-size: 11px;
  line-height: 1.7;
}

.home-footer-socials {
  display: flex;
  gap: 7px;
  margin-top: 18px;
}

.home-footer-socials span {
  width: 29px;
  height: 29px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--green-700);
  font-size: 9px;
  font-weight: 900;
}

.home-footer-column {
  display: flex;
  flex-direction: column;
  gap: 11px;
}

.home-footer-heading {
  margin-bottom: 5px;
  color: #547166;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .16em;
}

.home-footer-column a {
  color: #71857b;
  font-size: 11px;
}

.home-footer-column a:hover {
  color: var(--green-700);
}

.home-footer-input {
  display: flex;
  max-width: 300px;
  margin-top: 4px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: white;
  overflow: hidden;
}

.home-footer-input input {
  min-width: 0;
  flex: 1;
  padding: 13px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font-size: 10px;
}

.home-footer-input button {
  width: 44px;
  border: 0;
  background: var(--green-800);
  color: white;
}

.home-footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  margin-top: 55px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  color: #9aaa9f;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .1em;
}

/* =========================================================
   SHOP
   ========================================================= */

.shop-page {
  min-height: 100vh;
  background: #f6faf6;
}

.shop-hero {
  position: relative;
  min-height: 590px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #063a28;
  color: white;
}

.shop-hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 78% 45%, rgba(94,220,135,.26), transparent 29%),
    linear-gradient(130deg, #052c20, #0b5c3e 72%, #08744c);
}

.shop-hero-grid {
  position: absolute;
  inset: 0;
  opacity: .1;
  background-image:
    linear-gradient(rgba(255,255,255,.13) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.13) 1px, transparent 1px);
  background-size: 55px 55px;
}

.shop-hero-layout {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 40px;
  padding: 75px 0;
}

.shop-hero-copy {
  max-width: 600px;
}

.shop-hero h1 {
  margin: 24px 0 20px;
  font-size: clamp(50px, 6vw, 76px);
  line-height: .97;
  letter-spacing: -.065em;
}

.shop-hero-copy > p {
  max-width: 500px;
  color: rgba(255,255,255,.68);
  font-size: 15px;
  line-height: 1.75;
}

.shop-hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 28px;
}

.shop-hero-meta span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #a7e7b9;
  font-size: 10px;
  font-weight: 750;
}

.shop-hero-art {
  position: relative;
  min-height: 440px;
  display: grid;
  place-items: center;
}

.shop-art-glow {
  position: absolute;
  width: 310px;
  height: 310px;
  border-radius: 50%;
  background: rgba(112,229,146,.18);
  filter: blur(45px);
}

.shop-art-orbit {
  position: absolute;
  border: 1px solid rgba(162,239,183,.17);
  border-radius: 50%;
}

.shop-art-orbit-one {
  width: 420px;
  height: 420px;
}

.shop-art-orbit-two {
  width: 300px;
  height: 300px;
  border-style: dashed;
}

.shop-material-stack {
  position: relative;
  width: 280px;
  height: 350px;
  z-index: 3;
}

.shop-material-sheet {
  position: absolute;
  width: 245px;
  height: 305px;
  left: 18px;
  padding: 25px;
  border-radius: 22px;
  box-shadow: 0 30px 65px rgba(0,0,0,.2);
}

.shop-material-sheet span {
  display: block;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .17em;
}

.shop-material-sheet strong {
  display: block;
  margin-top: 9px;
  font-size: 26px;
  line-height: 1;
  letter-spacing: -.04em;
}

.sheet-back {
  top: 30px;
  transform: rotate(-13deg);
  background: #a8d7b1;
  color: #215b3d;
}

.sheet-middle {
  top: 13px;
  transform: rotate(7deg);
  background: #d9ebd9;
  color: #23553b;
}

.sheet-front {
  top: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: #f1f7ed;
  color: #17442e;
}

.shop-sheet-icon {
  width: 105px;
  height: 105px;
  display: grid;
  place-items: center;
  border-radius: 28px;
  background: #d9efdc;
  color: #1a8050;
}

.shop-floating-note {
  position: absolute;
  right: -5px;
  bottom: 22px;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px 15px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 16px;
  background: rgba(4,47,32,.7);
  backdrop-filter: blur(14px);
  color: #9de5b3;
}

.shop-floating-note span {
  display: flex;
  flex-direction: column;
  color: rgba(255,255,255,.55);
  font-size: 9px;
}

.shop-floating-note strong {
  color: white;
  font-size: 10px;
}

.shop-catalog {
  padding: 65px 0 110px;
}

.shop-toolbar {
  display: grid;
  grid-template-columns: 1fr 200px;
  gap: 14px;
}

.shop-search {
  height: 54px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 17px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: white;
  color: #7b9185;
}

.shop-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font-size: 12px;
}

.shop-toolbar select {
  height: 54px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 15px;
  outline: 0;
  background: white;
  color: #526c5f;
  font-size: 11px;
  font-weight: 750;
}

.shop-category-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 15px;
}

.shop-category-row button {
  min-height: 38px;
  padding: 0 15px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: white;
  color: #71847b;
  font-size: 10px;
  font-weight: 800;
  transition: .2s ease;
}

.shop-category-row button:hover,
.shop-category-row button.active {
  border-color: var(--green-700);
  background: var(--green-800);
  color: white;
}

.shop-results-heading {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 20px;
  margin-top: 70px;
}

.shop-results-heading > span {
  color: #8a9a91;
  font-size: 10px;
  font-weight: 750;
}

.shop-product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 17px;
  margin-top: 35px;
}

.shop-product-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 23px;
  background: white;
  box-shadow: 0 15px 50px rgba(25,77,47,.045);
}

.shop-product-visual {
  position: relative;
  min-height: 285px;
  display: grid;
  place-items: center;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 48%, #d7f0dc, transparent 38%),
    linear-gradient(145deg, #edf7ee, #dcefe0);
}

.shop-eco-label {
  position: absolute;
  left: 15px;
  top: 15px;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 9px;
  border-radius: 999px;
  background: rgba(255,255,255,.78);
  color: var(--green-700);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
  backdrop-filter: blur(10px);
}

.shop-favorite {
  position: absolute;
  right: 15px;
  top: 15px;
  z-index: 4;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(13,112,74,.12);
  border-radius: 50%;
  background: rgba(255,255,255,.78);
  color: #547166;
  backdrop-filter: blur(10px);
}

.shop-favorite:hover,
.shop-favorite.active {
  color: #c25454;
}

.shop-product-orb {
  width: 155px;
  height: 155px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.75);
  border-radius: 50%;
  background: rgba(255,255,255,.72);
  color: var(--green-600);
  box-shadow: 0 30px 50px rgba(28,93,53,.12);
}

/* Real product gallery images */
.shop-product-image-wrap {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 48px 28px 30px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 46%, rgba(255,255,255,.96), transparent 52%),
    linear-gradient(145deg, #edf7ee, #dcefe0);
}

.shop-product-image {
  width: 100%;
  height: 100%;
  max-width: 100%;
  max-height: 100%;
  display: block;
  object-fit: contain;
  object-position: center;
  border-radius: 14px;
  filter: saturate(.96);
  transition:
    transform .45s cubic-bezier(.2,.7,.2,1),
    filter .3s ease;
}

.shop-product-card:hover .shop-product-image {
  transform: scale(1.045);
  filter: saturate(1.03);
}

.shop-product-image-wrap::after {
  content: "";
  position: absolute;
  inset: auto 18% 10px;
  height: 18px;
  border-radius: 50%;
  background: rgba(35, 91, 60, .10);
  filter: blur(12px);
  pointer-events: none;
}

.shop-product-material {
  position: absolute;
  right: 16px;
  bottom: 15px;
  color: #789187;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .12em;
}

.shop-product-content {
  padding: 19px;
}

.shop-rating {
  display: flex;
  align-items: center;
  gap: 7px;
}

.shop-rating span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #c28a24;
  font-size: 10px;
  font-weight: 800;
}

.shop-rating small {
  color: #a0aaa5;
  font-size: 9px;
}

.shop-product-title {
  display: block;
  margin-top: 9px;
  color: #173e2e;
  font-size: 16px;
  font-weight: 850;
  letter-spacing: -.03em;
}

.shop-product-title:hover {
  color: var(--green-700);
}

.shop-product-content > p {
  min-height: 38px;
  margin: 8px 0 15px;
  color: #829188;
  font-size: 10px;
  line-height: 1.65;
}

.shop-product-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.shop-product-bottom > strong {
  color: #123e2b;
  font-size: 17px;
}

.shop-product-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 11px;
  border-radius: 10px;
  background: #edf7ef;
  color: var(--green-700);
  font-size: 9px;
  font-weight: 850;
}

.shop-product-button:hover {
  background: var(--green-800);
  color: white;
}

.shop-empty {
  min-height: 320px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--green-600);
}

.shop-empty h3 {
  margin: 15px 0 5px;
  color: var(--ink);
}

.shop-empty p {
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 12px;
}

.shop-empty button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 11px 15px;
  border: 0;
  border-radius: 11px;
  background: var(--green-800);
  color: white;
  font-size: 10px;
  font-weight: 800;
}

/* =========================================================
   PRODUCT DETAILS
   ========================================================= */

.product-details-page {
  min-height: calc(100vh - 120px);
  background:
    radial-gradient(circle at 12% 35%, rgba(108,203,132,.12), transparent 28%),
    #f5f9f4;
}

.product-details-container {
  padding: 32px 0 100px;
}

.product-back-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #527064;
  font-size: 13px;
  font-weight: 750;
  transition: color .2s ease;
}

.product-back-link:hover {
  color: #08764b;
}

.product-details-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 75px;
  align-items: center;
  margin-top: 25px;
}

.product-detail-visual {
  min-height: 600px;
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 34px;
  background:
    radial-gradient(circle at 50% 48%, rgba(183,236,198,.8), transparent 35%),
    linear-gradient(145deg, #edf8ef, #dcefe0);
  border: 1px solid #d8e8db;
}

.product-detail-glow {
  position: absolute;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: rgba(76,197,117,.18);
  filter: blur(45px);
}

.product-detail-orbit {
  position: absolute;
  width: 440px;
  height: 440px;
  border: 1px solid rgba(30,128,76,.15);
  border-radius: 50%;
}

.product-detail-orbit::before {
  content: "";
  position: absolute;
  inset: 42px;
  border: 1px dashed rgba(30,128,76,.12);
  border-radius: 50%;
}

.product-detail-product {
  width: 270px;
  height: 270px;
  display: grid;
  place-items: center;
  border-radius: 48px;
  background: rgba(255,255,255,.88);
  border: 1px solid rgba(255,255,255,.95);
  color: #168052;
  box-shadow:
    0 35px 80px rgba(19,91,53,.14),
    inset 0 1px 0 white;
  z-index: 2;
}

.product-detail-eco {
  position: absolute;
  top: 25px;
  left: 25px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 9px 13px;
  border-radius: 999px;
  background: #0b4935;
  color: #a8edc3;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .12em;
  z-index: 4;
}

.product-detail-material {
  position: absolute;
  right: 25px;
  bottom: 25px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  z-index: 4;
}

.product-detail-material span {
  color: #709083;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .15em;
}

.product-detail-material strong {
  margin-top: 4px;
  color: #0b3b2a;
  font-size: 12px;
}

.product-detail-info {
  max-width: 560px;
}

.product-detail-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #108052;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .17em;
}

.product-detail-rating {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 19px;
  color: #7a8c83;
  font-size: 12px;
}

.rating-stars {
  display: inline-flex;
  gap: 2px;
  color: #d79b26;
}

.product-detail-rating strong {
  color: #264b3c;
}

.product-detail-info h1 {
  margin: 13px 0 0;
  color: #092f21;
  font-size: clamp(40px, 5vw, 64px);
  line-height: .98;
  letter-spacing: -.06em;
}

.product-detail-description {
  margin: 22px 0 0;
  color: #6e8077;
  font-size: 15px;
  line-height: 1.75;
}

.product-detail-price {
  margin-top: 25px;
  color: #0a3b29;
  font-size: 31px;
  font-weight: 900;
  letter-spacing: -.04em;
}

.product-detail-price span {
  display: block;
  margin-top: 4px;
  color: #89988f;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0;
}

.product-detail-divider {
  height: 1px;
  margin: 28px 0;
  background: #dce7de;
}

.product-benefits {
  display: grid;
  gap: 14px;
}

.product-benefits > div {
  display: flex;
  align-items: center;
  gap: 12px;
}

.benefit-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #e2f5e7;
  color: #108052;
}

.product-benefits > div > span:last-child {
  display: flex;
  flex-direction: column;
}

.product-benefits strong {
  color: #214939;
  font-size: 12px;
}

.product-benefits small {
  margin-top: 2px;
  color: #87978e;
  font-size: 10px;
}

.product-purchase-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  margin-top: 30px;
}

.quantity-control {
  height: 52px;
  display: flex;
  align-items: center;
  border: 1px solid #d6e4d9;
  border-radius: 14px;
  background: white;
  overflow: hidden;
}

.quantity-control button {
  width: 42px;
  height: 100%;
  border: 0;
  background: transparent;
  color: #426256;
  display: grid;
  place-items: center;
}

.quantity-control button:hover {
  background: #edf6ee;
}

.quantity-control strong {
  width: 35px;
  text-align: center;
  color: #143e2e;
  font-size: 13px;
}

.product-detail-add {
  height: 52px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 0;
  border-radius: 14px;
  background: #0a5038;
  color: white;
  font-size: 13px;
  font-weight: 850;
  box-shadow: 0 12px 28px rgba(10,80,56,.17);
  transition: .25s ease;
}

.product-detail-add:hover {
  background: #0d6849;
  transform: translateY(-2px);
}

.product-detail-add.added {
  background: #168052;
}

.product-detail-wishlist {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border: 1px solid #d6e4d9;
  border-radius: 14px;
  background: white;
  color: #49675a;
}

.product-detail-wishlist:hover,
.product-detail-wishlist.active {
  color: #c45252;
  border-color: #efcccc;
  background: #fff7f7;
}

.product-detail-trust {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 22px;
}

.product-detail-trust > div {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 14px;
  border: 1px solid #e0eae2;
  border-radius: 14px;
  background: rgba(255,255,255,.65);
  color: #168052;
}

.product-detail-trust span {
  display: flex;
  flex-direction: column;
  color: #87968e;
  font-size: 9px;
  line-height: 1.45;
}

.product-detail-trust strong {
  margin-bottom: 2px;
  color: #294c3e;
  font-size: 10px;
}

.product-not-found {
  min-height: 60vh;
  display: grid;
  place-items: center;
  align-content: center;
  text-align: center;
  color: #168052;
}

.product-not-found h1 {
  margin: 15px 0 5px;
  color: #0a3828;
}

.product-not-found p {
  margin: 0 0 22px;
  color: #74867c;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1050px) {
  .home-hero-layout,
  .shop-hero-layout {
    grid-template-columns: 1fr;
  }

  .home-hero-content,
  .shop-hero-copy {
    max-width: 720px;
  }

  .home-hero-art,
  .shop-hero-art {
    min-height: 430px;
  }

  .home-benefits-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .home-materials-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .shop-product-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .product-details-layout {
    gap: 45px;
  }
}

@media (max-width: 900px) {
  .home-container,
  .shop-container,
  .product-details-container {
    width: min(100% - 40px, 760px);
  }

  .home-section-heading,
  .home-materials-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .home-footer-top {
    grid-template-columns: 1fr 1fr;
  }

  .shop-product-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .product-details-layout {
    grid-template-columns: 1fr;
  }

  .product-detail-info {
    max-width: none;
  }

  .product-detail-visual {
    min-height: 500px;
  }
}

@media (max-width: 620px) {
  .home-container,
  .shop-container,
  .product-details-container {
    width: calc(100% - 32px);
  }

  .home-hero {
    min-height: auto;
  }

  .home-hero-layout {
    padding: 70px 0 85px;
  }

  .home-hero h1,
  .shop-hero h1 {
    font-size: 48px;
  }

  .home-hero-art,
  .shop-hero-art {
    min-height: 360px;
  }

  .home-art-orb {
    width: 210px;
    height: 210px;
  }

  .home-art-orb-inner {
    width: 165px;
    height: 165px;
  }

  .home-art-ring-one {
    width: 300px;
    height: 300px;
  }

  .home-art-ring-two {
    width: 240px;
    height: 240px;
  }

  .home-floating-card-top {
    top: 10px;
    left: 0;
  }

  .home-floating-card-bottom {
    right: 0;
    bottom: 20px;
  }

  .home-art-tag {
    top: 12px;
    right: 0;
  }

  .home-stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .home-stats-grid > div:nth-child(2) {
    border-right: 0;
  }

  .home-stats-grid > div:nth-child(-n+2) {
    border-bottom: 1px solid var(--line);
  }

  .home-section,
  .home-materials {
    padding: 75px 0;
  }

  .home-benefits-grid,
  .home-materials-grid {
    grid-template-columns: 1fr;
  }

  .home-footer-top {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .home-footer-bottom {
    flex-direction: column;
    gap: 8px;
  }

  .shop-hero {
    min-height: auto;
  }

  .shop-hero-layout {
    padding: 65px 0;
  }

  .shop-art-orbit-one {
    width: 310px;
    height: 310px;
  }

  .shop-art-orbit-two {
    width: 235px;
    height: 235px;
  }

  .shop-material-stack {
    transform: scale(.82);
  }

  .shop-floating-note {
    right: 0;
  }

  .shop-toolbar {
    grid-template-columns: 1fr;
  }

  .shop-results-heading {
    align-items: flex-start;
    flex-direction: column;
    margin-top: 50px;
  }

  .shop-product-grid {
    grid-template-columns: 1fr;
  }

  .product-detail-visual {
    min-height: 400px;
    border-radius: 25px;
  }

  .product-detail-product {
    width: 210px;
    height: 210px;
  }

  .product-detail-product svg {
    width: 80px;
  }

  .product-detail-orbit {
    width: 330px;
    height: 330px;
  }

  .product-detail-info h1 {
    font-size: 42px;
  }

  .product-purchase-row {
    grid-template-columns: 1fr auto;
  }

  .quantity-control {
    grid-column: 1 / -1;
    width: fit-content;
  }

  .product-detail-add {
    width: 100%;
  }

  .product-detail-trust {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   GLOBAL NAVBAR
   ========================================================= */

.site-navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  border-bottom: 1px solid rgba(18, 70, 45, .09);
  background: rgba(250, 253, 249, .92);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.site-navbar-inner {
  width: min(1240px, calc(100% - 64px));
  min-height: 76px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.site-brand {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  flex-shrink: 0;
  color: #083b29;
  font-size: 21px;
  font-weight: 900;
  letter-spacing: -.055em;
}

.site-brand > span:last-child > span {
  color: #128052;
}

.site-brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #0a5038;
  color: white;
  box-shadow: 0 8px 20px rgba(10, 80, 56, .16);
}

.site-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin-left: auto;
}

.site-nav-link {
  position: relative;
  padding: 10px 13px;
  border-radius: 10px;
  color: #63786d;
  font-size: 11px;
  font-weight: 750;
  transition: .2s ease;
}

.site-nav-link:hover {
  color: #0b6849;
  background: #edf6ee;
}

.site-nav-link.active {
  color: #0a5b3d;
  background: #e7f4e9;
}

.site-nav-link.active::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 4px;
  width: 4px;
  height: 4px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: #168052;
}

.site-nav-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.nav-icon-button {
  position: relative;
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  border: 1px solid #dce8df;
  border-radius: 11px;
  background: rgba(255,255,255,.72);
  color: #527064;
  transition: .2s ease;
}

.nav-icon-button:hover {
  border-color: #b8d9c2;
  background: white;
  color: #0a704a;
  transform: translateY(-1px);
}

.nav-cart-count {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  padding: 0 3px;
  border: 2px solid #fafdF9;
  border-radius: 999px;
  background: #168052;
  color: white;
  font-size: 7px;
  font-weight: 900;
}

.nav-account-button {
  min-height: 39px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 13px;
  border-radius: 11px;
  background: #0a5038;
  color: white;
  font-size: 10px;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(10,80,56,.13);
  transition: .2s ease;
}

.nav-account-button:hover {
