   ========================================================= */

.categories-page {
  min-height: 100vh;
  overflow: hidden;
  background: #f7faf5;
}

.categories-hero {
  position: relative;
  min-height: 610px;
  overflow: hidden;
  background:
    radial-gradient(circle at 82% 45%, rgba(87, 176, 117, .22), transparent 30%),
    linear-gradient(135deg, #063a28 0%, #075238 52%, #0b6746 100%);
  color: #f7fff9;
}

.categories-hero-inner {
  position: relative;
  z-index: 2;
  width: min(1240px, calc(100% - 64px));
  min-height: 610px;
  margin: auto;
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  align-items: center;
  gap: 40px;
}

.categories-hero-content {
  max-width: 650px;
  padding: 80px 0;
}

.categories-eyebrow,
.section-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #69b98b;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .18em;
}

.categories-eyebrow {
  color: #a8d9b9;
}

.categories-hero h1 {
  margin: 22px 0 20px;
  font-size: clamp(48px, 6vw, 76px);
  line-height: .98;
  letter-spacing: -.065em;
}

.categories-hero h1 em,
.categories-introduction h2 em,
.categories-impact h2 em,
.categories-final-cta h2 em {
  color: #91d3a5;
  font-family: "Playfair Display", serif;
  font-weight: 600;
}

.categories-hero-content > p {
  max-width: 540px;
  margin: 0;
  color: #c1dbca;
  font-size: 15px;
  line-height: 1.8;
}

.categories-hero-buttons {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 32px;
}

.categories-main-button,
.categories-impact-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 46px;
  padding: 0 20px;
  border-radius: 12px;
  background: #e8f7eb;
  color: #075238;
  font-size: 11px;
  font-weight: 850;
  box-shadow: 0 12px 30px rgba(0, 0, 0, .12);
  transition: .2s ease;
}

.categories-main-button:hover,
.categories-impact-button:hover {
  transform: translateY(-2px);
  background: white;
}

.categories-outline-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 19px;
  border: 1px solid rgba(218, 243, 225, .3);
  border-radius: 12px;
  color: #d7ebdd;
  font-size: 11px;
  font-weight: 750;
  transition: .2s ease;
}

.categories-outline-button:hover {
  border-color: rgba(218, 243, 225, .65);
  background: rgba(255,255,255,.06);
}

.categories-visual {
  position: relative;
  width: min(500px, 100%);
  aspect-ratio: 1;
  margin: auto;
}

.category-orbit {
  position: absolute;
  left: 50%;
  top: 50%;
  border: 1px solid rgba(186, 230, 199, .2);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.orbit-large {
  width: 82%;
  height: 82%;
}

.orbit-small {
  width: 55%;
  height: 55%;
  border-color: rgba(186, 230, 199, .28);
}

.category-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 190px;
  height: 190px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(224, 250, 230, .18);
  border-radius: 50%;
  background: rgba(5, 65, 43, .76);
  box-shadow:
    0 30px 80px rgba(0,0,0,.22),
    inset 0 0 50px rgba(120, 213, 149, .07);
  backdrop-filter: blur(12px);
}

.category-core-icon {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  margin-bottom: 12px;
  border-radius: 18px;
  background: rgba(151, 216, 169, .12);
  color: #9fe0b1;
}

.category-core span {
  color: #80bd93;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .2em;
}

.category-core strong {
  margin-top: 7px;
  color: #edf9f0;
  font-size: 16px;
  line-height: 1.25;
  text-align: center;
}

.material-float {
  position: absolute;
  z-index: 4;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 13px;
  border: 1px solid rgba(222, 248, 229, .16);
  border-radius: 12px;
  background: rgba(7, 71, 47, .76);
  color: #dff3e4;
  font-size: 9px;
  font-weight: 800;
  box-shadow: 0 15px 30px rgba(0,0,0,.13);
  backdrop-filter: blur(10px);
}

.float-cotton {
  top: 13%;
  left: 12%;
}

.float-wood {
  top: 18%;
  right: 8%;
}

.float-glass {
  bottom: 16%;
  left: 6%;
}

.float-paper {
  right: 9%;
  bottom: 12%;
}

.categories-hero-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(3px);
  pointer-events: none;
}

.glow-a {
  width: 300px;
  height: 300px;
  top: -130px;
  left: -80px;
  background: rgba(100, 198, 130, .12);
}

.glow-b {
  width: 400px;
  height: 400px;
  right: -170px;
  bottom: -220px;
  background: rgba(121, 222, 151, .1);
}

.categories-introduction {
  width: min(1100px, calc(100% - 64px));
  margin: 0 auto;
  padding: 105px 0 72px;
  display: grid;
  grid-template-columns: 1fr .8fr;
  align-items: end;
  gap: 90px;
}

.categories-introduction h2 {
  margin: 16px 0 0;
  color: #143f2d;
  font-size: clamp(34px, 4vw, 50px);
  line-height: 1.03;
  letter-spacing: -.055em;
}

.categories-introduction h2 em {
  color: #168052;
}

.categories-introduction > p {
  margin: 0;
  color: #71847a;
  font-size: 14px;
  line-height: 1.9;
}

.categories-materials {
  width: min(1240px, calc(100% - 64px));
  margin: 0 auto;
  padding: 30px 0 105px;
}

.categories-section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 30px;
}

.categories-section-heading h2 {
  margin: 9px 0 0;
  color: #143f2d;
  font-size: 30px;
  letter-spacing: -.045em;
}

.view-all-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #16764d;
  font-size: 10px;
  font-weight: 850;
}

.categories-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.material-category-card {
  overflow: hidden;
  display: grid;
  grid-template-columns: .95fr 1.05fr;
  min-height: 290px;
  border: 1px solid rgba(28, 76, 51, .08);
  border-radius: 24px;
  background: white;
  box-shadow: 0 16px 50px rgba(22, 62, 40, .06);
  transition: .3s ease;
}

.material-category-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 25px 60px rgba(22, 62, 40, .1);
}

.material-card-visual {
  position: relative;
  min-height: 290px;
  overflow: hidden;
  display: grid;
  place-items: center;
}

.material-card-visual::before {
  content: "";
  position: absolute;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: rgba(255,255,255,.25);
  filter: blur(2px);
}

.material-card-visual.cotton {
  background: linear-gradient(145deg, #dff1e2, #b8dfc2);
  color: #22734a;
}

.material-card-visual.wood {
  background: linear-gradient(145deg, #eadfce, #d2bea1);
  color: #765738;
}

.material-card-visual.glass {
  background: linear-gradient(145deg, #d9f0ec, #afdcd3);
  color: #217a70;
}

.material-card-visual.paper {
  background: linear-gradient(145deg, #f2ead8, #e6d5b4);
  color: #80653b;
}

.material-card-ring {
  position: absolute;
  width: 205px;
  height: 205px;
  border: 1px solid rgba(255,255,255,.65);
  border-radius: 50%;
}

.material-card-icon {
  position: relative;
  z-index: 2;
  width: 92px;
  height: 92px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.55);
  border-radius: 27px;
  background: rgba(255,255,255,.38);
  box-shadow: 0 20px 40px rgba(0,0,0,.07);
  backdrop-filter: blur(8px);
}

.material-card-visual > span {
  position: absolute;
  left: 22px;
  bottom: 18px;
  color: rgba(20, 63, 45, .45);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .18em;
}

.material-card-body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 30px;
}

.material-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #79a18b;
  font-size: 9px;
  font-weight: 800;
}

.material-card-meta svg {
  color: #55a374;
}

.material-card-body h3 {
  margin: 19px 0 9px;
  color: #163f2d;
  font-size: 22px;
  letter-spacing: -.04em;
}

.material-card-body p {
  margin: 0;
  color: #77887f;
  font-size: 12px;
  line-height: 1.7;
}

.material-shop-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: fit-content;
  margin-top: 23px;
  color: #117249;
  font-size: 10px;
  font-weight: 850;
}

.categories-impact {
  width: min(1240px, calc(100% - 64px));
  min-height: 430px;
  margin: 0 auto 105px;
  padding: 65px;
  display: grid;
  grid-template-columns: 1fr .85fr;
  align-items: center;
  gap: 60px;
  overflow: hidden;
  position: relative;
  border-radius: 30px;
  background:
    radial-gradient(circle at 75% 50%, rgba(108, 203, 137, .16), transparent 35%),
    linear-gradient(135deg, #073d2b, #0a6042);
  color: white;
}

.categories-impact-copy {
  position: relative;
  z-index: 2;
  max-width: 540px;
}

.light-label {
  color: #8ecaa1;
}

.categories-impact h2 {
  margin: 16px 0;
  font-size: clamp(36px, 4vw, 52px);
  line-height: 1;
  letter-spacing: -.055em;
}

.categories-impact h2 em {
  color: #9cddb0;
}

.categories-impact-copy > p {
  max-width: 480px;
  margin: 0;
  color: #bdd6c6;
  font-size: 13px;
  line-height: 1.8;
}

.categories-impact-button {
  margin-top: 28px;
}

.categories-impact-panel {
  position: relative;
  min-height: 290px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(210, 241, 219, .12);
  border-radius: 25px;
  background: rgba(255,255,255,.035);
  backdrop-filter: blur(10px);
}

.impact-glow {
  position: absolute;
  width: 190px;
  height: 190px;
  border-radius: 50%;
  background: rgba(115, 213, 144, .13);
  filter: blur(25px);
}

.impact-main-icon {
  position: relative;
  z-index: 2;
  width: 67px;
  height: 67px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(184, 232, 198, .2);
  border-radius: 20px;
  background: rgba(161, 225, 176, .1);
  color: #9de0b0;
}

.impact-numbers {
  position: relative;
  z-index: 2;
  display: flex;
  gap: 30px;
  margin-top: 25px;
}

.impact-numbers div {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.impact-numbers strong {
  color: #ecf9ef;
  font-size: 22px;
  letter-spacing: -.04em;
}

.impact-numbers span {
  margin-top: 4px;
  color: #83af92;
  font-size: 8px;
  font-weight: 750;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.impact-cycle {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 25px;
  color: #7fbd92;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .15em;
}

.impact-cycle i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #65a77b;
}

.categories-final-cta {
  padding: 20px 20px 120px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.final-cta-icon {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  margin-bottom: 22px;
  border-radius: 17px;
  background: #e1f2e4;
  color: #18744c;
}

.categories-final-cta .section-label {
  color: #6b8b79;
}

.categories-final-cta h2 {
  margin: 14px 0 27px;
  color: #163f2d;
  font-size: clamp(35px, 4vw, 51px);
  line-height: 1.02;
  letter-spacing: -.055em;
}

.categories-final-cta h2 em {
  color: #188053;
}

@media (max-width: 900px) {
  .categories-hero-inner {
    grid-template-columns: 1fr;
    padding-top: 20px;
  }

  .categories-hero-content {
    padding: 65px 0 20px;
  }

  .categories-visual {
    width: min(430px, 85vw);
    margin-top: -15px;
    margin-bottom: 45px;
  }

  .categories-introduction {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .categories-impact {
    grid-template-columns: 1fr;
    padding: 45px;
  }
}

@media (max-width: 700px) {
  .categories-hero-inner,
  .categories-materials,
  .categories-introduction,
  .categories-impact {
    width: calc(100% - 32px);
  }

  .categories-hero {
    min-height: auto;
  }

  .categories-hero-inner {
    min-height: auto;
  }

  .categories-hero h1 {
    font-size: clamp(43px, 12vw, 62px);
  }

  .categories-hero-buttons {
    flex-direction: column;
    align-items: stretch;
  }

  .categories-main-button,
  .categories-outline-button {
    width: 100%;
    box-sizing: border-box;
  }

  .categories-grid {
    grid-template-columns: 1fr;
  }

  .material-category-card {
    grid-template-columns: 1fr;
  }

  .material-card-visual {
    min-height: 230px;
  }

  .categories-section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
  }

  .categories-impact {
    margin-bottom: 70px;
    padding: 32px 24px;
  }

  .impact-numbers {
    gap: 20px;
  }
}

@media (max-width: 480px) {
  .categories-visual {
    width: 100%;
  }

  .category-core {
    width: 155px;
    height: 155px;
  }

  .category-core strong {
    font-size: 13px;
  }

  .material-float {
    padding: 8px 10px;
    font-size: 8px;
  }

  .float-cotton {
    left: 0;
  }

  .float-wood {
    right: 0;
  }

  .float-glass {
    left: 0;
  }

  .float-paper {
    right: 0;
  }

  .categories-introduction {
    padding-top: 75px;
  }

  .categories-final-cta {
    padding-bottom: 80px;
  }
}

