}

.cart-item-info > span {
  color: #79a18a;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.cart-item-info h3 {
  margin: 8px 0 5px;
  color: #173f2d;
  font-size: 17px;
  letter-spacing: -.035em;
}

.cart-item-info p {
  margin: 0;
  color: #829087;
  font-size: 10px;
}

.cart-item-actions {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-top: 19px;
}

.quantity-control {
  display: flex;
  align-items: center;
  height: 32px;
  border: 1px solid #dce8df;
  border-radius: 9px;
  overflow: hidden;
}

.quantity-control button {
