  color: #547265;
}

.quantity-control button:hover {
  background: #edf6ef;
  color: #0c704b;
}

.quantity-control strong {
  width: 29px;
  text-align: center;
  color: #244d3b;
  font-size: 10px;
}

.remove-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 0;
  background: transparent;
  color: #8b9890;
  font-size: 9px;
  font-weight: 750;
}

.remove-item:hover {
  color: #a94e4e;
}

.cart-item-price {
  align-self: start;
  color: #153f2c;
  font-size: 15px;
