}

.cart-benefits {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 17px;
}

.cart-benefits > div {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 16px;
  border: 1px solid rgba(24, 73, 46, .07);
  border-radius: 14px;
  background: #edf6ee;
}

.cart-benefits svg {
  flex-shrink: 0;
  color: #31835a;
}

.cart-benefits strong,
.cart-benefits span {
  display: block;
}

.cart-benefits strong {
  color: #285641;
  font-size: 9px;
}

.cart-benefits span {
  margin-top: 3px;
  color: #829289;
  font-size: 8px;
}

.cart-summary {
  position: sticky;
  top: 100px;
  padding: 25px;
  border: 1px solid rgba(24, 73, 46, .08);
  border-radius: 22px;
  background: white;
  box-shadow: 0 20px 55px rgba(23, 63, 45, .07);
}

.summary-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 20px;
  border-bottom: 1px solid #edf1ed;
  color: #557164;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .13em;
}

.summary-top svg {
  color: #218157;
}

.promo-box {
  padding: 18px 0;
  border-bottom: 1px solid #edf1ed;
}

.promo-heading {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #5d7669;
  font-size: 9px;
  font-weight: 800;
}

.promo-heading svg {
  color: #278359;
}

.promo-input {
  display: flex;
  gap: 7px;
  margin-top: 11px;
}

.promo-input input {
  min-width: 0;
  flex: 1;
  height: 37px;
  padding: 0 11px;
  border: 1px solid #dce8df;
  border-radius: 9px;
  outline: none;
  color: #234c3a;
  background: #fafcf9;
  font-size: 10px;
}

.promo-input input:focus {
  border-color: #8fc5a0;
}

.promo-input button {
  height: 37px;
  padding: 0 12px;
  border: 0;
  border-radius: 9px;
  background: #e3f2e6;
  color: #147249;
  font-size: 9px;
  font-weight: 850;
}

.promo-success {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 8px;
  color: #31835a;
  font-size: 8px;
  font-weight: 750;
}

.summary-lines {
  display: grid;
  gap: 13px;
  padding: 19px 0;
}

.summary-lines > div,
.summary-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.summary-lines span {
  color: #7c8c83;
  font-size: 10px;
}

.summary-lines strong {
  color: #365849;
  font-size: 10px;
}

.discount-line span,
.discount-line strong {
  color: #2d885b;
}

.summary-total {
  padding: 18px 0;
  border-top: 1px solid #edf1ed;
}

.summary-total span {
  color: #385b4a;
  font-size: 11px;
  font-weight: 800;
}

.summary-total strong {
  color: #123d2a;
  font-size: 24px;
  letter-spacing: -.04em;
}

.checkout-button,
.cart-primary-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 47px;
  border-radius: 11px;
  background: #0a573b;
  color: white;
  font-size: 10px;
  font-weight: 850;
  box-shadow: 0 12px 25px rgba(10,87,59,.14);
  transition: .2s ease;
}

.checkout-button:hover,
.cart-primary-button:hover {
  background: #087049;
  transform: translateY(-1px);
}

.secure-checkout {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 13px;
  color: #8b9990;
  font-size: 8px;
}

.secure-checkout svg {
  color: #439568;
}

.empty-cart {
  padding: 70px 30px;
  border: 1px dashed #cdded2;
  border-radius: 20px;
  background: rgba(255,255,255,.65);
  text-align: center;
}

.empty-cart-icon {
  width: 70px;
  height: 70px;
  display: grid;
  place-items: center;
  margin: 0 auto 18px;
  border-radius: 22px;
  background: #e4f2e6;
  color: #2b8055;
}

.empty-cart h3 {
  margin: 0;
  color: #173f2d;
  font-size: 21px;
}

.empty-cart p {
  max-width: 380px;
  margin: 9px auto 22px;
  color: #819087;
  font-size: 11px;
  line-height: 1.7;
}

.empty-cart .cart-primary-button {
  width: fit-content;
  margin: auto;
  padding: 0 18px;
}

.cart-bottom {
  width: min(1240px, calc(100% - 64px));
  margin: 0 auto;
  padding: 25px 0 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #e5ebe6;
}

.cart-back-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #4f7060;
  font-size: 9px;
  font-weight: 800;
}

.cart-bottom > div {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.cart-bottom > div span {
  color: #81a18d;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .18em;
}

.cart-bottom > div strong {
  margin-top: 4px;
  color: #315946;
  font-size: 10px;
}

@media (max-width: 950px) {
  .cart-hero-inner {
    grid-template-columns: 1fr;
  }

  .cart-hero-inner > div:first-child {
    padding-bottom: 20px;
  }

  .cart-hero-art {
    margin-bottom: 40px;
  }

  .cart-content {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .cart-summary {
    position: static;
  }
}

@media (max-width: 700px) {
  .cart-hero-inner,
  .cart-content,
  .cart-bottom {
    width: calc(100% - 32px);
  }

  .cart-hero h1 {
    font-size: 48px;
  }

  .cart-hero-art {
    width: 290px;
    height: 260px;
  }

  .ring-one {
    width: 240px;
    height: 240px;
  }

  .ring-two {
    width: 160px;
    height: 160px;
  }

  .cart-item {
    grid-template-columns: 95px 1fr;
    gap: 15px;
  }

  .cart-item-visual {
    height: 105px;
  }

  .cart-item-price {
    position: absolute;
    top: 17px;
    right: 17px;
  }

  .cart-item-info h3 {
    padding-right: 65px;
  }

  .cart-benefits {
    grid-template-columns: 1fr;
  }

  .cart-section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .cart-summary {
    padding: 20px;
  }
}

@media (max-width: 480px) {
  .cart-hero-inner > div:first-child {
    padding-top: 55px;
  }

  .cart-art-label {
    font-size: 6px;
  }

  .cart-item {
    grid-template-columns: 78px 1fr;
    padding: 12px;
  }

  .cart-item-visual {
    height: 90px;
  }

  .cart-item-visual-circle {
    width: 55px;
    height: 55px;
  }

  .cart-item-actions {
    gap: 10px;
  }

  .remove-item {
    font-size: 8px;
  }

  .cart-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .cart-bottom > div {
    align-items: flex-start;
  }
}

/* =========================================================
   AUTH PAGES
   ========================================================= */

.auth-page {
  min-height: calc(100vh - 76px);
  display: grid;
  grid-template-columns: 1.02fr .98fr;
  background: #f7faf5;
}

.auth-visual {
  position: relative;
  min-height: 760px;
  overflow: hidden;
  padding: 35px 55px;
  background:
    radial-gradient(circle at 72% 45%, rgba(104, 207, 133, .18), transparent 30%),
    linear-gradient(145deg, #063b29, #086247);
  color: white;
}

.auth-brand {
  position: relative;
  z-index: 5;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: white;
  font-size: 20px;
  font-weight: 900;
  letter-spacing: -.055em;
}

.auth-brand > span:first-child {
  width: 37px;
  height: 37px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: rgba(232,247,235,.12);
  color: #a9dfb5;
}

.auth-brand > span:last-child {
  color: #8ed4a1;
}

.auth-visual-content {
  position: absolute;
  width: 410px;
  height: 410px;
  right: 8%;
  top: 50%;
  transform: translateY(-57%);
}

.auth-orbit {
  position: absolute;
  left: 50%;
  top: 50%;
  border: 1px solid rgba(188, 235, 200, .19);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.auth-orbit-one {
  width: 100%;
  height: 100%;
}

.auth-orbit-two {
  width: 64%;
  height: 64%;
}

.auth-leaf-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 145px;
  height: 145px;
  display: grid;
  place-items: center;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(207, 242, 216, .18);
  border-radius: 42px;
  background: rgba(151, 221, 169, .08);
  color: #a5ddb1;
  box-shadow: 0 30px 80px rgba(0,0,0,.2);
  backdrop-filter: blur(12px);
}

.auth-floating-card {
  position: absolute;
  z-index: 4;
  display: flex;
  flex-direction: column;
  padding: 13px 15px;
  border: 1px solid rgba(220, 247, 226, .13);
  border-radius: 13px;
  background: rgba(5, 67, 44, .72);
  box-shadow: 0 18px 35px rgba(0,0,0,.15);
  backdrop-filter: blur(10px);
}

.auth-floating-card strong {
  color: #e8f7eb;
  font-size: 15px;
}

.auth-floating-card span {
  margin-top: 3px;
  color: #8dbb9b;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.auth-float-top {
  top: 8%;
  left: 5%;
}

.auth-float-bottom {
  right: 4%;
  bottom: 9%;
}

.auth-visual-copy {
  position: absolute;
  z-index: 4;
  left: 55px;
  right: 40px;
  bottom: 50px;
  max-width: 470px;
}

.auth-visual-copy > span {
  color: #83c399;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .18em;
}

.auth-visual-copy h1 {
  margin: 13px 0;
  font-size: clamp(35px, 4vw, 52px);
  line-height: 1;
  letter-spacing: -.06em;
}

.auth-visual-copy h1 em {
  color: #9bdcaf;
  font-family: "Playfair Display", serif;
  font-weight: 600;
}

.auth-visual-copy p {
  max-width: 420px;
  margin: 0;
  color: #b9d5c4;
  font-size: 11px;
  line-height: 1.8;
}

.auth-form-section {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 65px 45px;
}

.auth-form-wrap {
  width: min(410px, 100%);
}

.auth-mobile-brand {
  display: none;
}

.auth-heading {
  margin-bottom: 30px;
}

.auth-form-label {
  color: #278056;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .18em;
}

.auth-heading h2 {
  margin: 10px 0 7px;
  color: #153f2d;
  font-size: 37px;
  line-height: 1;
  letter-spacing: -.055em;
}

.auth-heading p {
  margin: 0;
  color: #7a8b82;
  font-size: 11px;
  line-height: 1.7;
}

.auth-form {
  display: grid;
  gap: 17px;
}

.auth-form > label {
  display: grid;
  gap: 7px;
  color: #4c695a;
  font-size: 9px;
  font-weight: 800;
}

.auth-input {
  height: 45px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid #dce7df;
  border-radius: 11px;
  background: white;
  color: #6d8578;
  transition: .2s ease;
}

.auth-input:focus-within {
  border-color: #91c6a0;
  box-shadow: 0 0 0 3px rgba(58, 145, 87, .07);
}

.auth-input input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: #214b38;
  font-size: 10px;
}

.auth-input input::placeholder {
  color: #a1ada6;
}

.auth-input button {
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  color: #82948b;
}

.auth-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: -2px;
}

.remember-option,
.terms-option {
  display: flex !important;
  align-items: center;
  gap: 7px;
  color: #7b8c83 !important;
  font-size: 8px !important;
  font-weight: 650 !important;
}

.remember-option input,
.terms-option input {
  accent-color: #14774d;
}

.forgot-button {
  padding: 0;
  border: 0;
  background: transparent;
  color: #218055;
  font-size: 8px;
  font-weight: 800;
}

.auth-submit {
  min-height: 47px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 4px;
  border: 0;
  border-radius: 11px;
  background: #0a573b;
  color: white;
  font-size: 10px;
  font-weight: 850;
  box-shadow: 0 13px 28px rgba(10,87,59,.13);
  transition: .2s ease;
}

.auth-submit:hover {
  background: #087049;
  transform: translateY(-1px);
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 24px 0 14px;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: #e7ece8;
}

.auth-divider span {
  color: #a2ada7;
  font-size: 7px;
  font-weight: 850;
}

.auth-demo-button {
  width: 100%;
  min-height: 44px;
  border: 1px solid #dce7df;
  border-radius: 11px;
  background: white;
  color: #446657;
  font-size: 9px;
  font-weight: 800;
}

.auth-switch {
  margin: 22px 0 0;
  color: #7e8d85;
  text-align: center;
  font-size: 9px;
}

.auth-switch a {
  color: #16764d;
  font-weight: 850;
}

.auth-terms {
  margin: 19px auto 0;
  max-width: 330px;
  color: #a0aaa4;
  text-align: center;
  font-size: 7px;
  line-height: 1.7;
}

.terms-option {
  align-items: flex-start !important;
  margin-top: -1px;
  line-height: 1.5;
}

.register-page .auth-form {
  gap: 14px;
}

