/* =========================================================
   GREENCORE — GLOBAL VISUAL POLISH
   Premium Forest / Emerald Design System
   ========================================================= */

:root {
  --rp-forest-950: #062c1e;
  --rp-forest-900: #073b29;
  --rp-forest-800: #09563a;
  --rp-forest-700: #08734b;
  --rp-emerald: #12945f;
  --rp-emerald-light: #55c486;
  --rp-mint: #dff4e5;
  --rp-mint-soft: #edf8ef;
  --rp-cream: #f8fbf6;
  --rp-white: #ffffff;
  --rp-text: #123b2a;
  --rp-text-soft: #557064;
  --rp-muted: #72857a;
  --rp-border: #dce9df;
  --rp-shadow: 0 18px 55px rgba(9, 65, 42, .09);
}

/* ---------- GLOBAL ---------- */

html {
  scroll-behavior: smooth;
}

body {
  background:
    radial-gradient(circle at 8% 0%, rgba(118, 205, 143, .08), transparent 23%),
    var(--rp-cream);
  color: var(--rp-text);
}

* {
  box-sizing: border-box;
}

::selection {
  background: var(--rp-emerald);
  color: white;
}

/* ---------- TYPOGRAPHY ---------- */

h1,
h2,
h3,
h4,
p {
  text-wrap: balance;
}

h1,
h2,
h3 {
  color: var(--rp-text);
}

p {
  color: var(--rp-text-soft);
}

button,
a,
input {
  -webkit-tap-highlight-color: transparent;
}

/* ---------- GLOBAL NAVBAR IMPROVEMENT ---------- */

.site-navbar {
  background: rgba(248, 251, 246, .94);
  border-bottom: 1px solid rgba(17, 76, 48, .09);
  box-shadow: 0 4px 25px rgba(15, 66, 43, .035);
}

.site-navbar-inner {
  width: min(1280px, calc(100% - 56px));
  min-height: 78px;
}

.site-brand {
  font-size: 23px;
  letter-spacing: -.065em;
  color: var(--rp-forest-950);
}

.site-brand-mark {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: linear-gradient(145deg, var(--rp-forest-800), var(--rp-emerald));
  box-shadow: 0 9px 25px rgba(9, 115, 75, .2);
}

.site-nav {
  gap: 5px;
}

.site-nav-link {
  padding: 11px 15px;
  color: #587166;
  font-size: 12px;
  font-weight: 750;
