  margin-right: auto;
}

.home-section h2 {
  font-size: clamp(38px, 4.5vw, 58px);
  line-height: 1.02;
  letter-spacing: -.06em;
}

.home-section p {
  font-size: 14px;
  line-height: 1.8;
}

/* ---------- SHOP ---------- */

.shop-page {
  background:
    radial-gradient(circle at 95% 5%, rgba(104, 201, 133, .07), transparent 20%),
