}

.material-card-body {
  padding: 34px;
}

.material-card-body h3 {
  font-size: 23px;
  line-height: 1.2;
}

.material-card-body p {
  font-size: 12px;
  line-height: 1.75;
}

.categories-impact {
  width: min(1280px, calc(100% - 56px));
  background:
    radial-gradient(circle at 78% 45%, rgba(106, 213, 139, .17), transparent 31%),
    linear-gradient(135deg, #052f20, #08754c);
}

.categories-impact h2 {
  font-size: clamp(40px, 4.5vw, 58px);
}

/* =========================================================
   CART
   ========================================================= */

.cart-page {
  background:
    radial-gradient(circle at 4% 15%, rgba(99, 196, 128, .06), transparent 22%),
    var(--rp-cream);
}

.cart-hero {
  background:
    radial-gradient(circle at 78% 48%, rgba(108, 211, 140, .19), transparent 30%),
    linear-gradient(135deg, #052f20, #08734b);
}

.cart-hero h1 {
  font-size: clamp(52px, 6vw, 74px);
}

.cart-hero p {
  font-size: 14px;
}

.cart-content {
  width: min(1280px, calc(100% - 56px));
  gap: 70px;
}

.cart-section-heading h2 {
  font-size: 32px;
}

.cart-item {
  min-height: 170px;
  border-color: rgba(18, 70, 44, .09);
  border-radius: 20px;
}

.cart-item-info h3 {
  font-size: 18px;
}

.cart-item-info p {
  font-size: 10px;
}

.cart-item-price {
  font-size: 17px;
}

.cart-summary {
  border-color: rgba(18, 70, 44, .09);
  box-shadow: 0 20px 55px rgba(17, 66, 43, .09);
}

.summary-total strong {
  color: var(--rp-forest-800);
  font-size: 26px;
}

/* =========================================================
   AUTH
   ========================================================= */

.auth-page {
  background: var(--rp-cream);
}

.auth-visual {
  background:
    radial-gradient(circle at 72% 43%, rgba(107, 215, 139, .2), transparent 29%),
    linear-gradient(145deg, #052f20, #08734b);
}

.auth-heading h2 {
  font-size: 40px;
  color: var(--rp-text);
}

.auth-heading p {
  font-size: 12px;
}

.auth-form > label {
  font-size: 10px;
}

.auth-input {
  height: 49px;
  border-color: #d5e4da;
}

.auth-input input {
  font-size: 11px;
}

.auth-submit {
  min-height: 50px;
  font-size: 11px;
}

.auth-switch {
  font-size: 10px;
}

.auth-terms {
  font-size: 8px;
}

/* =========================================================
   SEARCH
   ========================================================= */

.navbar-search {
  width: min(500px, calc(100vw - 32px));
  height: 54px;
  border-color: #d4e3d9;
  box-shadow: 0 20px 55px rgba(12, 66, 42, .16);
}

.navbar-search input {
  font-size: 11px;
}

.navbar-search button {
  height: 40px;
  padding: 0 16px;
  background: linear-gradient(135deg, var(--rp-forest-800), var(--rp-emerald));
  font-size: 9px;
}

/* =========================================================
   GLOBAL RESPONSIVE ALIGNMENT
   ========================================================= */

@media (max-width: 1100px) {
  .site-navbar-inner,
  .home-section,
  .home-content,
  .home-container,
  .categories-materials,
  .categories-impact,
  .cart-content,
  .cart-bottom {
    width: calc(100% - 40px);
  }

  .categories-introduction {
    width: calc(100% - 40px);
  }
}

@media (max-width: 850px) {
  .site-navbar-inner {
    min-height: 70px;
  }

  .home-hero,
  .categories-hero,
  .cart-hero {
    min-height: auto;
  }

  .home-hero h1,
  .categories-hero h1,
  .cart-hero h1 {
    font-size: clamp(46px, 11vw, 66px);
  }

  .navbar-search {
    top: 74px;
  }
}

@media (max-width: 700px) {
  .site-navbar-inner,
  .home-section,
  .home-content,
  .home-container,
  .categories-materials,
  .categories-impact,
  .categories-introduction,
  .cart-content,
  .cart-bottom {
    width: calc(100% - 30px);
  }

  .categories-section-heading,
  .cart-section-heading {
    align-items: flex-start;
  }

  .categories-section-heading h2,
  .cart-section-heading h2 {
    font-size: 28px;
  }

  .material-card-body {
    padding: 25px;
  }

  .cart-summary {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .site-navbar-inner {
    width: calc(100% - 24px);
  }

  .site-brand {
    font-size: 20px;
  }

  .site-brand-mark {
    width: 36px;
    height: 36px;
  }

  .home-hero h1,
  .categories-hero h1,
  .cart-hero h1 {
    font-size: 45px;
  }

  .home-hero p,
  .categories-hero-content > p,
  .cart-hero p {
    font-size: 13px;
  }

  .categories-main-button,
  .categories-outline-button,
  .cart-primary-button,
  .checkout-button,
  .auth-submit {
    min-height: 49px;
  }

  .auth-heading h2 {
    font-size: 34px;
  }
}

/* =========================================================
   GREENCORE — DEEP DARK GREEN THEME
   ========================================================= */

:root {
  --rp-bg: #031b12;
  --rp-bg-2: #05271a;
  --rp-bg-3: #073723;
  --rp-surface: #092f20;
  --rp-surface-2: #0c3b28;
  --rp-surface-3: #104a31;

  --rp-green: #19a765;
  --rp-green-bright: #35c979;
  --rp-green-soft: #8be3a8;

  --rp-text: #f0fff4;
  --rp-text-2: #c4ddcc;
  --rp-text-3: #88a996;

  --rp-border: rgba(130, 211, 157, .16);
  --rp-border-strong: rgba(130, 211, 157, .28);

  --rp-shadow: 0 25px 70px rgba(0, 0, 0, .32);
}

/* =========================================================
   GLOBAL
   ========================================================= */

html,
body,
#root {
  background: var(--rp-bg) !important;
  color: var(--rp-text);
}

body {
  background:
    radial-gradient(
      circle at 10% 0%,
      rgba(24, 167, 101, .09),
      transparent 25%
    ),
    radial-gradient(
      circle at 90% 30%,
      rgba(53, 201, 121, .05),
      transparent 25%
    ),
    var(--rp-bg) !important;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--rp-text);
}

p {
  color: var(--rp-text-2);
}

a {
  color: inherit;
}

