   Brighter than dark mode, richer than light mode
   ========================================================= */

:root {
  --rp-bg: #0b3d2b;
  --rp-bg-soft: #10533a;
  --rp-bg-light: #eaf5ed;

  --rp-surface: #123f2e;
  --rp-surface-light: #f4faf5;
  --rp-surface-green: #dcefe2;

  --rp-emerald: #18a968;
