/* =========================================================
   GREENCORE — GLOBAL FOOTER
   ========================================================= */

.site-footer {
  position: relative;
  overflow: hidden;
  margin-top: 0;
  background:
    radial-gradient(circle at 82% 18%, rgba(56, 200, 121, 0.16), transparent 28%),
    linear-gradient(135deg, #073a28 0%, #0a4d35 48%, #0d6543 100%);
  color: #e9f8ed;
}

.site-footer::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  right: -180px;
  bottom: -250px;
  border-radius: 50%;
  background: rgba(82, 214, 137, 0.1);
  filter: blur(10px);
  pointer-events: none;
}

.site-footer-main {
  position: relative;
  z-index: 1;
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 76px 0 58px;
  display: grid;
  grid-template-columns: 1.8fr 0.8fr 0.8fr 1.35fr;
  gap: 58px;
}

.site-footer-brand {
  max-width: 360px;
}

.site-footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: #f5fff7;
  font-size: 25px;
  font-weight: 900;
  letter-spacing: -0.8px;
}

.site-footer-logo > span:last-child > span {
  color: #5cda91;
}

.site-footer-logo-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #66df99;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.12);
}

.site-footer-description {
  margin: 22px 0 25px;
  color: rgba(233, 248, 237, 0.74);
  font-size: 14px;
  line-height: 1.8;
}

.site-footer-location,
.site-footer-email {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 12px;
  color: rgba(233, 248, 237, 0.7);
  font-size: 13px;
}

.site-footer-email {
  transition: color 180ms ease;
}

.site-footer-email:hover {
  color: #70e39e;
}

.site-footer-column {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.site-footer-column h3 {
  margin: 3px 0 22px;
  color: #f4fff7;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.site-footer-column > a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 14px;
  color: rgba(233, 248, 237, 0.7);
  font-size: 14px;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.site-footer-column > a:hover {
  color: #75e5a2;
  transform: translateX(3px);
}

.site-footer-impact {
  padding: 23px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.055);
  backdrop-filter: blur(14px);
}

.site-footer-impact-icon {
  width: 45px;
  height: 45px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  color: #64dc95;
  background: rgba(84, 216, 137, 0.13);
}

.site-footer-impact h3 {
