  border-radius: 22px;
  background: rgba(255, 255, 255, 0.055);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
  backdrop-filter: blur(15px);
}

.rp-footer-impact-icon {
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  margin-bottom: 13px;
  border-radius: 12px;
  color: #70e19b;
  background: rgba(76, 220, 133, 0.11);
}

.rp-footer-impact-label {
  display: block;
  margin-bottom: 7px;
  color: #71df9d;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.rp-footer-impact h3 {
  margin: 0;
  color: #f2fff6;
  font-size: 20px;
  letter-spacing: -0.5px;
}

.rp-footer-impact p {
  margin: 8px 0 17px;
  color: rgba(239, 255, 244, 0.56);
  font-size: 12px;
  line-height: 1.7;
}

.rp-footer-impact-tags {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.rp-footer-impact-tags span {
  padding: 5px 7px;
  border-radius: 7px;
  color: rgba(235, 255, 241, 0.65);
  background: rgba(255, 255, 255, 0.06);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

/* Bottom */

.rp-footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 48px;
  padding-top: 20px;
  border-top: 1px solid rgba(218, 255, 229, 0.1);
  color: rgba(239, 255, 244, 0.4);
  font-size: 10px;
}

.rp-footer-socials {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rp-footer-socials a {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(211, 255, 225, 0.1);
  border-radius: 50%;
  color: rgba(239, 255, 244, 0.57);
  background: rgba(255, 255, 255, 0.045);
  transition: all 180ms ease;
}

.rp-footer-socials a:hover {
  color: #063b29;
  background: #78e6a4;
  transform: translateY(-2px);
}

/* Responsive */

@media (max-width: 980px) {
  .rp-footer-grid {
    grid-template-columns: 1.4fr 0.8fr 0.8fr;
    gap: 40px;
  }

  .rp-footer-impact {
    grid-column: 1 / -1;
  }
}

@media (max-width: 700px) {
  .rp-footer-container {
    width: min(100% - 30px, 560px);
    padding-top: 38px;
  }

  .rp-footer-cta {
    grid-template-columns: auto 1fr;
    padding: 22px;
  }

  .rp-footer-cta-button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .rp-footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 34px 25px;
  }

  .rp-footer-brand,
  .rp-footer-impact {
    grid-column: 1 / -1;
  }

  .rp-footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 450px) {
  .rp-footer-grid {
    grid-template-columns: 1fr;
  }

  .rp-footer-cta {
    grid-template-columns: 1fr;
  }

  .rp-footer-cta-icon {
    width: 43px;
    height: 43px;
  }
}


/* =========================================================
   AUTH PAGES — COMPACT FOOTER
   ========================================================= */

.rp-footer-compact .rp-footer-container {
  padding: 30px 0 18px;
}

.rp-footer-compact .rp-footer-grid {
  grid-template-columns: 1.8fr 0.8fr 0.8fr;
  gap: 45px;
  align-items: center;
}

.rp-footer-compact .rp-footer-brand-description,
.rp-footer-compact .rp-footer-contact {
  display: none;
}

.rp-footer-compact .rp-footer-logo {
  font-size: 21px;
}

.rp-footer-compact .rp-footer-logo-mark {
  width: 37px;
  height: 37px;
  border-radius: 11px;
}

.rp-footer-compact .rp-footer-heading {
  margin: 0 0 12px;
}

.rp-footer-compact .rp-footer-links a {
  margin-bottom: 8px;
  font-size: 12px;
}

.rp-footer-compact .rp-footer-bottom {
  margin-top: 25px;
  padding-top: 15px;
}

.rp-footer-compact .rp-footer-socials a {
  width: 29px;
  height: 29px;
}

@media (max-width: 700px) {
  .rp-footer-compact .rp-footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 25px;
  }

  .rp-footer-compact .rp-footer-brand {
    grid-column: 1 / -1;
  }

  .rp-footer-compact .rp-footer-container {
    padding-top: 25px;
  }
}

@media (max-width: 450px) {
  .rp-footer-compact .rp-footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

/* =========================================================
   GREENCORE — CHECKOUT
   ========================================================= */

.checkout-page {
  min-height: 100vh;
  background: #eaf5ed;
  color: #174632;
}

.checkout-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  padding: 68px max(20px, calc((100% - 1180px) / 2)) 46px;
  color: #f4fff7;
  background:
    radial-gradient(circle at 86% 20%, rgba(91, 224, 145, 0.2), transparent 28%),
    linear-gradient(135deg, #0a3a29, #0d6745);
}

.checkout-kicker {
  display: block;
  margin-bottom: 12px;
  color: #71dfa0;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.18em;
}

.checkout-hero h1 {
  margin: 0;
  font-size: clamp(34px, 5vw, 57px);
  line-height: 0.98;
  letter-spacing: -2px;
}

.checkout-hero p {
  margin: 15px 0 0;
  max-width: 570px;
  color: rgba(244, 255, 247, 0.67);
  font-size: 14px;
  line-height: 1.7;
}

.checkout-secure-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border: 1px solid rgba(210, 255, 226, 0.15);
  border-radius: 999px;
  color: #c8f5d8;
  background: rgba(255, 255, 255, 0.07);
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.checkout-content {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 42px 0 75px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  gap: 30px;
  align-items: start;
}

.checkout-main {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.checkout-section,
.checkout-summary {
  border: 1px solid #d8e9dd;
  border-radius: 24px;
  background: #f8fcf9;
  box-shadow: 0 12px 35px rgba(22, 70, 50, 0.055);
}

.checkout-section {
  padding: 28px;
}

.checkout-section-heading {
  display: flex;
  gap: 15px;
  align-items: flex-start;
  margin-bottom: 25px;
}

.checkout-step {
  width: 35px;
  height: 35px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: #0b6844;
  background: #dff2e5;
  font-size: 10px;
  font-weight: 900;
}

.checkout-section-heading h2 {
  margin: 0;
  color: #164a35;
  font-size: 19px;
  letter-spacing: -0.4px;
}

.checkout-section-heading p {
  margin: 5px 0 0;
  color: #789183;
  font-size: 12px;
}

.checkout-fields {
  display: grid;
  gap: 17px;
}

.checkout-fields-two {
  grid-template-columns: 1fr 1fr;
}

.checkout-fields-three {
  display: grid;
  grid-template-columns: 1.1fr 1fr 0.7fr;
  gap: 15px;
}

.checkout-section label {
  display: grid;
  gap: 8px;
  color: #466958;
  font-size: 11px;
  font-weight: 800;
}

.checkout-section input {
  width: 100%;
  box-sizing: border-box;
  min-height: 47px;
  padding: 0 14px;
  border: 1px solid #d6e6da;
  border-radius: 12px;
  outline: none;
  color: #183f2d;
  background: #ffffff;
  font-size: 13px;
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.checkout-section input::placeholder {
  color: #a7b9ad;
}

.checkout-section input:focus {
  border-color: #31aa70;
  box-shadow: 0 0 0 3px rgba(49, 170, 112, 0.1);
}

.checkout-payment-options {
  display: grid;
  gap: 10px;
}

.checkout-payment-option {
  width: 100%;
  min-height: 69px;
  display: grid;
  grid-template-columns: 27px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 13px 15px;
  border: 1px solid #dce9df;
  border-radius: 15px;
  color: #557261;
  background: #ffffff;
  text-align: left;
  transition: all 180ms ease;
}

.checkout-payment-option:hover {
  border-color: #9ed3b4;
}

.checkout-payment-option.active {
  border-color: #3ab277;
  background: #f0faf3;
  box-shadow: inset 0 0 0 1px rgba(58, 178, 119, 0.15);
}

.checkout-payment-option > svg {
  color: #168254;
}

.checkout-payment-option strong {
  display: block;
  color: #234f3a;
  font-size: 12px;
}

.checkout-payment-option small {
  display: block;
  margin-top: 3px;
  color: #8a9d91;
  font-size: 10px;
}

.checkout-upi-icon {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: #08734a;
  background: #dff4e7;
  font-size: 7px;
  font-weight: 900;
}

.checkout-radio {
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  border: 1.5px solid #bfd1c4;
  border-radius: 50%;
}

.checkout-payment-option.active .checkout-radio {
  border-color: #168254;
}

.checkout-radio span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #168254;
}

.checkout-payment-fields {
  margin-top: 15px;
  padding: 17px;
  border-radius: 15px;
  background: #eef8f1;
}

.checkout-cod-note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 15px;
  padding: 15px;
  border-radius: 13px;
  color: #50705d;
  background: #eef8f1;
  font-size: 12px;
  line-height: 1.5;
}

.checkout-cod-note svg {
  flex: 0 0 auto;
  color: #168254;
}

.checkout-trust-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.checkout-trust-row > div {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 48px;
  border: 1px solid #d8e9dd;
  border-radius: 13px;
  color: #688273;
  background: #f8fcf9;
  font-size: 10px;
  font-weight: 700;
}

.checkout-trust-row svg {
  color: #188454;
}

.checkout-recycle-icon {
  display: inline-flex;
  color: #188454;
}

.checkout-place-order {
  min-height: 55px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 0;
  border-radius: 15px;
  color: #f4fff7;
  background: linear-gradient(135deg, #087047, #16a765);
  box-shadow: 0 13px 30px rgba(12, 128, 78, 0.17);
  font-size: 13px;
  font-weight: 900;
  transition: all 180ms ease;
}

.checkout-place-order:hover {
  transform: translateY(-2px);
  box-shadow: 0 17px 34px rgba(12, 128, 78, 0.24);
}

.checkout-back {
  align-self: center;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
  color: #688273;
  background: transparent;
  font-size: 11px;
  font-weight: 800;
}

.checkout-back:hover {
  color: #087047;
}

/* Summary */

.checkout-summary {
  position: sticky;
  top: 90px;
  padding: 25px;
}

.checkout-summary-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 18px;
}

.checkout-summary-header span {
  color: #7a9183;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.15em;
}

.checkout-summary-header strong {
  color: #4f705e;
  font-size: 11px;
}

.checkout-summary-products {
  display: grid;
  gap: 14px;
}

.checkout-product {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 11px;
}

.checkout-product-visual {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #207c50;
  background: #dff0e4;
}

.checkout-product-visual.wood {
  color: #786346;
  background: #f1e9db;
}

.checkout-product-visual.glass {
  color: #377d80;
  background: #e0f0ef;
}

.checkout-product-info {
  min-width: 0;
}

.checkout-product-info strong {
  display: block;
  overflow: hidden;
  color: #244f3a;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.checkout-product-info span {
  display: block;
  margin-top: 3px;
  color: #8a9c91;
  font-size: 9px;
}

.checkout-product > strong {
  color: #28543e;
  font-size: 11px;
}

.checkout-summary-divider {
  height: 1px;
  margin: 21px 0;
  background: #e1ebe4;
}

.checkout-price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  color: #718779;
  font-size: 11px;
}

.checkout-price-row strong {
  color: #315b45;
}

.checkout-price-row.checkout-discount {
  color: #138052;
}

.checkout-price-row.checkout-discount strong {
  color: #138052;
}

.checkout-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.checkout-total span {
  color: #3f604e;
  font-size: 13px;
  font-weight: 800;
}

.checkout-total strong {
  color: #0b7047;
  font-size: 25px;
  letter-spacing: -0.7px;
}

.checkout-summary-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 23px;
  padding: 13px;
  border-radius: 12px;
  color: #587564;
  background: #eaf7ee;
  font-size: 10px;
  line-height: 1.5;
}

.checkout-summary-note svg {
  flex: 0 0 auto;
  color: #15905b;
}

/* Success */

.checkout-success {
  min-height: 70vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 70px 20px;
  text-align: center;
  background:
    radial-gradient(circle at 50% 25%, rgba(63, 190, 117, 0.12), transparent 30%),
    #eaf5ed;
}

.checkout-success-icon {
  width: 78px;
  height: 78px;
  display: grid;
  place-items: center;
  margin-bottom: 23px;
  border-radius: 25px;
  color: #f2fff6;
  background: linear-gradient(135deg, #087047, #19a867);
  box-shadow: 0 18px 40px rgba(9, 125, 76, 0.18);
}

.checkout-success h1 {
  max-width: 700px;
  margin: 0;
  color: #164b35;
  font-size: clamp(32px, 5vw, 55px);
  line-height: 1;
  letter-spacing: -2px;
}

.checkout-success > p {
  max-width: 560px;
  margin: 18px 0 0;
  color: #71887a;
  font-size: 14px;
  line-height: 1.75;
}

.checkout-order-card {
  width: min(700px, 100%);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin-top: 34px;
  overflow: hidden;
  border: 1px solid #d5e7db;
  border-radius: 18px;
  background: #dcebe1;
}

.checkout-order-card > div {
  padding: 20px 13px;
  background: #f8fcf9;
}

.checkout-order-card span {
  display: block;
  margin-bottom: 7px;
  color: #8a9c91;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.checkout-order-card strong {
  color: #27563f;
  font-size: 12px;
}

.checkout-success-actions {
  display: flex;
  gap: 10px;
  margin-top: 27px;
}

.checkout-primary-button,
.checkout-secondary-button {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 17px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 900;
}

.checkout-primary-button {
  color: #f4fff7;
  background: #087047;
}

.checkout-secondary-button {
  color: #28704e;
  border: 1px solid #c9dfd0;
  background: #f8fcf9;
}

@media (max-width: 900px) {
  .checkout-content {
    grid-template-columns: 1fr;
  }

  .checkout-summary {
    position: static;
    order: -1;
  }
}

@media (max-width: 650px) {
  .checkout-hero {
    align-items: flex-start;
    flex-direction: column;
    padding-top: 45px;
  }

  .checkout-content {
    width: min(100% - 24px, 600px);
    padding-top: 25px;
  }

  .checkout-section {
    padding: 21px;
    border-radius: 19px;
  }

  .checkout-fields-two,
  .checkout-fields-three {
    grid-template-columns: 1fr;
  }

  .checkout-trust-row {
    grid-template-columns: 1fr;
  }

  .checkout-order-card {
    grid-template-columns: 1fr;
  }

  .checkout-success-actions {
    width: 100%;
    flex-direction: column;
  }

  .checkout-primary-button,
  .checkout-secondary-button {
    width: 100%;
  }
}


/* =========================================================
   SHOP — ADD TO CART
   ========================================================= */

.shop-add-cart {
  width: 100%;
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin-top: 14px;
  border: 0;
  border-radius: 11px;
  color: #f4fff7;
  background: linear-gradient(135deg, #087047, #18a967);
  font-size: 11px;
  font-weight: 900;
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    background 180ms ease;
}

.shop-add-cart:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #09623f, #20b873);
  box-shadow: 0 10px 23px rgba(10, 127, 76, 0.18);
}

.shop-add-cart:active {
  transform: translateY(0);
}

.nav-cart-button {
  position: relative;
}

.nav-cart-count {
  min-width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  padding: 0 3px;
  position: absolute;
  top: -5px;
  right: -5px;
  border: 2px solid #0a3a29;
  border-radius: 999px;
  color: #ffffff;
  background: #19a967;
  font-size: 8px;
  font-weight: 900;
  line-height: 1;
}

/* =========================================================
   GREENCORE — CART PAGE PREMIUM UI
   ========================================================= */

.cart-page {
  min-height: 100vh;
  background: var(--rp-bg-light, #eaf5ed);
  color: var(--rp-dark-text, #174632);
}

.cart-container {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}

/* ---------- HERO ---------- */

.cart-hero {
  position: relative;
  overflow: hidden;
  padding: 42px 0 58px;
  background:
    radial-gradient(circle at 85% 20%, rgba(56, 200, 121, 0.22), transparent 30%),
    linear-gradient(135deg, #073d2b 0%, #09613f 55%, #0d8051 100%);
  color: #f5fff7;
}

.cart-hero-glow {
  position: absolute;
  width: 360px;
  height: 360px;
  right: -130px;
  top: -190px;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 50%;
  box-shadow:
    0 0 0 80px rgba(255,255,255,.025),
    0 0 0 160px rgba(255,255,255,.018);
  pointer-events: none;
}

.cart-back-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 38px;
  color: rgba(245,255,247,.72);
  font-size: 12px;
  font-weight: 700;
  transition: color .2s ease, transform .2s ease;
}

.cart-back-link:hover {
  color: #fff;
  transform: translateX(-3px);
}

.cart-hero-copy {
  max-width: 760px;
}

.cart-eyebrow,
.cart-section-label {
  margin: 0 0 10px;
  color: #42d38a;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.cart-hero h1 {
  margin: 0;
  max-width: 780px;
  color: #f7fff9;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(42px, 6vw, 72px);
  font-weight: 700;
  line-height: .98;
  letter-spacing: -.045em;
}

.cart-hero-copy > p:last-child {
  margin: 20px 0 0;
  max-width: 560px;
  color: rgba(245,255,247,.72);
  font-size: 15px;
  line-height: 1.7;
}

/* ---------- MAIN ---------- */

.cart-main {
  padding: 62px 0 70px;
}

.cart-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  align-items: start;
  gap: 34px;
}

.cart-items-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.cart-items-heading h2 {
  margin: 0;
  color: #174632;
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -.035em;
}

.cart-clear-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #cfe2d5;
  border-radius: 10px;
  padding: 9px 13px;
  background: rgba(255,255,255,.62);
  color: #527064;
  font-size: 11px;
  font-weight: 800;
  transition: all .2s ease;
}

.cart-clear-button:hover {
  border-color: #b8d6c2;
  background: #fff;
  color: #a34242;
}

/* ---------- ITEMS ---------- */

.cart-items-list {
  display: grid;
  gap: 14px;
}

.cart-item {
  position: relative;
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr) auto;
  align-items: center;
  gap: 22px;
  min-height: 160px;
  padding: 18px;
  overflow: hidden;
  border: 1px solid #d6e6da;
  border-radius: 20px;
  background: rgba(255,255,255,.78);
  box-shadow: 0 12px 35px rgba(20,72,46,.06);
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}

.cart-item:hover {
  transform: translateY(-2px);
  border-color: #bdd8c5;
  box-shadow: 0 18px 42px rgba(20,72,46,.10);
}

.cart-product-art {
  position: relative;
  display: flex;
  width: 116px;
  height: 116px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 15px;
  color: #14754b;
}

.cart-product-art::before {
  position: absolute;
  width: 70px;
  height: 70px;
  border: 1px solid rgba(20,117,75,.12);
  border-radius: 50%;
  content: "";
}

.cart-product-art svg {
  position: relative;
  z-index: 1;
}

.cart-product-art span {
  position: absolute;
  right: 9px;
  bottom: 8px;
  z-index: 2;
  padding: 4px 6px;
  border-radius: 6px;
  background: rgba(255,255,255,.72);
  color: #39725b;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
}

.cart-product-art.cotton {
  background: linear-gradient(145deg, #d9f2df, #b8e3c4);
}

.cart-product-art.wood {
  background: linear-gradient(145deg, #eee2cc, #d9c29e);
  color: #81633d;
}

.cart-product-art.glass {
  background: linear-gradient(145deg, #d8f2ed, #a9ddd2);
  color: #277c6d;
}

.cart-product-art.paper {
  background: linear-gradient(145deg, #eee7d2, #ded0a9);
  color: #806f43;
}

.cart-item-info {
  min-width: 0;
}

.cart-item-category {
  display: block;
  margin-bottom: 7px;
  color: #58a982;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
}

.cart-item-name {
  display: block;
  margin-bottom: 5px;
  color: #174632;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -.025em;
  transition: color .2s ease;
}

.cart-item-name:hover {
  color: #0b9a5d;
}

.cart-item-info > p {
  max-width: 440px;
  margin: 0;
  color: #779184;
  font-size: 11px;
  line-height: 1.55;
}

.cart-item-controls {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 16px;
}

.cart-quantity {
  display: inline-flex;
  align-items: center;
  overflow: hidden;
  border: 1px solid #d2e2d7;
  border-radius: 9px;
  background: #fff;
}

.cart-quantity button {
  display: grid;
  width: 31px;
  height: 30px;
  place-items: center;
  border: 0;
  background: transparent;
  color: #39725b;
}

.cart-quantity button:hover {
  background: #edf7ef;
  color: #087d4c;
}

.cart-quantity span {
  display: grid;
  min-width: 28px;
  height: 30px;
  place-items: center;
  border-right: 1px solid #dce9df;
  border-left: 1px solid #dce9df;
  color: #174632;
  font-size: 11px;
  font-weight: 800;
}

.cart-remove-button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 0;
  background: transparent;
  color: #8a9e93;
  font-size: 10px;
  font-weight: 700;
}

.cart-remove-button:hover {
  color: #a34444;
}

.cart-item-price {
  align-self: start;
  min-width: 100px;
  padding-top: 5px;
  color: #078b54;
  font-size: 17px;
  font-weight: 900;
  text-align: right;
}

.cart-item-price span {
  display: block;
  margin-top: 4px;
  color: #91a49a;
  font-size: 9px;
  font-weight: 600;
}

.cart-bottom-note {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 20px;
  color: #668578;
  font-size: 11px;
}

.cart-bottom-note svg {
  color: #17a967;
}

/* ---------- SUMMARY ---------- */

.cart-summary {
  position: sticky;
  top: 95px;
  border: 1px solid #d4e5d9;
  border-radius: 22px;
  padding: 25px;
  background: rgba(255,255,255,.86);
  box-shadow: 0 18px 48px rgba(19,70,45,.09);
}

.cart-summary-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding-bottom: 20px;
  border-bottom: 1px solid #e2ece4;
}

.cart-summary-header h2 {
  margin: 0;
  color: #174632;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -.025em;
}

.cart-summary-icon {
  display: grid;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  place-items: center;
  border: 1px solid #cce3d3;
  border-radius: 10px;
  background: #edf8f0;
  color: #078b54;
}

.cart-promo {
  padding: 20px 0;
  border-bottom: 1px solid #e2ece4;
}

.cart-promo label {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 9px;
  color: #4f6d60;
  font-size: 10px;
  font-weight: 800;
}

.cart-promo label svg {
  color: #14945c;
}

.cart-promo-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 7px;
}

.cart-promo-row input {
  min-width: 0;
  border: 1px solid #d6e5da;
  border-radius: 9px;
  outline: none;
  padding: 11px 12px;
  background: #fbfdfb;
  color: #174632;
  font-size: 10px;
}

.cart-promo-row input:focus {
  border-color: #58b887;
  box-shadow: 0 0 0 3px rgba(24,169,104,.08);
}

.cart-promo-row button {
  border: 0;
  border-radius: 9px;
  padding: 0 13px;
  background: #dff3e6;
  color: #087b4b;
  font-size: 10px;
  font-weight: 900;
}

.cart-promo-row button:hover {
  background: #ccebd7;
}

.cart-promo-success {
  margin: 8px 0 0;
  color: #0a985b;
  font-size: 9px;
  font-weight: 800;
}

.cart-summary-lines {
  padding: 17px 0 8px;
}

.cart-summary-lines > div {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  padding: 6px 0;
  color: #70867b;
  font-size: 11px;
}

.cart-summary-lines strong {
  color: #49675a;
  font-weight: 700;
}

.cart-summary-lines .cart-discount-line {
  color: #11935a;
}

.cart-summary-lines .cart-discount-line strong {
  color: #11935a;
}

.cart-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 17px 0;
  border-top: 1px solid #dfeae2;
}

.cart-total span {
  color: #174632;
  font-size: 12px;
  font-weight: 900;
}

.cart-total strong {
  color: #078b54;
  font-size: 27px;
  font-weight: 900;
  letter-spacing: -.04em;
}

.cart-checkout-button,
.cart-primary-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 10px;
  padding: 14px 17px;
  background: linear-gradient(135deg, #087d4c, #13a866);
  color: #fff;
  font-size: 11px;
  font-weight: 900;
  box-shadow: 0 10px 22px rgba(8,125,76,.20);
  transition: transform .2s ease, box-shadow .2s ease;
}

.cart-checkout-button:hover,
.cart-primary-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 28px rgba(8,125,76,.27);
}

.cart-secure-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 12px;
  color: #91a59b;
  font-size: 9px;
}

/* ---------- BENEFITS ---------- */

.cart-benefits {
  padding: 0 0 70px;
}

.cart-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.cart-benefits-grid > div {
  display: flex;
  align-items: center;
  gap: 13px;
  min-height: 76px;
  border: 1px solid #d5e6da;
  border-radius: 15px;
  padding: 15px;
  background: rgba(255,255,255,.55);
}

.cart-benefits-grid > div > svg {
  flex-shrink: 0;
  color: #14985d;
}

.cart-benefits-grid strong,
.cart-benefits-grid span {
  display: block;
}

.cart-benefits-grid strong {
  margin-bottom: 3px;
  color: #275a43;
  font-size: 11px;
  font-weight: 900;
}

.cart-benefits-grid span {
  color: #82978d;
  font-size: 9px;
}

/* ---------- EMPTY CART ---------- */

.cart-empty-page {
  display: flex;
  min-height: 65vh;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 24px;
  text-align: center;
  background:
    radial-gradient(circle at 50% 20%, rgba(56,200,121,.14), transparent 32%),
    #eaf5ed;
}

.cart-empty-icon {
  display: grid;
  width: 82px;
  height: 82px;
  margin-bottom: 25px;
  place-items: center;
  border: 1px solid #c8e2d0;
  border-radius: 24px;
  background: #dcefe2;
  color: #0b8c55;
  box-shadow: 0 18px 45px rgba(20,72,46,.08);
}

.cart-empty-page h1 {
  max-width: 650px;
  margin: 0;
  color: #174632;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(36px, 5vw, 58px);
  line-height: 1;
  letter-spacing: -.04em;
}

.cart-empty-page > p:not(.cart-eyebrow) {
  max-width: 520px;
  margin: 18px auto 28px;
  color: #71897d;
  font-size: 13px;
  line-height: 1.7;
}

.cart-primary-button {
  width: fit-content;
  min-width: 175px;
}

/* ---------- NAV CART BADGE ---------- */

.nav-cart-button {
  position: relative;
}

.nav-cart-count {
  position: absolute;
  top: -5px;
  right: -5px;
  display: grid;
  min-width: 16px;
  height: 16px;
  box-sizing: border-box;
  place-items: center;
  border: 2px solid #0a3a29;
  border-radius: 999px;
  padding: 0 3px;
  background: #36cf7f;
  color: #073b29;
  font-size: 7px;
  font-weight: 950;
  line-height: 1;
  pointer-events: none;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width: 980px) {
  .cart-layout {
    grid-template-columns: 1fr;
  }

  .cart-summary {
    position: static;
  }

  .cart-summary {
    max-width: 520px;
  }
}

@media (max-width: 700px) {
  .cart-container {
    width: min(100% - 30px, 560px);
  }

  .cart-hero {
    padding: 30px 0 45px;
  }

  .cart-back-link {
    margin-bottom: 28px;
  }

  .cart-hero h1 {
    font-size: 43px;
  }

  .cart-main {
    padding: 40px 0 50px;
  }

  .cart-items-heading {
    align-items: flex-start;
  }

  .cart-items-heading h2 {
    font-size: 25px;
  }

  .cart-item {
    grid-template-columns: 82px minmax(0, 1fr);
    gap: 14px;
    padding: 13px;
  }

  .cart-product-art {
    width: 82px;
    height: 82px;
  }

  .cart-item-price {
    position: absolute;
    right: 14px;
    top: 14px;
    min-width: 0;
    font-size: 14px;
  }

  .cart-item-info {
    padding-right: 65px;
  }

  .cart-item-name {
    font-size: 15px;
  }

  .cart-item-controls {
    flex-wrap: wrap;
    gap: 9px;
  }

  .cart-benefits-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .cart-container {
    width: min(100% - 22px, 560px);
  }

  .cart-hero h1 {
    font-size: 36px;
  }

  .cart-items-heading {
    flex-direction: column;
    gap: 12px;
  }

  .cart-item {
    grid-template-columns: 66px minmax(0, 1fr);
  }

  .cart-product-art {
    width: 66px;
    height: 66px;
    border-radius: 11px;
  }

  .cart-product-art svg {
    width: 22px;
  }

  .cart-product-art span {
    display: none;
  }

  .cart-item-info {
    padding-right: 55px;
  }

  .cart-item-info > p {
    display: none;
  }

  .cart-item-name {
    font-size: 14px;
  }

  .cart-summary {
    padding: 18px;
    border-radius: 17px;
  }
}

/* =========================================================
   PRODUCT CARD — BUY NOW + ADD TO CART
   ========================================================= */

.shop-product-actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 9px;
  margin-top: 18px;
}

.shop-buy-now,
.shop-add-cart {
  width: 100%;
  min-height: 43px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 11px;
  padding: 11px 15px;
  font-size: 11px;
  font-weight: 900;
  transition:
    transform .2s ease,
    box-shadow .2s ease,
    background .2s ease,
    border-color .2s ease;
}

.shop-buy-now {
  border: 1px solid #0b8b55;
  background: linear-gradient(135deg, #078651, #12aa67);
  color: #fff;
  box-shadow: 0 9px 20px rgba(7, 134, 81, .18);
}

.shop-buy-now:hover {
  transform: translateY(-2px);
  box-shadow: 0 13px 25px rgba(7, 134, 81, .25);
}

.shop-add-cart {
  border: 1.5px solid #15955e;
  background: #fff;
  color: #087e4d;
}

.shop-add-cart:hover {
  transform: translateY(-1px);
  background: #effaf3;
  border-color: #087e4d;
}

.shop-product-benefits {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 15px;
  border-top: 1px solid #e0ece3;
  padding-top: 13px;
}

.shop-product-benefits span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 0;
  color: #718b7e;
  font-size: 8px;
  font-weight: 700;
  white-space: nowrap;
}

.shop-product-benefits span + span {
  border-left: 1px solid #dce8df;
}

.shop-product-benefits svg {
  color: #12955b;
  flex-shrink: 0;
}

@media (max-width: 520px) {
  .shop-product-benefits span {
    font-size: 7px;
  }
}


/* =========================================================
   GREENCORE — ACCOUNT PAGE
   ========================================================= */

.account-page {
  min-height: 100vh;
  background: #eaf5ed;
  color: #174632;
}

/* ---------- HERO ---------- */

.account-hero {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 330px;
  padding: 75px max(24px, calc((100% - 1180px) / 2));
  background:
    radial-gradient(circle at 85% 20%, rgba(61, 210, 132, .24), transparent 30%),
    linear-gradient(135deg, #063c2b 0%, #08623f 55%, #0d8152 100%);
  color: #f5fff7;
}

.account-hero::after {
  position: absolute;
  width: 500px;
  height: 500px;
  right: -210px;
  top: -300px;
  border: 1px solid rgba(255,255,255,.11);
  border-radius: 50%;
  box-shadow:
    0 0 0 90px rgba(255,255,255,.025),
    0 0 0 180px rgba(255,255,255,.018);
  content: "";
  pointer-events: none;
}

.account-hero > div:first-child {
  position: relative;
  z-index: 2;
  max-width: 760px;
}

.account-kicker {
  display: block;
  margin-bottom: 13px;
  color: #48d48d;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.account-hero h1 {
  margin: 0;
  color: #f7fff9;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(44px, 6vw, 72px);
  font-weight: 700;
  line-height: .98;
  letter-spacing: -.045em;
}

.account-hero p {
  max-width: 590px;
  margin: 20px 0 0;
  color: rgba(245,255,247,.72);
  font-size: 14px;
  line-height: 1.7;
}

.account-profile-mark {
  position: relative;
  z-index: 2;
  display: grid;
  width: 82px;
  height: 82px;
  flex-shrink: 0;
  margin-left: 40px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 24px;
  background: rgba(255,255,255,.08);
  color: #74e5a8;
  box-shadow: 0 18px 45px rgba(0,0,0,.12);
}

/* ---------- CONTENT ---------- */

.account-content {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
  padding: 48px 0 70px;
}

/* ---------- PROFILE ---------- */

.account-profile-card {
  border: 1px solid #d3e5d8;
  border-radius: 22px;
  padding: 27px 30px;
  background: rgba(255,255,255,.9);
  box-shadow: 0 16px 42px rgba(19,70,45,.07);
}

.account-card-heading {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-bottom: 25px;
}

.account-card-icon {
  display: grid;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  place-items: center;
  border: 1px solid #c9e2d1;
  border-radius: 12px;
  background: #eaf7ee;
  color: #078b54;
}

.account-card-heading span {
  display: block;
  margin-bottom: 3px;
  color: #58a982;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .15em;
}

.account-card-heading h2 {
  margin: 0;
  color: #174632;
  font-size: 22px;
  font-weight: 850;
  letter-spacing: -.03em;
}

.account-profile-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-top: 1px solid #e3ece5;
}

.account-profile-grid > div {
  min-width: 0;
  padding: 20px 20px 4px 0;
}

.account-profile-grid > div + div {
  padding-left: 20px;
  border-left: 1px solid #e3ece5;
}

.account-profile-grid span {
  display: block;
  margin-bottom: 7px;
  color: #81958b;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.account-profile-grid strong {
  display: block;
  overflow-wrap: anywhere;
  color: #285b44;
  font-size: 12px;
  font-weight: 800;
}

/* ---------- ORDERS ---------- */

.account-orders {
  margin-top: 46px;
}

.account-orders-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.account-orders-heading .account-kicker {
  margin-bottom: 7px;
}

.account-orders-heading h2 {
  margin: 0;
  color: #174632;
  font-size: 30px;
  font-weight: 850;
  letter-spacing: -.04em;
}

.account-order-count {
  display: inline-flex;
  align-items: center;
  min-height: 31px;
  border: 1px solid #cfe3d5;
  border-radius: 999px;
  padding: 0 12px;
  background: #f7fbf8;
  color: #5e786b;
  font-size: 9px;
  font-weight: 900;
}

/* ---------- ORDER LIST ---------- */

.account-order-list {
  display: grid;
  gap: 12px;
}

.account-order-card {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto auto 20px;
  align-items: center;
  gap: 18px;
  min-height: 94px;
  border: 1px solid #d5e5da;
  border-radius: 17px;
  padding: 16px 20px;
  background: rgba(255,255,255,.88);
  color: inherit;
  text-decoration: none;
  box-shadow: 0 8px 28px rgba(20,72,46,.045);
  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease;
}

.account-order-card:hover {
  transform: translateY(-2px);
  border-color: #acd2ba;
  box-shadow: 0 15px 34px rgba(20,72,46,.09);
}

.account-order-icon {
  display: grid;
  width: 52px;
  height: 52px;
  place-items: center;
  border-radius: 14px;
  background: #e6f5eb;
  color: #078b54;
}

.account-order-main {
  min-width: 0;
}

.account-order-main > strong {
  display: block;
  overflow: hidden;
  color: #174632;
  font-size: 13px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-order-main > span {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 7px;
  color: #81958b;
  font-size: 9px;
}

.account-order-main > span svg {
  color: #5ca982;
}

.account-order-status {
  min-width: 105px;
}

.account-order-status > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border-radius: 999px;
  padding: 6px 9px;
  background: #eaf7ee;
  color: #078651;
  font-size: 8px;
  font-weight: 900;
  text-transform: uppercase;
}

.account-order-status > span svg {
  flex-shrink: 0;
}

.account-order-status small {
  display: block;
  margin-top: 6px;
  color: #91a39a;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.account-order-total {
  min-width: 80px;
  color: #078b54;
  font-size: 16px;
  font-weight: 900;
  text-align: right;
}

.account-order-card > svg:last-child {
  color: #78a18d;
  transition: transform .2s ease, color .2s ease;
}

.account-order-card:hover > svg:last-child {
  color: #078b54;
  transform: translateX(3px);
}

/* ---------- EMPTY / LOADING / ERROR ---------- */

.account-empty-card {
  display: flex;
  min-height: 190px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px dashed #cbded1;
  border-radius: 18px;
  padding: 30px;
  background: rgba(255,255,255,.68);
  color: #789086;
  text-align: center;
}

.account-empty-card > svg {
  margin-bottom: 10px;
  color: #15955e;
}

.account-empty-card h3 {
  margin: 5px 0 5px;
  color: #285b44;
  font-size: 17px;
  font-weight: 850;
}

.account-empty-card p {
  margin: 4px 0 18px;
  color: #81958b;
  font-size: 11px;
  line-height: 1.6;
}

.account-empty-card .checkout-primary-button {
  width: fit-content;
}

.account-error-card {
  border-style: solid;
  border-color: #e5cccc;
  background: #fff9f9;
}

.account-error-card p {
  margin: 0;
  color: #a04d4d;
}

/* ---------- LOGOUT ---------- */

.account-logout {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 48px;
  margin-top: 22px;
  border: 1px solid #d4e4d9;
  border-radius: 13px;
  background: rgba(255,255,255,.78);
  color: #637b6e;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
  transition: all .2s ease;
}

.account-logout:hover {
  border-color: #dfbcbc;
  background: #fff8f8;
  color: #a04444;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width: 900px) {
  .account-hero {
    min-height: 300px;
    padding: 60px 32px;
  }

  .account-profile-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .account-profile-grid > div + div {
    border-left: 0;
    padding-left: 0;
  }

  .account-profile-grid > div:nth-child(even) {
    padding-left: 20px;
    border-left: 1px solid #e3ece5;
  }

  .account-order-card {
    grid-template-columns: 48px minmax(0, 1fr) auto 18px;
  }

  .account-order-status {
    display: none;
  }
}

@media (max-width: 650px) {
  .account-hero {
    align-items: flex-start;
    min-height: 0;
    padding: 48px 22px 55px;
  }

  .account-hero h1 {
    font-size: 43px;
  }

  .account-profile-mark {
    display: none;
  }

  .account-content {
    width: min(100% - 24px, 600px);
    padding: 30px 0 50px;
  }

  .account-profile-card {
    padding: 21px;
    border-radius: 18px;
  }

  .account-card-heading {
    margin-bottom: 20px;
  }

  .account-profile-grid {
    grid-template-columns: 1fr;
  }

  .account-profile-grid > div,
  .account-profile-grid > div + div,
  .account-profile-grid > div:nth-child(even) {
    padding: 14px 0;
    border-left: 0;
  }

  .account-orders {
    margin-top: 35px;
  }

  .account-orders-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }

  .account-orders-heading h2 {
    font-size: 26px;
  }

  .account-order-card {
    grid-template-columns: 45px minmax(0, 1fr) 18px;
    gap: 12px;
    padding: 14px;
  }

  .account-order-icon {
    width: 45px;
    height: 45px;
  }

  .account-order-total {
    grid-column: 2;
    min-width: 0;
    margin-top: 3px;
    text-align: left;
  }

  .account-order-card > svg:last-child {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
}

@media (max-width: 420px) {
  .account-content {
    width: min(100% - 20px, 600px);
  }

  .account-hero h1 {
    font-size: 36px;
  }

  .account-profile-card {
    padding: 18px;
  }

  .account-order-card {
    grid-template-columns: 40px minmax(0, 1fr) 16px;
  }

  .account-order-icon {
    width: 40px;
    height: 40px;
  }
}

/* =========================================================
   GREENCORE — PREMIUM NAVBAR
   ========================================================= */

.site-navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  width: 100%;
  border-bottom: 1px solid rgba(255,255,255,.07);
  background: rgba(5, 55, 39, .96);
  box-shadow: 0 8px 30px rgba(3, 45, 31, .12);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.site-navbar-inner {
  width: min(1220px, calc(100% - 42px));
  min-height: 76px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 30px;
}

/* ---------- BRAND ---------- */

.site-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  color: #f4fff7;
  font-size: 21px;
  font-weight: 900;
  letter-spacing: -.045em;
  text-decoration: none;
  transition: transform .2s ease;
}

.site-brand:hover {
  transform: translateY(-1px);
}

.site-brand > span:last-child > span {
  color: #55d98f;
}

.site-brand-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid rgba(117,231,169,.18);
  border-radius: 12px;
  background: linear-gradient(145deg, #19a967, #087d4c);
  color: #ecfff4;
  box-shadow:
    0 8px 20px rgba(0,0,0,.16),
    inset 0 1px 0 rgba(255,255,255,.14);
}

/* ---------- DESKTOP NAV ---------- */

.site-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.site-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 14px;
  border-radius: 10px;
  color: rgba(235,250,241,.68);
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
  transition:
    color .2s ease,
    background .2s ease,
    transform .2s ease;
}

.site-nav-link:hover {
  color: #f5fff8;
  background: rgba(255,255,255,.065);
}

.site-nav-link.active {
  color: #f4fff7;
  background: rgba(57,207,127,.12);
}

.site-nav-link.active::after {
  position: absolute;
  right: 14px;
  bottom: 5px;
  left: 14px;
  height: 2px;
  border-radius: 99px;
  background: #45d58b;
  box-shadow: 0 0 10px rgba(69,213,139,.45);
  content: "";
}

/* ---------- ACTIONS ---------- */

.site-nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.nav-icon-button {
  position: relative;
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 12px;
  background: rgba(255,255,255,.055);
  color: rgba(240,255,246,.82);
  text-decoration: none;
  cursor: pointer;
  transition:
    transform .2s ease,
    border-color .2s ease,
    background .2s ease,
    color .2s ease,
    box-shadow .2s ease;
}

.nav-icon-button:hover,
.nav-icon-button.search-active {
  transform: translateY(-1px);
  border-color: rgba(75,218,143,.34);
  background: rgba(39,190,113,.15);
  color: #72e6a8;
  box-shadow: 0 8px 20px rgba(0,0,0,.12);
}

.nav-cart-button {
  position: relative;
}

.nav-cart-count {
  position: absolute;
  top: -5px;
  right: -5px;
  display: grid;
  min-width: 17px;
  height: 17px;
  box-sizing: border-box;
  place-items: center;
  border: 2px solid #053927;
  border-radius: 999px;
  padding: 0 4px;
  background: #42d98b;
  color: #073b29;
  font-size: 7px;
  font-weight: 950;
  line-height: 1;
  pointer-events: none;
}

/* ---------- ACCOUNT ---------- */

.nav-authenticated {
  display: flex;
  align-items: center;
  gap: 7px;
}

.nav-account-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  max-width: 155px;
  border: 1px solid rgba(75,218,143,.42);
  border-radius: 12px;
  padding: 0 13px;
  overflow: hidden;
  background: linear-gradient(
    135deg,
    rgba(22,157,94,.9),
    rgba(12,116,72,.95)
  );
  color: #f3fff7;
  font-size: 10px;
  font-weight: 900;
  text-decoration: none;
  white-space: nowrap;
  text-overflow: ellipsis;
  cursor: pointer;
  box-shadow:
    0 7px 18px rgba(0,0,0,.12),
    inset 0 1px 0 rgba(255,255,255,.12);
  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease;
}

.nav-account-button:hover {
  transform: translateY(-1px);
  border-color: rgba(105,232,164,.65);
  box-shadow:
    0 10px 24px rgba(0,0,0,.17),
    0 0 0 3px rgba(65,211,139,.07);
}

.nav-account-button svg {
  flex-shrink: 0;
}

.nav-logout-button {
  min-height: 38px;
  border: 0;
  border-radius: 9px;
  padding: 0 9px;
  background: transparent;
  color: rgba(238,250,243,.58);
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
  transition: color .2s ease, background .2s ease;
}

.nav-logout-button:hover {
  background: rgba(255,255,255,.055);
  color: #ffb8b8;
}

/* ---------- SEARCH ---------- */

.navbar-search {
  position: absolute;
  top: calc(100% + 10px);
  left: 50%;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(620px, calc(100% - 32px));
  min-height: 52px;
  padding: 6px 7px 6px 15px;
  border: 1px solid #cfe4d6;
  border-radius: 15px;
  background: rgba(255,255,255,.97);
  box-shadow: 0 20px 50px rgba(5,65,42,.18);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -10px);
  transition:
    opacity .2s ease,
    transform .2s ease;
}

.navbar-search.open {
  opacity: 1;
  pointer-events: auto;
  transform: translate(-50%, 0);
}

.navbar-search > svg {
  flex-shrink: 0;
  color: #14945c;
}

.navbar-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: #174632;
  font-size: 12px;
  font-weight: 600;
}

.navbar-search input::placeholder {
  color: #9aada3;
}

.navbar-search button {
  min-height: 39px;
  border: 0;
  border-radius: 10px;
  padding: 0 16px;
  background: linear-gradient(135deg, #087d4c, #15a866);
  color: #fff;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 7px 15px rgba(8,125,76,.18);
  transition: transform .2s ease, box-shadow .2s ease;
}

.navbar-search button:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 20px rgba(8,125,76,.25);
}

/* ---------- MENU ---------- */

.nav-menu-button {
  display: none;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 12px;
  background: rgba(255,255,255,.055);
  color: #eefcf3;
  cursor: pointer;
}

/* ---------- MOBILE NAV ---------- */

.mobile-nav {
  display: none;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width: 1050px) {
  .site-navbar-inner {
    gap: 18px;
  }

  .site-nav-link {
    padding: 0 10px;
  }

  .nav-logout-button {
    display: none;
  }
}

