/* =========================================================
   GREENCORE — COMPACT FUTURISTIC FAQ
   ========================================================= */

.faq-section {
  position: relative;
  overflow: hidden;
  padding: 72px 24px 76px;
  background:
    radial-gradient(circle at 0% 50%, rgba(34, 197, 94, 0.08), transparent 27%),
    radial-gradient(circle at 100% 50%, rgba(16, 185, 129, 0.07), transparent 27%),
    #edf7f0;
}

.faq-container {
  position: relative;
  z-index: 1;
  width: min(1120px, 100%);
  margin: 0 auto;
}

/* HEADER */

.faq-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 30px;
}

.faq-heading > div:first-child {
  max-width: 700px;
}

.faq-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 9px;
  color: #087443;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.2em;
}

.faq-kicker::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #16a34a;
  box-shadow: 0 0 8px rgba(22, 163, 74, 0.4);
}

.faq-heading h2 {
  margin: 0;
  color: #073b28;
  font-size: clamp(30px, 3.5vw, 43px);
  line-height: 1;
  letter-spacing: -0.045em;
}

.faq-heading p {
  margin: 10px 0 0;
  color: #648074;
  font-size: 12px;
  line-height: 1.6;
}

.faq-heading-icon {
  display: grid;
  width: 45px;
  height: 45px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(20, 140, 82, 0.18);
  border-radius: 13px;
  color: #12905a;
  background: rgba(255, 255, 255, 0.62);
}

/* TWO COLUMN FAQ */

.faq-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 12px;
  align-items: start;
}

/* CARD */

.faq-item {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(20, 105, 68, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 4px 18px rgba(20, 75, 48, 0.04);
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.faq-item:hover {
  transform: translateY(-1px);
  border-color: rgba(22, 163, 74, 0.25);
  box-shadow: 0 7px 22px rgba(20, 75, 48, 0.07);
}

.faq-item.open {
  border-color: rgba(22, 163, 74, 0.3);
  box-shadow: 0 8px 25px rgba(20, 75, 48, 0.07);
}

.faq-item.open::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: #16a34a;
}

/* QUESTION */

.faq-question {
  width: 100%;
  min-height: 55px;
  padding: 8px 11px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border: 0;
  color: #123d2c;
  background: transparent;
  cursor: pointer;
  text-align: left;
  font: inherit;
}

.faq-question > span {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
}

.faq-question small {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  place-items: center;
  border: 1px solid rgba(22, 163, 74, 0.17);
  border-radius: 8px;
  color: #159447;
  background: #effaf2;
  font-size: 8px;
  font-weight: 800;
}

.faq-item.open .faq-question small {
  color: white;
  border-color: #16a34a;
  background: #16a34a;
}

.faq-question > svg {
  width: 25px;
  height: 25px;
  padding: 5px;
  flex: 0 0 25px;
  border: 1px solid rgba(22, 163, 74, 0.14);
  border-radius: 7px;
  color: #5a806c;
  background: #f5faf6;
  transition:
    transform 0.25s ease,
    color 0.25s ease,
    background 0.25s ease;
}

.faq-item.open .faq-question > svg {
  transform: rotate(180deg);
  color: white;
  background: #16a34a;
  border-color: #16a34a;
}

/* ANSWER */

.faq-answer {
  padding: 0 44px 15px 50px;
  animation: faqPremiumIn 0.2s ease both;
}

.faq-answer p {
  margin: 0;
  color: #668174;
  font-size: 10px;
  line-height: 1.65;
}

@keyframes faqPremiumIn {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* SMALL FOOTER SIGNAL */

.faq-list::after {
  content: "GREENCORE • SUSTAINABLE SHOPPING";
  grid-column: 1 / -1;
  margin-top: 7px;
  color: rgba(8, 116, 67, 0.32);
  text-align: center;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

/* MOBILE */

@media (max-width: 760px) {
  .faq-section {
    padding: 58px 16px 62px;
  }

  .faq-heading {
    margin-bottom: 24px;
  }

  .faq-heading h2 {
    font-size: 30px;
  }

  .faq-heading p {
    font-size: 11px;
  }

  .faq-heading-icon {
    width: 39px;
    height: 39px;
  }

  .faq-list {
    grid-template-columns: 1fr;
  }

  .faq-list::after {
    grid-column: auto;
  }

  .faq-question {
    min-height: 53px;
  }

  .faq-question > span {
    font-size: 11px;
  }

  .faq-answer {
    padding: 0 40px 14px 48px;
  }

  .faq-answer p {
    font-size: 10px;
  }
}


