/* =========================================================
   FAQ
   ========================================================= */

.faq-section {
  position: relative;
  overflow: hidden;
  padding: 88px 24px;
  background:
    radial-gradient(circle at 0% 70%, rgba(66, 210, 123, 0.1), transparent 28%),
    radial-gradient(circle at 100% 20%, rgba(66, 210, 123, 0.08), transparent 28%),
    #eaf6ee;
}

.faq-container {
  width: min(1120px, 100%);
  margin: 0 auto;
}

.faq-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 30px;
}

.faq-heading h2 {
  margin: 0;
  color: #073b28;
  font-size: clamp(32px, 3.7vw, 47px);
  line-height: 1;
  letter-spacing: -0.05em;
}

.faq-heading p {
  max-width: 510px;
  margin: 10px 0 0;
  color: #719082;
  font-size: 11px;
  line-height: 1.65;
}

.faq-heading-icon {
  display: grid;
  width: 43px;
  height: 43px;
  place-items: center;
  border: 1px solid rgba(18, 145, 88, 0.18);
  border-radius: 13px;
  color: #159457;
  background: rgba(255, 255, 255, 0.7);
}

.faq-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 12px;
  align-items: start;
}

.faq-item {
  overflow: hidden;
  border: 1px solid rgba(15, 100, 61, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.8);
  box-shadow: 0 5px 20px rgba(16, 70, 44, 0.04);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.faq-item:hover,
.faq-item.open {
  border-color: rgba(22, 163, 74, 0.28);
  box-shadow: 0 8px 25px rgba(16, 70, 44, 0.07);
}

.faq-question {
  width: 100%;
  min-height: 54px;
  padding: 8px 11px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border: 0;
  color: #123d2c;
  background: transparent;
  cursor: pointer;
  text-align: left;
  font: inherit;
}

.faq-question > span {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  font-size: 11px;
  font-weight: 650;
}

.faq-question small {
  display: grid;
  width: 27px;
  height: 27px;
  flex: 0 0 27px;
  place-items: center;
  border: 1px solid rgba(22, 163, 74, 0.15);
  border-radius: 8px;
  color: #159457;
  background: #eff9f2;
  font-size: 7px;
  font-weight: 800;
}

.faq-item.open .faq-question small {
  color: #fff;
  background: #16a34a;
  border-color: #16a34a;
}

.faq-question > svg {
  width: 24px;
  height: 24px;
  padding: 5px;
  flex: 0 0 24px;
  border: 1px solid rgba(22, 163, 74, 0.13);
  border-radius: 7px;
  color: #648879;
  background: #f5faf6;
  transition: transform 0.25s ease, background 0.25s ease;
}

.faq-item.open .faq-question > svg {
  transform: rotate(180deg);
  color: white;
  background: #16a34a;
  border-color: #16a34a;
}

.faq-answer {
  padding: 0 42px 15px 48px;
}

.faq-answer p {
  margin: 0;
  color: #718b7e;
  font-size: 10px;
  line-height: 1.7;
}

