/* =========================================================
   GREENCORE — LIVE IMPACT CALCULATOR
   ========================================================= */

.impact-page {
  min-height: 100%;
  background:
    radial-gradient(circle at 75% 18%, rgba(42, 191, 126, 0.12), transparent 32%),
    radial-gradient(circle at 15% 40%, rgba(20, 112, 76, 0.12), transparent 28%),
    #07110d;
  color: #ecfff5;
  overflow: hidden;
}

.impact-container {
  width: min(1120px, calc(100% - 48px));
  margin: 0 auto;
}

/* HERO */

.impact-hero {
  position: relative;
  min-height: 650px;
  display: flex;
  align-items: center;
  overflow: hidden;
  border-bottom: 1px solid rgba(111, 255, 181, 0.08);
}

.impact-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(112, 255, 181, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(112, 255, 181, 0.035) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: linear-gradient(to bottom, black, transparent 90%);
  pointer-events: none;
}

.impact-grid {
  position: absolute;
  inset: 0;
}

.impact-orbit {
  position: absolute;
  border: 1px solid rgba(77, 224, 146, 0.12);
  border-radius: 50%;
  pointer-events: none;
}

.impact-orbit-one {
  width: 680px;
  height: 680px;
  right: -250px;
  top: -160px;
}

.impact-orbit-two {
  width: 480px;
  height: 480px;
  right: -145px;
  top: -60px;
  border-color: rgba(77, 224, 146, 0.08);
}

.impact-hero .impact-container {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 75px;
  align-items: center;
  padding-top: 70px;
  padding-bottom: 70px;
}

.impact-hero-copy {
  max-width: 540px;
}

.impact-eyebrow,
.impact-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #7dffb7;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.impact-eyebrow {
  padding: 8px 12px;
  border: 1px solid rgba(125, 255, 183, 0.18);
  border-radius: 999px;
  background: rgba(125, 255, 183, 0.05);
}

.impact-hero-copy h1 {
  margin: 22px 0 20px;
  max-width: 550px;
  font-size: clamp(42px, 5vw, 68px);
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.impact-hero-copy h1 em {
  color: #62e99c;
  font-style: normal;
}

.impact-hero-copy > p {
  max-width: 510px;
  margin: 0;
  color: rgba(229, 248, 238, 0.62);
  font-size: 15px;
  line-height: 1.75;
}

.impact-live-pill {
  width: fit-content;
  margin-top: 25px;
  padding: 9px 13px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(89, 255, 159, 0.16);
  border-radius: 999px;
  background: rgba(71, 211, 133, 0.06);
  color: rgba(235, 255, 244, 0.7);
  font-size: 12px;
}

.impact-live-pill span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #55e995;
  box-shadow: 0 0 12px rgba(85, 233, 149, 0.8);
  animation: impact-pulse 1.7s infinite;
}

@keyframes impact-pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }

  50% {
    opacity: 0.45;
    transform: scale(0.7);
  }
}

/* DASHBOARD */

.impact-dashboard {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.impact-card,
.impact-mini-card {
  border: 1px solid rgba(126, 255, 187, 0.11);
  background: linear-gradient(
    145deg,
    rgba(21, 49, 37, 0.86),
    rgba(8, 25, 18, 0.82)
  );
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025),
    0 24px 70px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(18px);
}

.impact-card {
  min-height: 255px;
  padding: 23px;
  border-radius: 20px;
}

.impact-card-top {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 25px;
}

.impact-card-top > span,
.impact-mini-card span {
  color: rgba(225, 249, 235, 0.42);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.impact-icon {
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: rgba(76, 226, 143, 0.09);
  color: #67eba2;
}

.impact-card > strong {
  display: block;
  font-size: clamp(34px, 4vw, 49px);
  line-height: 1;
  letter-spacing: -0.045em;
  color: #f0fff6;
}

.impact-card > small {
  display: block;
  margin-top: 8px;
  color: rgba(226, 248, 235, 0.44);
  font-size: 12px;
}

.impact-progress {
  height: 4px;
  margin-top: 27px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
}

.impact-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2c9c63, #7dffb7);
}

.impact-card-foot {
  margin-top: 13px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: rgba(214, 248, 226, 0.54);
  font-size: 11px;
}

.impact-card-foot svg {
  color: #68e99f;
}

.impact-mini-card {
  min-height: 82px;
  padding: 17px 19px;
  display: flex;
  align-items: center;
  gap: 13px;
  border-radius: 15px;
}

.impact-mini-card > svg {
  flex: 0 0 auto;
  color: #67e99f;
}

.impact-mini-card div {
  min-width: 0;
}

.impact-mini-card span {
  display: block;
  margin-bottom: 4px;
}

.impact-mini-card strong {
  display: block;
  color: rgba(239, 255, 246, 0.84);
  font-size: 13px;
  font-weight: 600;
}

/* FLOW */

.impact-section {
  padding: 105px 0;
  background: #09150f;
}

.impact-section-heading {
  max-width: 700px;
  margin-bottom: 50px;
}

.impact-section-heading h2 {
  max-width: 650px;
  margin: 12px 0 14px;
  font-size: clamp(30px, 4vw, 48px);
  line-height: 1;
  letter-spacing: -0.035em;
}

.impact-section-heading p {
  max-width: 570px;
  margin: 0;
  color: rgba(225, 248, 235, 0.5);
  line-height: 1.7;
  font-size: 14px;
}

.impact-flow {
  display: grid;
  grid-template-columns: 1fr 40px 1fr 40px 1fr;
  align-items: center;
  gap: 15px;
}

.impact-flow article {
  min-height: 225px;
  padding: 25px;
  border: 1px solid rgba(123, 255, 183, 0.09);
  border-radius: 18px;
  background: rgba(16, 38, 28, 0.58);
