}

.impact-flow article > span {
  position: absolute;
  top: 25px;
  right: 25px;
  color: rgba(126, 255, 184, 0.28);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.impact-flow h3 {
  margin: 28px 0 8px;
