}

.impact-flow p {
  margin: 0;
  color: rgba(225, 248, 235, 0.48);
  font-size: 13px;
  line-height: 1.65;
}

.impact-flow-arrow {
  color: rgba(101, 235, 157, 0.45);
}

/* RATE */

.impact-rate-section {
  padding: 70px 0;
  background:
    linear-gradient(90deg, rgba(71, 211, 133, 0.045), transparent 55%),
    #07110d;
  border-top: 1px solid rgba(123, 255, 183, 0.06);
  border-bottom: 1px solid rgba(123, 255, 183, 0.06);
