}

.impact-rate-grid h2 {
  max-width: 450px;
  margin: 10px 0 0;
  font-size: 30px;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.impact-rate {
  padding-left: 28px;
  border-left: 1px solid rgba(124, 255, 184, 0.12);
}

.impact-rate strong {
  display: block;
  color: #73efa8;
  font-size: 31px;
  letter-spacing: -0.04em;
}

.impact-rate span {
  display: block;
  max-width: 130px;
  margin-top: 7px;
  color: rgba(225, 248, 235, 0.43);
  font-size: 11px;
  line-height: 1.5;
}

/* CTA */

.impact-cta {
  padding: 70px 0;
  background:
    radial-gradient(circle at 50% 100%, rgba(66, 206, 128, 0.11), transparent 45%),
    #06100c;
}

.impact-cta .impact-container {
  min-height: 135px;
