.impact-cta span {
  color: #72eea6;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.impact-cta h2 {
  margin: 8px 0 0;
  font-size: 29px;
  letter-spacing: -0.03em;
}

.impact-cta a {
  margin-left: auto;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 12px 17px;
  border: 1px solid rgba(118, 255, 178, 0.18);
