  font-size: 10px;
  line-height: 1.55;
}

.paper-result-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 140px;
  padding: 10px 12px;
  border: 1px solid rgba(123,226,162,.17);
  border-radius: 13px;
  background: rgba(103,215,149,.09);
  color: #82e5ab;
}

.paper-result-badge span {
  display: flex;
  flex-direction: column;
  gap: 2px;
  color: #9bc1b1;
  font-size: 8px;
  line-height: 1.25;
}

.paper-result-badge strong {
  color: #fff;
  font-size: 9px;
}

.paper-impact-metrics {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-top: 30px;
}

.paper-impact-metric {
  min-height: 153px;
  padding: 16px;
  border: 1px solid rgba(150,224,181,.13);
  border-radius: 15px;
  background: rgba(255,255,255,.045);
  backdrop-filter: blur(4px);
}

.paper-impact-metric.tree {
  background: rgba(65,181,111,.11);
  border-color: rgba(92,210,139,.23);
}

.paper-metric-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  margin-bottom: 16px;
  border-radius: 10px;
  background: rgba(122,226,162,.12);
  color: #9af0bb;
}

.paper-impact-metric strong {
  display: block;
  margin-bottom: 5px;
  color: #fff;
  font-size: 23px;
  line-height: 1;
  letter-spacing: -.04em;
}

.paper-impact-metric > span {
  display: block;
  min-height: 27px;
  color: #a2c1b4;
  font-size: 10px;
  line-height: 1.4;
}

.paper-impact-metric small {
  display: block;
  margin-top: 9px;
  color: #67a38a;
  font-size: 8px;
  line-height: 1.35;
}

.paper-tree-saving-message {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 17px;
  padding: 17px;
  border: 1px solid rgba(72,210,130,.35);
  border-radius: 15px;
  background: rgba(30,137,82,.15);
}

.paper-tree-saving-icon {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #91edb4;
  background: rgba(81,210,134,.16);
}

.paper-tree-saving-message strong {
  display: block;
  color: #fff;
  font-size: 13px;
}

.paper-tree-saving-message p {
  margin: 5px 0 0;
  color: #91b8a7;
  font-size: 9px;
  line-height: 1.6;
}

.paper-empty-result {
  position: relative;
  z-index: 2;
  min-height: 350px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  margin-top: 23px;
  padding: 30px;
  border: 1px solid rgba(151,224,181,.13);
  border-radius: 18px;
  background: rgba(255,255,255,.035);
}

.paper-empty-result > div {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
  border-radius: 50%;
  color: #75dfa1;
  background: rgba(106,220,153,.08);
  border: 1px solid rgba(106,220,153,.13);
}

.paper-empty-result h3 {
  margin: 0 0 8px;
  color: #fff;
  font-size: 17px;
}

.paper-empty-result p {
  max-width: 400px;
  margin: 0;
  color: #8daea0;
  font-size: 10px;
  line-height: 1.7;
}

.paper-disclaimer {
  position: relative;
  z-index: 2;
  margin: 18px 0 0;
  color: #63927e;
  font-size: 8px;
  line-height: 1.6;
}

/* Nature decoration */

.paper-nature-decoration {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.paper-hill {
  position: absolute;
  bottom: -95px;
  border-radius: 50% 50% 0 0;
  background: rgba(114,193,143,.08);
}

.paper-hill-one {
  right: -5%;
  width: 60%;
  height: 260px;
}

.paper-hill-two {
  right: 23%;
  width: 45%;
  height: 190px;
  background: rgba(89,177,124,.07);
}

.paper-tree {
  position: absolute;
  bottom: 5px;
  width: 22px;
  height: 82px;
  opacity: .24;
}

.paper-tree::before,
.paper-tree::after,
.paper-tree span {
  content: "";
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 50%;
  background: #59ad7a;
}

.paper-tree::before {
  top: 0;
  width: 54px;
  height: 54px;
}

.paper-tree::after {
  top: 22px;
  width: 68px;
  height: 48px;
}

.paper-tree span {
  top: 54px;
  width: 8px;
  height: 28px;
  border-radius: 3px;
  background: #367c5b;
}

.paper-tree-one {
  right: 32%;
  transform: scale(.7);
}

.paper-tree-two {
  right: 38%;
  transform: scale(.48);
}

.paper-tree-three {
  right: 27%;
  transform: scale(.55);
}

.paper-globe {
  position: absolute;
  top: 36px;
  right: 9%;
  width: 175px;
  height: 175px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: rgba(42,155,91,.2);
  background: radial-gradient(circle, rgba(93,202,132,.18), rgba(93,202,132,0) 70%);
}

.paper-globe::before,
.paper-globe::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(48,155,93,.13);
  border-radius: 50%;
}

.paper-globe::before {
  inset: -22px;
}

.paper-globe::after {
  inset: -45px;
}

.paper-globe-leaf {
  position: absolute;
  color: #39a96d;
  opacity: .55;
}

/* Why section */

.paper-why-section {
  padding: 72px 24px 90px;
  background: #f7fbf8;
}

.paper-why-container {
  width: min(1180px, 100%);
  margin: 0 auto;
}

.paper-why-heading {
  max-width: 760px;
  margin-bottom: 28px;
}

.paper-why-heading > span {
  color: #25805b;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .18em;
}

.paper-why-heading h2 {
  margin: 9px 0 7px;
  color: #092f22;
  font-size: clamp(28px, 3vw, 39px);
  line-height: 1.05;
  letter-spacing: -.045em;
}

.paper-why-heading p {
  margin: 0;
  color: #7b8d85;
  font-size: 12px;
  line-height: 1.65;
}

.paper-benefit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr) .85fr;
  gap: 14px;
}

.paper-benefit-card,
.paper-quote-card {
  min-height: 190px;
  padding: 23px;
  border: 1px solid #e0eae4;
  border-radius: 17px;
  background: #fff;
  box-shadow: 0 10px 30px rgba(7,59,43,.04);
}

.paper-benefit-icon {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
  border-radius: 11px;
  background: #dff4e7;
  color: #15945a;
}

.paper-benefit-card h3 {
  margin: 0 0 8px;
  color: #123c2e;
  font-size: 13px;
  font-weight: 800;
}

.paper-benefit-card p {
  margin: 0;
  color: #819089;
  font-size: 10px;
  line-height: 1.7;
}

.paper-quote-card {
  position: relative;
  overflow: hidden;
  background: linear-gradient(145deg, #e4f5e9, #d5efdf);
}

.paper-quote-card > span {
  display: block;
  color: #26915e;
  font-family: Georgia, serif;
  font-size: 38px;
  line-height: .7;
}

.paper-quote-card blockquote {
  position: relative;
  z-index: 2;
  margin: 12px 0 16px;
  color: #124532;
  font-family: Georgia, serif;
  font-size: 19px;
  line-height: 1.18;
  font-weight: 600;
}

.paper-quote-card blockquote em {
  color: #148b54;
}

.paper-quote-card p {
  position: relative;
  z-index: 2;
  margin: 0;
  color: #58806c;
  font-size: 9px;
  line-height: 1.6;
}

.paper-quote-leaf {
  position: absolute;
  right: -3px;
  bottom: -4px;
  color: rgba(42,145,87,.2);
  transform: rotate(-18deg);
}

/* Responsive */

@media (max-width: 1050px) {
  .paper-calculator-grid {
    grid-template-columns: 1fr;
  }

  .paper-result-card {
    min-height: 500px;
  }

  .paper-benefit-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .paper-quote-card {
    grid-column: span 2;
  }
}

@media (max-width: 700px) {
  .paper-impact-hero {
    padding: 42px 15px 55px;
  }

  .paper-impact-intro h1 {
    font-size: 42px;
  }

  .paper-impact-intro p {
    font-size: 12px;
  }

  .paper-calculator-card,
  .paper-result-card {
    padding: 20px;
    border-radius: 18px;
  }

  .paper-result-top {
    grid-template-columns: 44px 1fr;
  }

  .paper-result-icon {
    width: 44px;
    height: 44px;
  }

  .paper-result-badge {
    grid-column: 1 / -1;
    width: fit-content;
  }

  .paper-impact-metrics {
    grid-template-columns: repeat(2, 1fr);
  }

  .paper-benefit-grid {
    grid-template-columns: 1fr;
  }

  .paper-quote-card {
    grid-column: auto;
  }
}

@media (max-width: 480px) {
  .paper-material-card {
    min-height: 82px;
  }

  .paper-material-icon {
    width: 43px;
    height: 43px;
    flex-basis: 43px;
  }

  .paper-impact-metrics {
    grid-template-columns: 1fr 1fr;
  }

  .paper-impact-metric {
    min-height: 135px;
    padding: 13px;
  }

  .paper-impact-metric strong {
    font-size: 19px;
  }

  .paper-unit-toggle button {
    min-width: 45px;
  }

  .paper-amount-control input {
    padding-right: 115px;
  }
}

