/* =========================================================
   GREENCORE — FUTURISTIC VISION & MISSION
   ========================================================= */

.vm-future-page {
  --vm-bg: #031b13;
  --vm-bg-soft: #06271c;
  --vm-panel: rgba(11, 57, 40, 0.72);
  --vm-panel-light: rgba(18, 75, 51, 0.52);
  --vm-green: #69d99b;
  --vm-green-bright: #9af0bb;
  --vm-green-dark: #0e6b43;
  --vm-text: #f0fff6;
  --vm-muted: #9bbcaf;
  --vm-line: rgba(117, 224, 158, 0.16);

  position: relative;
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 75% 8%,
      rgba(42, 170, 105, 0.18),
      transparent 28%
    ),
    radial-gradient(
      circle at 10% 35%,
      rgba(42, 170, 105, 0.10),
      transparent 25%
    ),
    var(--vm-bg);
  color: var(--vm-text);
}

.vm-future-container {
  position: relative;
  z-index: 3;
  width: min(1280px, calc(100% - 48px));
  margin: 0 auto;
}

/* =========================================================
   HERO
   ========================================================= */

.vm-future-hero {
  position: relative;
  min-height: 780px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background:
    linear-gradient(
      180deg,
      rgba(2, 22, 15, 0.08),
      rgba(2, 22, 15, 0.70)
    ),
    radial-gradient(
      circle at 78% 48%,
      rgba(63, 205, 124, 0.12),
      transparent 32%
    );
}

.vm-grid-overlay {
  position: absolute;
  inset: 0;
  opacity: 0.32;
  background-image:
    linear-gradient(
      rgba(105, 217, 155, 0.055) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(105, 217, 155, 0.055) 1px,
      transparent 1px
    );
  background-size: 70px 70px;
  mask-image: linear-gradient(
    to bottom,
    black,
    transparent 90%
  );
}

.vm-noise {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.035;
  background-image:
    radial-gradient(
      rgba(255, 255, 255, 0.8) 0.6px,
      transparent 0.6px
    );
  background-size: 5px 5px;
}

.vm-glow {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(10px);
}

.vm-glow-one {
  width: 420px;
  height: 420px;
  top: 100px;
  right: 5%;
  background: rgba(57, 214, 125, 0.08);
}

.vm-glow-two {
  width: 260px;
  height: 260px;
  bottom: 10%;
  left: -100px;
  background: rgba(46, 178, 105, 0.10);
}

.vm-glow-three {
  width: 180px;
  height: 180px;
  top: 30%;
  right: 35%;
  background: rgba(136, 242, 176, 0.06);
}

.vm-hero-layout {
  display: grid;
  grid-template-columns: 1fr 0.95fr;
  align-items: center;
  gap: 60px;
  padding: 90px 0;
}

.vm-hero-copy {
  max-width: 690px;
}

.vm-future-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px;
  border: 1px solid var(--vm-line);
  border-radius: 999px;
  background: rgba(9, 51, 35, 0.58);
  color: var(--vm-green);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  backdrop-filter: blur(12px);
}

.vm-eyebrow-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--vm-green);
  box-shadow: 0 0 14px var(--vm-green);
}

.vm-hero-copy h1 {
  margin: 30px 0 24px;
  font-size: clamp(58px, 7vw, 104px);
  line-height: 0.88;
  letter-spacing: -0.065em;
  font-weight: 800;
}

.vm-hero-copy h1 span {
  color: #c5f5d6;
}

.vm-hero-copy h1 em {
  color: var(--vm-green);
  font-family: Georgia, serif;
  font-weight: 400;
}

.vm-hero-copy > p {
  max-width: 600px;
  margin: 0;
  color: var(--vm-muted);
  font-size: 17px;
  line-height: 1.8;
}

.vm-hero-actions {
  display: flex;
  align-items: center;
  gap: 28px;
  margin-top: 36px;
}

.vm-primary-button {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  padding: 14px 18px;
  border-radius: 13px;
  background: var(--vm-green);
  color: #052419;
  text-decoration: none;
  font-size: 13px;
  font-weight: 800;
  box-shadow: 0 0 30px rgba(105, 217, 155, 0.18);
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

.vm-primary-button:hover {
  transform: translateY(-3px);
  box-shadow: 0 0 45px rgba(105, 217, 155, 0.30);
}

.vm-scroll-indicator {
  display: flex;
  align-items: center;
  gap: 11px;
  color: #719688;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.vm-scroll-line {
  width: 42px;
  height: 1px;
  background: var(--vm-green);
}

/* =========================================================
   ORBITAL VISUAL
   ========================================================= */

.vm-orbit-stage {
  position: relative;
  width: min(540px, 100%);
  aspect-ratio: 1;
  margin: auto;
  display: grid;
  place-items: center;
}

.vm-orbit-circle {
  position: absolute;
  border: 1px solid rgba(105, 217, 155, 0.16);
  border-radius: 50%;
}

.vm-orbit-circle-outer {
  width: 92%;
  height: 92%;
  transform: rotate(-22deg);
  border-style: dashed;
}

.vm-orbit-circle-middle {
  width: 70%;
  height: 70%;
  border-color: rgba(105, 217, 155, 0.22);
}

.vm-orbit-circle-inner {
  width: 48%;
  height: 48%;
  border-color: rgba(105, 217, 155, 0.30);
}

.vm-orbit-dash {
  position: absolute;
  width: 108%;
  height: 35%;
  border-top: 1px solid rgba(105, 217, 155, 0.18);
  border-bottom: 1px solid rgba(105, 217, 155, 0.08);
  border-radius: 50%;
  transform: rotate(-32deg);
}

.vm-orbit-dash-two {
  transform: rotate(58deg);
}

.vm-core-glow {
  position: absolute;
  width: 190px;
  height: 190px;
  border-radius: 50%;
  background: rgba(81, 220, 132, 0.13);
  filter: blur(30px);
}

.vm-core {
  position: relative;
  z-index: 3;
  width: 165px;
  height: 165px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(139, 237, 173, 0.28);
  border-radius: 50%;
  background:
    radial-gradient(
      circle at 35% 25%,
      rgba(117, 226, 157, 0.24),
      rgba(3, 39, 26, 0.92)
    );
  color: var(--vm-green);
  box-shadow:
    inset 0 0 40px rgba(89, 215, 137, 0.08),
