.vm-core span {
  margin-top: 8px;
  font-size: 8px;
  letter-spacing: 0.25em;
  color: #8cb7a2;
}

.vm-core strong {
  margin-top: 3px;
  font-size: 12px;
  letter-spacing: 0.14em;
}

.vm-orbit-node {
  position: absolute;
  z-index: 4;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(105, 217, 155, 0.25);
