  box-shadow: 0 0 22px rgba(69, 203, 120, 0.10);
}

.vm-node-one {
  top: 10%;
  left: 31%;
}

.vm-node-two {
  top: 39%;
  right: 2%;
}

.vm-node-three {
  bottom: 9%;
  right: 29%;
}

.vm-node-four {
  bottom: 34%;
  left: 2%;
}

.vm-orbit-label {
  position: absolute;
  z-index: 5;
  color: #638f7a;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.vm-orbit-label-top {
  top: 5%;
  right: 13%;
