/* =========================================================
   VISION & MISSION — PREMIUM VISUAL ENHANCEMENT
   ========================================================= */

.vm-future-page {
  isolation: isolate;
}

/* ---------- Atmospheric depth ---------- */

.vm-future-page::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  background:
    radial-gradient(
      circle at 20% 15%,
      rgba(74, 218, 133, 0.045),
      transparent 22%
    ),
    radial-gradient(
      circle at 80% 65%,
      rgba(57, 190, 119, 0.04),
      transparent 25%
    );
}

.vm-future-page section {
  position: relative;
}

/* ---------- Hero enhancement ---------- */

.vm-future-hero {
  min-height: 820px;
}

.vm-future-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 180px;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    transparent,
    #031b13
  );
}

.vm-hero-copy h1 {
  text-shadow:
    0 0 50px rgba(91, 224, 142, 0.055);
}

.vm-hero-copy h1 em {
  position: relative;
  display: inline-block;
  text-shadow:
    0 0 35px rgba(105, 217, 155, 0.18);
}

.vm-hero-copy h1 em::after {
  content: "";
  position: absolute;
  left: 3%;
  right: 3%;
  bottom: -7px;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(105, 217, 155, 0.75),
    transparent
  );
}

/* ---------- Hero button ---------- */

.vm-primary-button {
  position: relative;
  overflow: hidden;
}

.vm-primary-button::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 80%;
  height: 100%;
  transform: skewX(-20deg);
  background: rgba(255, 255, 255, 0.18);
  transition: left 0.55s ease;
}

.vm-primary-button:hover::before {
  left: 140%;
}

/* ---------- Orbital system ---------- */

.vm-orbit-stage {
  filter: drop-shadow(
    0 0 45px rgba(68, 210, 126, 0.05)
  );
}

.vm-orbit-circle-outer {
  animation: vmOrbitSpin 26s linear infinite;
}

.vm-orbit-circle-middle {
  animation: vmOrbitSpinReverse 20s linear infinite;
}

.vm-orbit-circle-inner {
  animation: vmOrbitPulse 4s ease-in-out infinite;
}

.vm-orbit-dash-one {
  animation: vmOrbitSpin 18s linear infinite;
}

.vm-orbit-dash-two {
  animation: vmOrbitSpinReverse 24s linear infinite;
}

.vm-core-glow {
  animation: vmCoreGlow 4s ease-in-out infinite;
}

.vm-core {
  animation: vmCoreFloat 5s ease-in-out infinite;
}

.vm-orbit-node {
  animation: vmNodePulse 3.5s ease-in-out infinite;
}

.vm-node-one {
  animation-delay: 0s;
}

.vm-node-two {
  animation-delay: 0.8s;
}

.vm-node-three {
  animation-delay: 1.6s;
}

.vm-node-four {
  animation-delay: 2.4s;
}

@keyframes vmOrbitSpin {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes vmOrbitSpinReverse {
  from {
    transform: rotate(360deg);
  }

  to {
    transform: rotate(0deg);
  }
}

@keyframes vmOrbitPulse {
  0%,
  100% {
    opacity: 0.65;
    transform: scale(0.98);
  }

  50% {
    opacity: 1;
    transform: scale(1.02);
  }
}

@keyframes vmCoreGlow {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(0.94);
  }

  50% {
    opacity: 1;
    transform: scale(1.08);
  }
}

@keyframes vmCoreFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }
}

@keyframes vmNodePulse {
  0%,
  100% {
    box-shadow:
      0 0 0 rgba(69, 203, 120, 0);
    transform: scale(1);
  }

  50% {
    box-shadow:
      0 0 24px rgba(69, 203, 120, 0.14);
    transform: scale(1.06);
  }
}

/* ---------- Section transition ---------- */

.vm-vision-section::before,
.vm-mission-section::before,
.vm-principles-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: min(900px, 70%);
  height: 1px;
  transform: translateX(-50%);
  background: linear-gradient(
    90deg,
    transparent,
    rgba(105, 217, 155, 0.18),
    transparent
  );
}

/* ---------- Section index ---------- */

.vm-section-index {
  position: relative;
}

.vm-section-index::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -9px;
  width: 18px;
  height: 1px;
  background: var(--vm-green);
  box-shadow:
    0 0 12px rgba(105, 217, 155, 0.5);
}

/* ---------- Main cards ---------- */

.vm-big-card {
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease,
    transform 0.35s ease;
}

.vm-big-card:hover {
  border-color: rgba(105, 217, 155, 0.28);
  box-shadow:
    0 35px 100px rgba(0, 0, 0, 0.28),
    inset 0 1px rgba(145, 238, 177, 0.08);
}

/* glass reflection */

.vm-big-card::after {
  content: "";
  position: absolute;
  top: -50%;
  left: -15%;
  width: 45%;
  height: 200%;
  transform: rotate(18deg);
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.018),
    transparent
  );
  transition: left 0.8s ease;
}

.vm-big-card:hover::after {
  left: 110%;
}

/* ---------- Vision visual ---------- */

.vm-vision-visual {
  overflow: hidden;
}

.vm-vision-visual::before {
  content: "";
  position: absolute;
  width: 430px;
  height: 430px;
  border-radius: 50%;
  border: 1px solid rgba(105, 217, 155, 0.045);
}

.vm-vision-center {
  animation: vmVisionFloat 5s ease-in-out infinite;
}

@keyframes vmVisionFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-10px);
  }
}

.vm-visual-tag {
  backdrop-filter: blur(14px);
  box-shadow:
    0 8px 25px rgba(0, 0, 0, 0.18);
}

.tag-one {
  animation: vmTagFloat 5s ease-in-out infinite;
}

.tag-two {
  animation: vmTagFloat 5s ease-in-out 1.2s infinite;
}

.tag-three {
  animation: vmTagFloat 5s ease-in-out 2.2s infinite;
}

@keyframes vmTagFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-5px);
  }
}

/* ---------- Mission visual ---------- */

.vm-mission-visual {
  overflow: hidden;
}

.vm-mission-center {
  animation: vmMissionPulse 4.5s ease-in-out infinite;
}

@keyframes vmMissionPulse {
  0%,
  100% {
    box-shadow:
      0 0 0 35px rgba(105, 217, 155, 0.025),
      0 0 0 70px rgba(105, 217, 155, 0.018),
      0 0 70px rgba(105, 217, 155, 0.10);
  }

  50% {
    box-shadow:
      0 0 0 48px rgba(105, 217, 155, 0.025),
      0 0 0 92px rgba(105, 217, 155, 0.014),
      0 0 90px rgba(105, 217, 155, 0.18);
  }
}

.vm-mission-point {
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

.vm-mission-point:hover {
  transform: scale(1.12);
  box-shadow:
    0 0 25px rgba(105, 217, 155, 0.20);
}

/* ---------- Mission rows ---------- */

.vm-mission-points div {
  position: relative;
  overflow: hidden;
  transition:
    background 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s ease;
}

.vm-mission-points div::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--vm-green);
  transform: scaleY(0);
  transform-origin: center;
  transition: transform 0.25s ease;
}

.vm-mission-points div:hover {
  transform: translateX(5px);
  background: rgba(105, 217, 155, 0.07);
  border-color: rgba(105, 217, 155, 0.16);
}

.vm-mission-points div:hover::before {
  transform: scaleY(1);
}

/* ---------- Principles ---------- */

.vm-principle-card {
  backdrop-filter: blur(12px);
}

.vm-principle-card::before {
  content: "";
  position: absolute;
  width: 180px;
  height: 180px;
  top: -100px;
  right: -100px;
  border-radius: 50%;
  background: rgba(83, 220, 132, 0.06);
  filter: blur(20px);
  transition:
    transform 0.4s ease,
    opacity 0.4s ease;
}

.vm-principle-card:hover::before {
  transform: scale(1.5);
  opacity: 1.5;
}

.vm-principle-card:nth-child(1) {
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(102, 221, 145, 0.10),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      rgba(12, 63, 43, 0.82),
      rgba(5, 34, 23, 0.76)
    );
}

.vm-principle-card:nth-child(2) {
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(70, 210, 174, 0.09),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      rgba(10, 62, 48, 0.82),
      rgba(5, 34, 25, 0.76)
    );
}

.vm-principle-card:nth-child(3) {
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(114, 203, 169, 0.08),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      rgba(11, 58, 43, 0.82),
      rgba(5, 34, 24, 0.76)
    );
}

.vm-principle-card:nth-child(4) {
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(152, 225, 161, 0.09),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      rgba(13, 62, 41, 0.82),
      rgba(5, 34, 23, 0.76)
    );
}

.vm-principle-icon {
  transition:
    transform 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}

.vm-principle-card:hover .vm-principle-icon {
  transform: translateY(-3px) rotate(-3deg);
  background: rgba(105, 217, 155, 0.12);
  box-shadow:
    0 0 25px rgba(105, 217, 155, 0.10);
}

/* ---------- Principles heading ---------- */

.vm-principles-heading h2 {
  text-shadow:
    0 0 40px rgba(105, 217, 155, 0.04);
}

/* ---------- Final CTA ---------- */

.vm-future-cta {
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease;
}

.vm-future-cta:hover {
  border-color: rgba(105, 217, 155, 0.30);
  box-shadow:
    0 35px 100px rgba(0, 0, 0, 0.28),
    0 0 70px rgba(48, 188, 108, 0.05);
}

.vm-cta-content h2 {
  text-shadow:
    0 0 45px rgba(105, 217, 155, 0.04);
}

.vm-cta-visual {
  overflow: hidden;
}

.vm-cta-circle {
  animation: vmCtaOrbit 18s linear infinite;
}

.cta-circle-two {
  animation-direction: reverse;
  animation-duration: 25s;
}

.cta-circle-three {
  animation-duration: 32s;
}

@keyframes vmCtaOrbit {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

.vm-cta-core {
  animation: vmCtaCore 4s ease-in-out infinite;
}

@keyframes vmCtaCore {
  0%,
  100% {
    transform: scale(1);
    box-shadow:
      0 0 70px rgba(78, 214, 130, 0.14),
      inset 0 0 30px rgba(78, 214, 130, 0.08);
  }

  50% {
    transform: scale(1.06);
    box-shadow:
      0 0 100px rgba(78, 214, 130, 0.22),
      inset 0 0 40px rgba(78, 214, 130, 0.12);
  }
}

/* ---------- CTA button ---------- */

.vm-cta-buttons a {
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

.vm-cta-buttons a:hover {
  transform: translateY(-3px);
  box-shadow:
    0 12px 30px rgba(62, 208, 124, 0.14);
}

.vm-cta-buttons .vm-cta-secondary:hover {
  box-shadow: none;
}

/* ---------- Reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {
  .vm-future-page *,
  .vm-future-page *::before,
  .vm-future-page *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* ---------- Mobile refinement ---------- */

@media (max-width: 650px) {
  .vm-future-hero {
    min-height: auto;
  }

  .vm-hero-copy h1 {
    text-shadow: none;
  }

  .vm-orbit-stage {
    margin-top: 20px;
  }

  .vm-big-card {
    border-radius: 23px;
  }

  .vm-card-content {
    padding: 34px 25px;
  }

  .vm-card-stat-row {
    flex-wrap: wrap;
  }

  .vm-principle-card {
    border-radius: 17px;
  }

  .vm-future-cta {
    border-radius: 23px;
  }
}

/* =========================================================
   GREENCORE — GLOBAL PREMIUM NAVBAR
   Applies to every page
   ========================================================= */

.site-navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  width: 100%;
  height: 72px;
  display: flex;
  align-items: center;
  background:
    linear-gradient(
      180deg,
      rgba(3, 47, 32, 0.97),
      rgba(3, 39, 27, 0.94)
    );
  border-bottom: 1px solid rgba(119, 225, 157, 0.10);
  box-shadow:
    0 10px 35px rgba(0, 28, 18, 0.16),
    inset 0 -1px rgba(126, 226, 159, 0.035);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.site-navbar::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(105, 217, 155, 0.25),
    transparent
  );
  pointer-events: none;
}

.site-navbar::after {
  content: "";
  position: absolute;
  width: 280px;
  height: 90px;
  left: 18%;
  top: -65px;
  border-radius: 50%;
  background: rgba(57, 204, 121, 0.07);
  filter: blur(25px);
  pointer-events: none;
}

.site-navbar-inner {
  position: relative;
  z-index: 2;
  width: min(1320px, calc(100% - 42px));
  height: 100%;
  margin: 0 auto;
  display: flex;
  align-items: center;
}

/* =========================================================
   LOGO
   ========================================================= */

.site-navbar .site-logo,
.site-navbar .navbar-logo,
.site-navbar .brand {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 11px;
  text-decoration: none;
  color: #f2fff7;
  font-weight: 850;
  letter-spacing: -0.045em;
}

.site-navbar .site-logo-mark,
.site-navbar .navbar-logo-mark,
.site-navbar .brand-mark {
  position: relative;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border: 1px solid rgba(134, 239, 171, 0.32);
  border-radius: 13px;
  background:
    linear-gradient(
      145deg,
      rgba(48, 187, 108, 0.95),
      rgba(12, 112, 67, 0.95)
    );
  color: #eafff1;
  box-shadow:
    0 0 25px rgba(56, 204, 121, 0.14),
    inset 0 1px rgba(255, 255, 255, 0.15);
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

.site-navbar .site-logo:hover .site-logo-mark,
.site-navbar .navbar-logo:hover .navbar-logo-mark,
.site-navbar .brand:hover .brand-mark {
  transform: translateY(-2px) rotate(-3deg);
  box-shadow:
    0 0 35px rgba(56, 204, 121, 0.25),
    inset 0 1px rgba(255, 255, 255, 0.18);
}

/* =========================================================
   NAV LINKS
   ========================================================= */

.site-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: 45px;
}

.site-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  height: 42px;
  padding: 0 15px;
  border-radius: 11px;
  color: #a8c7b7;
  text-decoration: none;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: -0.01em;
  transition:
    color 0.22s ease,
    background 0.22s ease,
    transform 0.22s ease;
}

.site-nav-link::before {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 5px;
  height: 2px;
  border-radius: 99px;
  background: #72dfa0;
  transform: scaleX(0);
  transform-origin: center;
  box-shadow: 0 0 10px rgba(114, 223, 160, 0.45);
  transition: transform 0.22s ease;
}

.site-nav-link:hover {
  color: #edfff4;
  background: rgba(107, 218, 151, 0.075);
}

.site-nav-link:hover::before {
  transform: scaleX(1);
}

/* Active route support */
.site-nav-link.active,
.site-nav-link[aria-current="page"] {
  color: #f2fff7;
  background:
    linear-gradient(
      135deg,
      rgba(49, 167, 100, 0.20),
      rgba(39, 126, 78, 0.12)
    );
  border: 1px solid rgba(104, 219, 148, 0.13);
  box-shadow:
    inset 0 1px rgba(255, 255, 255, 0.025),
    0 5px 20px rgba(23, 103, 62, 0.08);
}

.site-nav-link.active::before,
.site-nav-link[aria-current="page"]::before {
  transform: scaleX(0.65);
}

/* =========================================================
   RIGHT SIDE CONTROLS
   ========================================================= */

.site-navbar .nav-actions,
.site-navbar .navbar-actions,
.site-navbar .site-nav-actions {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-left: auto;
}

.site-navbar button,
.site-navbar .nav-icon-button,
.site-navbar .navbar-icon-button {
  transition:
    transform 0.22s ease,
    background 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease;
}

.site-navbar .nav-icon-button:hover,
.site-navbar .navbar-icon-button:hover {
  transform: translateY(-2px);
  border-color: rgba(105, 217, 155, 0.28);
  background: rgba(92, 214, 143, 0.11);
  box-shadow:
    0 8px 22px rgba(0, 0, 0, 0.14),
    0 0 20px rgba(77, 211, 130, 0.06);
}

/* =========================================================
   PROFILE AVATAR
   ========================================================= */

.nav-profile-avatar {
  position: relative;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  padding: 0;
  overflow: hidden;
  border: 1px solid rgba(126, 237, 165, 0.34);
  border-radius: 50%;
  background:
    radial-gradient(
      circle at 35% 25%,
      #77e3a0,
      #1d9b60 65%,
      #087043
    );
  color: #ecfff3;
  font-size: 14px;
  font-weight: 850;
  cursor: pointer;
  box-shadow:
    0 0 20px rgba(54, 207, 122, 0.17),
    inset 0 1px rgba(255, 255, 255, 0.18);
}

.nav-profile-avatar::after {
  content: "";
  position: absolute;
  right: 1px;
  bottom: 1px;
  width: 9px;
  height: 9px;
  border: 2px solid #063a27;
  border-radius: 50%;
  background: #69e19a;
  box-shadow: 0 0 10px rgba(105, 225, 154, 0.75);
}

.nav-profile-avatar:hover {
  transform: translateY(-2px) scale(1.03);
  box-shadow:
    0 0 30px rgba(54, 207, 122, 0.27),
    inset 0 1px rgba(255, 255, 255, 0.20);
}

.nav-profile-login {
  text-decoration: none;
}

/* =========================================================
   CART BADGE
   ========================================================= */

.site-navbar .cart-badge,
.site-navbar .nav-cart-badge {
  border: 2px solid #063b28;
  box-shadow:
    0 0 12px rgba(79, 223, 139, 0.35);
}

/* =========================================================
   SEARCH
   ========================================================= */

.site-navbar input {
  color: #eafff1;
}

.site-navbar input::placeholder {
  color: #719386;
}

.site-navbar input:focus {
  outline: none;
}

/* =========================================================
   MOBILE MENU
   ========================================================= */

.mobile-nav-menu {
  background:
    linear-gradient(
      180deg,
      rgba(3, 47, 32, 0.99),
      rgba(2, 34, 24, 0.99)
    ) !important;
  border-top: 1px solid rgba(105, 217, 155, 0.10);
  box-shadow:
    0 20px 45px rgba(0, 20, 12, 0.25);
  backdrop-filter: blur(20px);
}

.mobile-nav-link {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 48px;
  padding: 0 15px;
  border: 1px solid transparent;
  border-radius: 11px;
  color: #a9c9b8;
  text-decoration: none;
  font-size: 13px;
  font-weight: 750;
  transition:
    color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.mobile-nav-link:hover,
.mobile-nav-link.active {
  color: #f0fff6;
  background: rgba(93, 216, 144, 0.08);
  border-color: rgba(105, 217, 155, 0.12);
  transform: translateX(3px);
}

/* =========================================================
   SMALL SCREENS
   ========================================================= */

@media (max-width: 850px) {
  .site-navbar {
    height: 66px;
  }

  .site-navbar-inner {
    width: calc(100% - 24px);
  }

  .site-nav {
    display: none;
  }

  .site-navbar .site-logo-mark,
  .site-navbar .navbar-logo-mark,
  .site-navbar .brand-mark {
    width: 39px;
    height: 39px;
    border-radius: 12px;
  }

  .nav-profile-avatar {
    width: 39px;
    height: 39px;
  }
}

@media (max-width: 480px) {
  .site-navbar-inner {
    width: calc(100% - 18px);
  }

  .site-navbar .nav-actions,
  .site-navbar .navbar-actions,
  .site-navbar .site-nav-actions {
    gap: 5px;
  }
}

/* =========================================================
   PREMIUM GREENCORE CALCULATOR
   ========================================================= */

.paper-impact-page {
  position: relative;
  min-height: calc(100vh - 76px);
  overflow: hidden;
  padding: 86px 24px 110px;
  background:
    radial-gradient(circle at 12% 8%, rgba(74, 222, 128, 0.13), transparent 28%),
    radial-gradient(circle at 88% 18%, rgba(34, 197, 94, 0.11), transparent 30%),
    linear-gradient(180deg, #f7fcf8 0%, #eef8f1 52%, #f8fcf9 100%);
}

.paper-impact-page::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.28;
  background-image:
    linear-gradient(rgba(22, 101, 52, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(22, 101, 52, 0.055) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, black, transparent 78%);
}

.paper-impact-page::after {
  content: "";
  position: absolute;
  width: 520px;
  height: 520px;
  right: -260px;
  top: 280px;
  border-radius: 50%;
  background: rgba(74, 222, 128, 0.1);
  filter: blur(90px);
  pointer-events: none;
}

.paper-impact-container {
  position: relative;
  z-index: 1;
  width: min(1180px, 100%);
  margin: 0 auto;
}

.paper-impact-hero {
  max-width: 790px;
  margin: 0 auto 58px;
  text-align: center;
}

.paper-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 14px;
  border: 1px solid rgba(22, 101, 52, 0.14);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: 0 8px 25px rgba(22, 101, 52, 0.08);
  color: #166534;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  backdrop-filter: blur(14px);
}

.paper-eyebrow::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 5px rgba(34, 197, 94, 0.12);
}

.paper-impact-hero h1 {
  margin: 22px 0 16px;
  color: #102c1c;
  font-size: clamp(42px, 6vw, 76px);
  line-height: 0.98;
  letter-spacing: -0.055em;
  font-weight: 850;
}

.paper-impact-hero h1 span {
  display: block;
  background: linear-gradient(100deg, #166534 5%, #22a052 48%, #65a30d 95%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.paper-impact-intro {
  max-width: 650px;
  margin: 0 auto;
  color: #557060;
  font-size: 17px;
  line-height: 1.75;
}

/* Calculator shell */

.paper-calculator-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: 24px;
  align-items: stretch;
}

.paper-calculator-card,
.paper-result-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(22, 101, 52, 0.12);
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow:
    0 25px 70px rgba(22, 101, 52, 0.10),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(22px);
}

.paper-calculator-card {
  padding: 34px;
}

.paper-calculator-card::before,
.paper-result-card::before {
  content: "";
  position: absolute;
  width: 220px;
  height: 220px;
  right: -100px;
  top: -120px;
  border-radius: 50%;
  background: rgba(74, 222, 128, 0.11);
  filter: blur(10px);
}

.paper-section-heading {
  position: relative;
  margin-bottom: 24px;
}

.paper-section-heading h2 {
  margin: 0 0 7px;
  color: #143522;
  font-size: 25px;
  letter-spacing: -0.025em;
}

.paper-section-heading p {
  margin: 0;
  color: #718277;
  font-size: 14px;
  line-height: 1.6;
}

/* Material cards */

.paper-material-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 15px;
  width: 100%;
  margin-bottom: 12px;
  padding: 17px;
  border: 1px solid rgba(22, 101, 52, 0.1);
  border-radius: 19px;
  background: rgba(248, 252, 249, 0.8);
  color: #244333;
  text-align: left;
  cursor: pointer;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    background 180ms ease;
}

.paper-material-card:hover {
  transform: translateY(-2px);
  border-color: rgba(34, 197, 94, 0.3);
  background: #ffffff;
  box-shadow: 0 12px 30px rgba(22, 101, 52, 0.09);
}

.paper-material-card.active {
  border-color: rgba(34, 197, 94, 0.5);
  background: linear-gradient(135deg, #effcf3, #ffffff);
  box-shadow:
    0 12px 35px rgba(34, 197, 94, 0.12),
    inset 0 0 0 1px rgba(34, 197, 94, 0.06);
}

.paper-material-card strong {
  display: block;
  margin-bottom: 3px;
  font-size: 15px;
  color: #183b26;
}

.paper-material-card span {
  color: #789080;
  font-size: 12px;
}

.paper-material-card svg {
  flex: 0 0 auto;
  color: #22a052;
}

.paper-material-card .material-check {
  margin-left: auto;
  width: 21px;
  height: 21px;
  border: 1.5px solid #c9d8cd;
  border-radius: 50%;
}

.paper-material-card.active .material-check {
  border-color: #22a052;
  background: #22a052;
  box-shadow: inset 0 0 0 5px white;
}

/* Amount */

.paper-amount-control {
  margin-top: 30px;
}

.paper-amount-control label {
  display: block;
  margin-bottom: 10px;
  color: #365642;
  font-size: 13px;
  font-weight: 750;
}

.paper-amount-control input {
  width: 100%;
  min-height: 58px;
  padding: 0 18px;
  border: 1px solid #d4e2d8;
  border-radius: 17px;
  outline: none;
  background: #fbfefc;
  color: #163a24;
  font-size: 20px;
  font-weight: 750;
  transition: 180ms ease;
}

.paper-amount-control input:focus {
  border-color: rgba(34, 197, 94, 0.65);
  box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.1);
  background: #ffffff;
}

.paper-unit-toggle {
  display: inline-flex;
  margin-top: 11px;
  padding: 4px;
  border: 1px solid #dce8df;
  border-radius: 12px;
  background: #f2f7f3;
}

.paper-unit-toggle button {
  min-width: 58px;
  padding: 7px 11px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #718277;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.paper-unit-toggle button.active {
  background: #ffffff;
  color: #166534;
  box-shadow: 0 3px 10px rgba(22, 101, 52, 0.1);
}

/* Calculate */

.paper-calculate-button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  min-height: 58px;
  margin-top: 26px;
  border: 0;
  border-radius: 17px;
  background: linear-gradient(105deg, #14532d, #16803f 55%, #22a052);
  color: white;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.01em;
  cursor: pointer;
  box-shadow:
    0 14px 30px rgba(22, 101, 52, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  overflow: hidden;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.paper-calculate-button::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    110deg,
    transparent 25%,
    rgba(255, 255, 255, 0.16) 45%,
    transparent 65%
  );
  transform: translateX(-100%);
  transition: transform 500ms ease;
}

.paper-calculate-button:hover {
  transform: translateY(-2px);
  box-shadow:
    0 18px 38px rgba(22, 101, 52, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.paper-calculate-button:hover::after {
  transform: translateX(100%);
}

.paper-calculate-button:active {
  transform: translateY(0);
}

/* Result */

.paper-result-card {
  min-height: 100%;
  padding: 34px;
  background:
    radial-gradient(circle at 88% 5%, rgba(74, 222, 128, 0.16), transparent 32%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.94), rgba(242, 250, 245, 0.88));
}

.paper-result-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.paper-result-top h2 {
  margin: 0 0 8px;
  color: #12331f;
  font-size: 25px;
}

.paper-result-top p {
  margin: 0;
  color: #728278;
  font-size: 13px;
}

.paper-result-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border: 1px solid rgba(34, 197, 94, 0.16);
  border-radius: 999px;
  background: rgba(220, 252, 231, 0.72);
  color: #166534;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.paper-result-badge svg {
  width: 14px;
  height: 14px;
}

/* Metrics */

.paper-impact-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
  margin-top: 30px;
}

.paper-impact-metric {
  position: relative;
  min-height: 132px;
  padding: 20px;
  overflow: hidden;
  border: 1px solid rgba(22, 101, 52, 0.1);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.78);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.paper-impact-metric:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 28px rgba(22, 101, 52, 0.09);
}

.paper-impact-metric svg {
  margin-bottom: 17px;
  color: #22a052;
}

.paper-impact-metric strong {
  display: block;
  color: #153c24;
  font-size: clamp(22px, 3vw, 31px);
  line-height: 1;
  letter-spacing: -0.035em;
}

.paper-impact-metric span {
  display: block;
  margin-top: 7px;
  color: #789080;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.paper-tree-saving-message {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  padding: 15px 17px;
  border: 1px solid rgba(101, 163, 13, 0.16);
  border-radius: 16px;
  background: linear-gradient(110deg, #f2fbe8, #f7fced);
  color: #46621f;
  font-size: 13px;
  font-weight: 700;
}

.paper-tree-saving-message svg {
  flex: 0 0 auto;
  color: #65a30d;
}

/* Empty state */

.paper-empty-result {
  display: flex;
  min-height: 330px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 40px;
}

.paper-empty-result > div:first-child {
  display: grid;
  width: 76px;
  height: 76px;
  place-items: center;
  margin-bottom: 20px;
  border: 1px solid rgba(34, 197, 94, 0.16);
  border-radius: 24px;
  background: linear-gradient(145deg, #eaf9ee, #ffffff);
  color: #22a052;
  box-shadow: 0 15px 35px rgba(34, 197, 94, 0.1);
}

.paper-empty-result h3 {
  margin: 0 0 8px;
  color: #1b3d28;
  font-size: 19px;
}

.paper-empty-result p {
  max-width: 360px;
  margin: 0;
  color: #7b8d82;
  font-size: 13px;
  line-height: 1.7;
}

/* Why section */

.paper-why-section {
  margin-top: 100px;
}

.paper-why-section > .paper-section-heading {
  max-width: 620px;
  margin-bottom: 25px;
}

.paper-why-section > .paper-section-heading h2 {
  font-size: 34px;
  letter-spacing: -0.035em;
}

.paper-benefit-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
}

.paper-benefit-card,
.paper-quote-card {
  position: relative;
  overflow: hidden;
  min-height: 205px;
  padding: 24px;
  border: 1px solid rgba(22, 101, 52, 0.09);
  border-radius: 23px;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.paper-benefit-card:hover,
.paper-quote-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 38px rgba(22, 101, 52, 0.1);
}

.paper-benefit-card::after {
  content: "";
  position: absolute;
  width: 100px;
  height: 100px;
  right: -42px;
  bottom: -48px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.34);
}

.paper-benefit-card:nth-child(1) {
  background: linear-gradient(145deg, #e8f8ee, #d5f0df);
}

.paper-benefit-card:nth-child(2) {
  background: linear-gradient(145deg, #e4f8f3, #ccefe4);
}

.paper-benefit-card:nth-child(3) {
  background: linear-gradient(145deg, #eef8df, #dcefc8);
}

.paper-benefit-card:nth-child(4) {
  background: linear-gradient(145deg, #e1f4e8, #ccebd8);
}

.paper-benefit-card svg {
  width: 23px;
  height: 23px;
  margin-bottom: 28px;
  color: #166534;
}

.paper-benefit-card h3 {
  margin: 0 0 9px;
  color: #183d27;
  font-size: 16px;
}

.paper-benefit-card p {
  margin: 0;
  color: #587060;
  font-size: 12px;
  line-height: 1.65;
}

.paper-quote-card {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 15px;
  min-height: 130px;
  background:
    radial-gradient(circle at 80% 20%, rgba(255, 255, 255, 0.5), transparent 25%),
    linear-gradient(145deg, #e0f5e7, #ccebd8);
  text-align: center;
}

.paper-quote-card p {
  max-width: 760px;
  margin: 0;
  color: #245337;
  font-size: 19px;
  line-height: 1.55;
  font-weight: 750;
  letter-spacing: -0.015em;
}

/* Responsive */

@media (max-width: 980px) {
  .paper-calculator-grid {
    grid-template-columns: 1fr;
  }

  .paper-benefit-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .paper-impact-hero h1 {
    font-size: clamp(42px, 9vw, 64px);
  }
}

@media (max-width: 620px) {
  .paper-impact-page {
    padding: 58px 16px 80px;
  }

  .paper-impact-hero {
    margin-bottom: 38px;
  }

  .paper-impact-hero h1 {
    font-size: 43px;
  }

  .paper-impact-intro {
    font-size: 15px;
  }

  .paper-calculator-card,
  .paper-result-card {
    padding: 23px;
    border-radius: 23px;
  }

  .paper-result-top {
    flex-direction: column;
  }

  .paper-impact-metrics {
    grid-template-columns: 1fr;
  }

  .paper-benefit-grid {
    grid-template-columns: 1fr;
  }

  .paper-why-section {
    margin-top: 70px;
  }

  .paper-why-section > .paper-section-heading h2 {
    font-size: 28px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .paper-material-card,
  .paper-calculate-button,
  .paper-impact-metric,
  .paper-benefit-card,
  .paper-quote-card {
    transition: none;
  }
}


/* =========================================================
   VISION-STYLE CALCULATOR EXPERIENCE
   ========================================================= */

.paper-impact-page {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  padding: 90px 24px 130px;
  color: #ecfdf3;
  background:
    radial-gradient(circle at 50% -15%, rgba(34, 197, 94, 0.22), transparent 35%),
    radial-gradient(circle at 5% 30%, rgba(16, 185, 129, 0.10), transparent 30%),
    radial-gradient(circle at 95% 65%, rgba(74, 222, 128, 0.08), transparent 28%),
    linear-gradient(180deg, #03130c 0%, #061b12 48%, #03140d 100%);
}

.paper-impact-page::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(rgba(74, 222, 128, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(74, 222, 128, 0.035) 1px, transparent 1px);
