  min-width: 50px;
  height: 34px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #607c6b;
  font-size: 11px;
  font-weight: 850;
  cursor: pointer;
}

.calculator-unit-toggle button.active {
  background: rgba(74, 222, 128, 0.13);
  color: #86efac;
  box-shadow: inset 0 0 0 1px rgba(74, 222, 128, 0.08);
}

.calculator-conversion {
  min-height: 17px;
  margin: 9px 3px 0;
  color: #597464;
  font-size: 10px;
}

/* ============================================================
   PRIMARY BUTTON
   ============================================================ */

.calculator-primary-button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 58px;
  gap: 10px;
  margin-top: 23px;
  overflow: hidden;
  border: 1px solid rgba(134, 239, 172, 0.17);
  border-radius: 17px;
  background:
    linear-gradient(
      105deg,
      #14532d,
      #15803d 50%,
      #22c55e
    );
  color: white;
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;
  box-shadow:
    0 17px 42px rgba(34, 197, 94, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease;
}

.calculator-primary-button::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    110deg,
    transparent 20%,
    rgba(255, 255, 255, 0.18) 48%,
    transparent 70%
  );
  transform: translateX(-120%);
  transition: transform 600ms ease;
}

.calculator-primary-button:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow:
    0 23px 52px rgba(34, 197, 94, 0.23),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.calculator-primary-button:hover:not(:disabled)::after {
  transform: translateX(120%);
}

.calculator-primary-button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
  box-shadow: none;
}

.calculator-arrow {
  font-size: 18px;
  line-height: 1;
}

.calculator-reset {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: 100%;
  margin-top: 13px;
  padding: 5px;
  border: 0;
  background: transparent;
  color: #567162;
  font-size: 10px;
  cursor: pointer;
}

.calculator-reset:hover {
  color: #8aad99;
}

/* ============================================================
   RESULT HEADER
   ============================================================ */

.calculator-result-symbol {
  display: grid;
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid rgba(74, 222, 128, 0.15);
  border-radius: 14px;
  background: rgba(74, 222, 128, 0.08);
  color: #4ade80;
  box-shadow: 0 0 25px rgba(34, 197, 94, 0.06);
}

.calculator-result-heading {
  min-height: 78px;
}

.calculator-result-line {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 25px 0;
}

.calculator-result-line span {
  height: 1px;
  flex: 1;
  background: rgba(134, 239, 172, 0.08);
}

.calculator-result-line small {
  color: #4c705b;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.18em;
}

/* ============================================================
   METRICS
   ============================================================ */

.calculator-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
}

.calculator-metric {
  position: relative;
  min-height: 145px;
  padding: 21px;
  overflow: hidden;
  border: 1px solid rgba(134, 239, 172, 0.08);
  border-radius: 20px;
  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.045),
      rgba(255, 255, 255, 0.015)
    );
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.calculator-metric::after {
  content: "";
  position: absolute;
  width: 100px;
  height: 100px;
  right: -50px;
  bottom: -50px;
  border-radius: 50%;
  background: rgba(74, 222, 128, 0.06);
  filter: blur(10px);
}

.calculator-metric:hover {
  transform: translateY(-4px);
  border-color: rgba(74, 222, 128, 0.20);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.18);
}

.calculator-metric > div:first-child {
  display: grid;
  width: 37px;
  height: 37px;
  place-items: center;
  margin-bottom: 18px;
  border: 1px solid rgba(74, 222, 128, 0.10);
  border-radius: 11px;
  background: rgba(74, 222, 128, 0.06);
  color: #4ade80;
}

.calculator-metric strong {
  display: block;
  color: #effdf4;
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1;
  letter-spacing: -0.045em;
}

.calculator-metric span {
  display: block;
  margin-top: 8px;
  color: #799486;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.calculator-metric small {
  display: block;
  margin-top: 7px;
  color: #4e6c5b;
  font-size: 9px;
}

/* ============================================================
   IMPACT MESSAGE
   ============================================================ */

.calculator-impact-message {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 15px;
  padding: 17px;
  border: 1px solid rgba(190, 242, 100, 0.11);
  border-radius: 17px;
  background:
    linear-gradient(
      110deg,
      rgba(101, 163, 13, 0.08),
      rgba(101, 163, 13, 0.025)
    );
}

.calculator-impact-icon {
  display: grid;
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid rgba(190, 242, 100, 0.12);
  border-radius: 14px;
  color: #bef264;
  background: rgba(190, 242, 100, 0.06);
}

.calculator-impact-message strong {
  display: block;
  margin-bottom: 5px;
  color: #c9e7b0;
  font-size: 12px;
}

.calculator-impact-message p {
  margin: 0;
  color: #718c72;
  font-size: 10px;
  line-height: 1.6;
}

/* ============================================================
   EMPTY RESULT
   ============================================================ */

.calculator-empty {
  display: flex;
  min-height: 370px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 45px;
  text-align: center;
}

.calculator-empty-orbit {
  position: relative;
  display: grid;
  width: 92px;
  height: 92px;
  place-items: center;
  margin-bottom: 25px;
  border: 1px solid rgba(74, 222, 128, 0.14);
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.045);
  color: #4ade80;
  box-shadow:
    0 0 45px rgba(34, 197, 94, 0.07),
    inset 0 0 25px rgba(34, 197, 94, 0.035);
}

.calculator-empty-orbit::before,
.calculator-empty-orbit::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(74, 222, 128, 0.07);
  border-radius: 50%;
}

.calculator-empty-orbit::before {
  inset: -15px;
}

.calculator-empty-orbit::after {
  inset: -30px;
}

.calculator-empty h3 {
  margin: 0 0 9px;
  color: #eafff0;
  font-size: 19px;
}

.calculator-empty p {
  max-width: 380px;
  margin: 0;
  color: #6f8a7a;
  font-size: 11px;
  line-height: 1.8;
}

.calculator-disclaimer {
  margin: 19px 0 0;
  color: #405d4c;
  font-size: 8px;
  line-height: 1.6;
  text-align: center;
}

/* ============================================================
   WHY RECYCLE
   ============================================================ */

.calculator-why {
  position: relative;
  z-index: 3;
  width: 100%;
  padding: 20px clamp(22px, 5vw, 85px) 145px;
}

.calculator-why-inner {
  width: 100%;
  max-width: 1580px;
  margin: 0 auto;
}

.calculator-why-heading {
  max-width: 760px;
  margin-bottom: 32px;
}

.calculator-why-heading > span {
  display: block;
  margin-bottom: 12px;
  color: #4ade80;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.18em;
}

.calculator-why-heading h2 {
  margin: 0 0 15px;
  color: #ecfdf5;
  font-size: clamp(35px, 5vw, 55px);
  line-height: 0.98;
  letter-spacing: -0.055em;
}

.calculator-why-heading p {
  max-width: 650px;
  margin: 0;
  color: #718e7e;
  font-size: 12px;
  line-height: 1.8;
}

.calculator-benefits {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
}

.calculator-benefits article,
.calculator-benefits aside {
  position: relative;
  min-height: 225px;
  padding: 25px;
  overflow: hidden;
  border: 1px solid rgba(134, 239, 172, 0.08);
  border-radius: 23px;
  background:
    linear-gradient(
      145deg,
      rgba(10, 54, 34, 0.78),
      rgba(3, 26, 17, 0.93)
    );
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.calculator-benefits article:hover,
.calculator-benefits aside:hover {
  transform: translateY(-5px);
  border-color: rgba(74, 222, 128, 0.18);
  box-shadow: 0 25px 50px rgba(0, 0, 0, 0.20);
}

.calculator-benefits article::after,
.calculator-benefits aside::after {
  content: "";
  position: absolute;
  width: 130px;
  height: 130px;
  right: -65px;
  bottom: -65px;
  border-radius: 50%;
  background: rgba(74, 222, 128, 0.055);
  filter: blur(10px);
}

.calculator-benefits article > div:first-child {
  display: grid;
  width: 43px;
  height: 43px;
  place-items: center;
  margin-bottom: 25px;
  border: 1px solid rgba(74, 222, 128, 0.12);
  border-radius: 13px;
  background: rgba(74, 222, 128, 0.07);
  color: #4ade80;
}

.calculator-benefits article > span {
  position: absolute;
  top: 29px;
  right: 25px;
  color: #3d604d;
  font-size: 9px;
  font-weight: 850;
}

.calculator-benefits h3 {
  margin: 0 0 9px;
  color: #dff9e8;
  font-size: 15px;
}

.calculator-benefits article p {
  margin: 0;
  color: #718d7d;
  font-size: 10px;
  line-height: 1.75;
}

.calculator-benefits aside {
  display: flex;
  flex-direction: column;
  justify-content: center;
  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(74, 222, 128, 0.11),
      transparent 50%
    ),
    linear-gradient(
      145deg,
      rgba(10, 52, 33, 0.84),
      rgba(3, 25, 16, 0.95)
    );
}

.calculator-quote-mark {
  position: absolute;
  top: 17px;
  left: 23px;
  color: rgba(74, 222, 128, 0.28);
  font-family: Georgia, serif;
  font-size: 45px;
  line-height: 1;
}

.calculator-benefits blockquote {
  margin: 0 0 14px;
  color: #b8dec5;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 21px;
  line-height: 1.15;
  font-style: italic;
}

.calculator-benefits blockquote em {
  color: #4ade80;
}

.calculator-benefits aside p {
  margin: 0;
  color: #668574;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.7;
}

.calculator-benefits aside > svg {
  position: absolute;
  right: -5px;
  bottom: -10px;
  color: rgba(74, 222, 128, 0.055);
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1150px) {
  .calculator-workspace-inner {
    grid-template-columns: 1fr;
  }

  .calculator-benefits {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .calculator-globe {
    right: 5vw;
    opacity: 0.55;
  }
}

@media (max-width: 700px) {
  .calculator-hero {
    min-height: 510px;
    padding: 80px 18px 60px;
  }

  .calculator-hero h1 {
    font-size: 48px;
  }

  .calculator-globe {
    top: 45px;
    right: -35px;
    transform: scale(0.7);
    opacity: 0.35;
  }

  .calculator-orbit-one {
    width: 350px;
  }

  .calculator-orbit-two {
    width: 480px;
  }

  .calculator-workspace,
  .calculator-why {
    padding-left: 16px;
    padding-right: 16px;
  }

  .calculator-input-panel,
  .calculator-result-panel {
    padding: 23px;
    border-radius: 23px;
  }

  .calculator-panel-top h2,
  .calculator-result-heading h2 {
    font-size: 21px;
  }

  .calculator-material-copy small {
    white-space: normal;
  }

  .calculator-metrics {
    grid-template-columns: 1fr;
  }

  .calculator-benefits {
    grid-template-columns: 1fr;
  }

  .calculator-why {
    padding-bottom: 90px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .calculator-material,
  .calculator-primary-button,
  .calculator-metric,
  .calculator-benefits article,
  .calculator-benefits aside {
    transition: none;
  }
}



/* ================================================================
   HOME — VISION & MISSION DESIGN SYSTEM
   Full-page futuristic GreenCore theme
   ================================================================ */

.home-page {
  position: relative;
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  overflow: hidden;
  color: #effff5;
  background: #031b12;
}

/* subtle futuristic grid across the entire page */
.home-page::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: .25;
  background-image:
    linear-gradient(rgba(113,239,166,.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(113,239,166,.045) 1px, transparent 1px);
  background-size: 55px 55px;
  mask-image: linear-gradient(to bottom, black, transparent 92%);
}

.home-page > * {
  position: relative;
  z-index: 1;
}

.home-page .home-container {
  width: min(1280px, calc(100% - 64px));
