  font-size: clamp(40px, 4.5vw, 63px);
  line-height: .98;
  letter-spacing: -.058em;
}

.home-page .home-section-heading h2 em {
  color: #69e99e;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 500;
}

.home-page .home-section-heading > p {
  margin: 0;
  color: #789d8a;
  font-size: 12px;
  line-height: 1.8;
}

/* ================================================================
