   ================================================================ */

.home-page .home-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.home-page .home-benefit-card {
  position: relative;
  min-height: 310px;
  padding: 28px;
  overflow: hidden;
