  transition: transform .3s ease, border-color .3s ease, box-shadow .3s ease;
}

.home-page .home-benefit-card::before {
  content: "";
  position: absolute;
  width: 190px;
  height: 190px;
  right: -100px;
  bottom: -100px;
  border-radius: 50%;
  background: rgba(66,225,132,.08);
  filter: blur(3px);
}

.home-page .home-benefit-card:hover {
  transform: translateY(-7px);
  border-color: rgba(108,239,160,.29);
  box-shadow: 0 25px 60px rgba(0,0,0,.18);
}

.home-page .home-benefit-number {
  color: #4e7d66;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .16em;
}

.home-page .home-benefit-icon {
  width: 49px;
  height: 49px;
  margin: 45px 0 24px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(118,240,169,.16);
