    rotateX(67deg)
    rotateZ(22deg) !important;

  border-color: rgba(102, 230, 165, 0.10) !important;
}

/* third depth ring generated without changing JSX */
.home-hero-art::after {
  content: "";
  position: absolute;
  width: 560px;
  height: 560px;
  left: 50%;
  top: 50%;

  border: 1px solid rgba(99, 226, 161, 0.055);
  border-radius: 50%;

  transform:
    translate(-50%, -50%)
    rotateX(69deg)
    rotateZ(-34deg);

  pointer-events: none;
  z-index: -1;
}

/* ============================================================
   MAIN 3D ORB
   ============================================================ */

.home-art-orb {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;

  width: 270px !important;
  height: 270px !important;

  transform:
    translate(-50%, -50%)
    translateZ(60px) !important;

  border-radius: 50% !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  background:
    radial-gradient(
      circle at 34% 25%,
      #8df4bd 0%,
      #58dda0 12%,
      #2db978 29%,
      #118353 53%,
      #075438 72%,
      #032b1f 100%
    ) !important;

  border: 1px solid rgba(155, 255, 204, 0.28) !important;

  box-shadow:
    0 35px 80px rgba(0, 0, 0, 0.32),
    0 0 80px rgba(53, 218, 137, 0.13),
    0 0 150px rgba(34, 171, 105, 0.08),
    inset -28px -35px 60px rgba(0, 40, 27, 0.46),
    inset 22px 20px 45px rgba(176, 255, 211, 0.13) !important;

  transform-style: preserve-3d;
  z-index: 5 !important;
}

/* 3D shadow side of orb */
.home-art-orb::before {
  content: "";
  position: absolute;
  inset: 8px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle at 32% 25%,
      rgba(255, 255, 255, 0.20),
      transparent 19%
    ),
    radial-gradient(
      circle at 67% 75%,
      rgba(0, 35, 23, 0.28),
      transparent 52%
    );

  box-shadow:
    inset -18px -20px 30px rgba(0, 30, 20, 0.24),
    inset 12px 10px 24px rgba(202, 255, 223, 0.07);

  pointer-events: none;
}

/* subtle glass reflection */
.home-art-orb::after {
  content: "";
  position: absolute;

  width: 105px;
  height: 48px;

  left: 45px;
  top: 27px;

  border-radius: 50%;

  background: rgba(220, 255, 235, 0.13);

  transform: rotate(-24deg);
  filter: blur(8px);

  pointer-events: none;
}

/* ============================================================
   INNER ORB
   ============================================================ */

.home-art-orb-inner {
  position: relative !important;
  width: 145px !important;
  height: 145px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  border-radius: 50% !important;

  background:
    radial-gradient(
      circle at 34% 28%,
      rgba(125, 239, 178, 0.92),
      rgba(41, 179, 109, 0.72) 48%,
      rgba(10, 103, 62, 0.78) 100%
    ) !important;

  border: 1px solid rgba(178, 255, 214, 0.16) !important;

  box-shadow:
    0 12px 35px rgba(0, 0, 0, 0.20),
    inset 10px 10px 25px rgba(213, 255, 229, 0.08),
    inset -12px -16px 25px rgba(0, 48, 31, 0.22) !important;

  transform: translateZ(38px);
  z-index: 3;
}

.home-art-orb-inner svg {
  width: 82px !important;
  height: 82px !important;

  color: #effff6 !important;

  stroke-width: 1.45 !important;

  filter:
    drop-shadow(0 0 8px rgba(221, 255, 235, 0.20))
    drop-shadow(0 8px 20px rgba(0, 35, 22, 0.18));
}

/* ============================================================
   ORBITING LIGHT POINTS
   ============================================================ */

.home-art-ring-one::before,
.home-art-ring-one::after,
.home-art-ring-two::before,
.home-art-ring-two::after {
  content: "";
  position: absolute;

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #83efb5;

  box-shadow:
    0 0 10px rgba(113, 239, 173, 0.75),
    0 0 25px rgba(69, 220, 139, 0.35);
}

.home-art-ring-one::before {
  left: 12%;
  top: 17%;
}

.home-art-ring-one::after {
  right: 9%;
  bottom: 18%;
}

.home-art-ring-two::before {
  right: 16%;
  top: 7%;
  width: 5px;
  height: 5px;
}

.home-art-ring-two::after {
  left: 7%;
  bottom: 22%;
  width: 5px;
  height: 5px;
}

/* ============================================================
   FLOATING GLASS CARDS
   ============================================================ */

.home-floating-card {
  position: absolute !important;

  background:
    linear-gradient(
      145deg,
      rgba(11, 73, 51, 0.72),
      rgba(3, 34, 25, 0.72)
    ) !important;

  border: 1px solid rgba(115, 235, 171, 0.18) !important;

  box-shadow:
    0 30px 70px rgba(0, 0, 0, 0.30),
    inset 0 1px 0 rgba(190, 255, 216, 0.04) !important;

  backdrop-filter: blur(20px);

  transform-style: preserve-3d;
}

/* Top floating card */
.home-floating-card-top {
  left: 50% !important;
  top: 3% !important;

  width: 330px !important;

  transform:
    translateX(-50%)
    translateZ(90px)
    rotateX(2deg) !important;

  z-index: 8 !important;
}

/* Bottom floating card */
.home-floating-card-bottom {
  left: 50% !important;
  bottom: 2% !important;

  width: 350px !important;

  transform:
    translateX(-50%)
    translateZ(75px)
    rotateX(-2deg) !important;

  z-index: 8 !important;
}

/* Add dimensional shadow behind cards */
.home-floating-card-top::before,
.home-floating-card-bottom::before {
  content: "";
  position: absolute;
  inset: 7px -7px -10px;

  border-radius: inherit;

  background: rgba(0, 15, 10, 0.28);

  filter: blur(13px);

  z-index: -1;
}

/* ============================================================
   VERTICAL GLASS PILL — RIGHT SIDE
   ============================================================ */

.home-art-tag {
  position: absolute !important;

  right: 2% !important;
  top: 50% !important;

  min-width: 118px;

  transform:
    translateY(-50%)
    translateZ(110px)
    rotateY(-4deg) !important;

  padding: 20px 15px !important;

  background:
    linear-gradient(
      180deg,
      rgba(7, 61, 44, 0.74),
      rgba(2, 31, 23, 0.80)
    ) !important;

  border: 1px solid rgba(111, 232, 167, 0.16) !important;

  border-radius: 70px !important;

  box-shadow:
    25px 30px 60px rgba(0, 0, 0, 0.26),
    inset 1px 0 rgba(170, 255, 205, 0.035) !important;

  backdrop-filter: blur(22px);

  z-index: 9 !important;
}

/* ============================================================
   3D DEPTH SHADOW
   ============================================================ */

.home-hero-art .home-art-glow {
  position: absolute;
  left: 50%;
  top: 50%;

  width: 360px;
  height: 360px;

  transform:
    translate(-50%, -50%)
    translateZ(-20px);

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(61, 225, 143, 0.18),
      transparent 67%
    ) !important;

  filter: blur(12px);

  z-index: -3;
}

/* ============================================================
   SUBTLE FLOATING MOTION
   ============================================================ */

@keyframes homeOrbFloat3D {
  0% {
    transform:
      translate(-50%, -50%)
      translate3d(0, 0, 60px)
      rotateY(-2deg);
  }

  50% {
    transform:
      translate(-50%, -50%)
      translate3d(0, -8px, 78px)
      rotateY(2deg);
  }

  100% {
    transform:
      translate(-50%, -50%)
      translate3d(0, 0, 60px)
      rotateY(-2deg);
  }
}

.home-art-orb {
  animation: homeOrbFloat3D 6s ease-in-out infinite !important;
}

@keyframes homeCardFloat3D {
  0% {
    transform:
      translateX(-50%)
      translateZ(90px)
      translateY(0);
  }

  50% {
    transform:
      translateX(-50%)
      translateZ(105px)
      translateY(-5px);
  }

  100% {
    transform:
      translateX(-50%)
      translateZ(90px)
      translateY(0);
  }
}

.home-floating-card-top {
  animation: homeCardFloat3D 7s ease-in-out infinite !important;
}

@keyframes homeCardFloatBottom3D {
  0% {
    transform:
      translateX(-50%)
      translateZ(75px)
      translateY(0);
  }

  50% {
    transform:
      translateX(-50%)
      translateZ(88px)
      translateY(5px);
  }

  100% {
    transform:
      translateX(-50%)
      translateZ(75px)
      translateY(0);
  }
}

.home-floating-card-bottom {
  animation: homeCardFloatBottom3D 8s ease-in-out infinite !important;
}

