/* ============================================================
   GREENCORE SHOP — VISION & MISSION THEME
   ============================================================ */

.shop-page {
  --shop-bg: #031a14;
  --shop-bg-deep: #02140f;
  --shop-surface: rgba(7, 48, 36, 0.58);
  --shop-surface-hover: rgba(10, 64, 47, 0.72);
  --shop-border: rgba(108, 225, 163, 0.15);
  --shop-border-bright: rgba(108, 225, 163, 0.28);
  --shop-text: #f1fff7;
  --shop-muted: rgba(210, 239, 222, 0.65);
  --shop-accent: #6ee7a5;

  position: relative;
  isolation: isolate;
  min-height: 100vh;
  overflow: hidden;

  background:
    radial-gradient(
      ellipse 60% 35% at 85% 5%,
      rgba(40, 196, 121, 0.10),
      transparent 70%
    ),
    radial-gradient(
      ellipse 50% 40% at 5% 70%,
      rgba(25, 143, 88, 0.08),
      transparent 70%
    ),
    linear-gradient(
      180deg,
      #031c15 0%,
      #031913 45%,
      #02150f 100%
    ) !important;

  color: var(--shop-text);
}

/* Futuristic grid */
.shop-page::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -2;
  pointer-events: none;

  background-image:
    linear-gradient(
      rgba(108, 225, 163, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(108, 225, 163, 0.035) 1px,
      transparent 1px
    );

  background-size: 72px 72px;
  opacity: 0.75;
}

/* Atmospheric glow */
.shop-page::after {
  content: "";
  position: absolute;
  width: 600px;
  height: 600px;
  right: -350px;
  top: 300px;
  z-index: -1;
  pointer-events: none;

  border-radius: 50%;
  background: rgba(37, 188, 114, 0.07);
  filter: blur(80px);
}

/* ============================================================
   SHOP HEAD / HERO
   ============================================================ */

.shop-page h1,
.shop-page h2,
.shop-page h3,
.shop-page h4 {
  color: var(--shop-text) !important;
}

.shop-page p {
  color: var(--shop-muted);
}

/* Common shop container */
.shop-page > * {
  position: relative;
  z-index: 1;
}

/* ============================================================
   SEARCH / FILTER CONTROLS
   ============================================================ */

.shop-page input,
.shop-page select,
.shop-page textarea {
  color: #effff5 !important;

  background:
    rgba(4, 37, 28, 0.72) !important;

  border: 1px solid var(--shop-border) !important;

  box-shadow:
    inset 0 1px 0 rgba(174, 255, 211, 0.025) !important;

  backdrop-filter: blur(16px);
}

.shop-page input::placeholder {
  color: rgba(196, 231, 211, 0.42) !important;
}

.shop-page input:focus,
.shop-page select:focus,
.shop-page textarea:focus {
  outline: none !important;
  border-color: var(--shop-border-bright) !important;

  box-shadow:
    0 0 0 3px rgba(74, 224, 148, 0.06),
    0 0 25px rgba(51, 205, 128, 0.05) !important;
}

/* Filter buttons */
.shop-page button {
  color: #dff9ea;
}

.shop-page button:not([aria-label]):hover {
  color: #f2fff7;
}

/* ============================================================
   CATEGORY / FILTER PILLS
   ============================================================ */

.shop-page [class*="filter"],
.shop-page [class*="category"],
.shop-page [class*="pill"] {
  border-color: rgba(108, 225, 163, 0.14) !important;
}

.shop-page [class*="filter"] button,
.shop-page [class*="category"] button,
.shop-page [class*="pill"] button {
  background: rgba(6, 48, 36, 0.55) !important;
  color: rgba(216, 244, 227, 0.72) !important;
  border-color: rgba(108, 225, 163, 0.13) !important;
}

.shop-page [class*="filter"] button:hover,
.shop-page [class*="category"] button:hover,
.shop-page [class*="pill"] button:hover {
  background: rgba(11, 70, 51, 0.68) !important;
  color: #f1fff7 !important;
  border-color: rgba(108, 225, 163, 0.27) !important;
}

/* Active filter */
.shop-page [class*="active"] {
  color: #032117 !important;
}

/* ============================================================
   PRODUCT GRID
   ============================================================ */

.shop-page [class*="grid"] {
  position: relative;
}

/* Product cards */
.shop-page [class*="product-card"],
.shop-page [class*="ProductCard"] {
  background:
    linear-gradient(
      145deg,
      rgba(9, 62, 46, 0.62),
      rgba(3, 35, 26, 0.70)
    ) !important;

  border: 1px solid rgba(108, 225, 163, 0.14) !important;

  border-radius: 20px;

  box-shadow:
    0 22px 60px rgba(0, 0, 0, 0.18),
    inset 0 1px 0 rgba(175, 255, 211, 0.025) !important;

  backdrop-filter: blur(18px);

  transition:
    transform 240ms ease,
    border-color 240ms ease,
    box-shadow 240ms ease,
    background 240ms ease;
}

.shop-page [class*="product-card"]:hover,
.shop-page [class*="ProductCard"]:hover {
  transform: translateY(-5px);

  background:
    linear-gradient(
      145deg,
      rgba(11, 74, 54, 0.72),
      rgba(4, 40, 29, 0.76)
    ) !important;

  border-color: rgba(108, 225, 163, 0.27) !important;

  box-shadow:
    0 28px 70px rgba(0, 0, 0, 0.25),
    0 0 35px rgba(52, 211, 132, 0.045) !important;
}

/* Product images */
.shop-page [class*="product-card"] img,
.shop-page [class*="ProductCard"] img {
  background:
    linear-gradient(
      145deg,
      rgba(9, 70, 51, 0.55),
      rgba(2, 31, 23, 0.65)
    ) !important;
}

/* Product names */
.shop-page [class*="product-card"] h3,
.shop-page [class*="ProductCard"] h3 {
  color: #effff5 !important;
}

/* Product descriptions */
.shop-page [class*="product-card"] p,
.shop-page [class*="ProductCard"] p {
  color: rgba(210, 239, 222, 0.62) !important;
}

/* Prices */
.shop-page [class*="price"],
.shop-page [class*="Price"] {
  color: #76eaaa !important;
  font-weight: 700;
}

/* ============================================================
   PRODUCT ACTION BUTTONS
   ============================================================ */

.shop-page [class*="product-card"] button,
.shop-page [class*="ProductCard"] button {
  background: rgba(7, 54, 40, 0.70);
  color: #dff9ea;
  border: 1px solid rgba(108, 225, 163, 0.15);
}

.shop-page [class*="product-card"] button:hover,
.shop-page [class*="ProductCard"] button:hover {
  background: rgba(17, 91, 64, 0.78);
  color: #f3fff8;
  border-color: rgba(108, 225, 163, 0.30);
}

/* Primary shopping buttons */
.shop-page a[class*="primary"],
.shop-page button[class*="primary"],
.shop-page [class*="add-to-cart"],
.shop-page [class*="addToCart"] {
  background:
    linear-gradient(
      135deg,
      #70e9aa,
      #35c980
    ) !important;

  color: #032016 !important;

  border: 1px solid rgba(153, 255, 199, 0.25) !important;

  box-shadow:
    0 12px 35px rgba(29, 192, 113, 0.10) !important;
}

.shop-page a[class*="primary"]:hover,
.shop-page button[class*="primary"]:hover,
.shop-page [class*="add-to-cart"]:hover,
.shop-page [class*="addToCart"]:hover {
  background:
    linear-gradient(
      135deg,
      #88f2ba,
      #4bdd91
    ) !important;

  box-shadow:
    0 0 28px rgba(80, 225, 148, 0.13) !important;
}

/* ============================================================
   BADGES
   ============================================================ */

.shop-page [class*="badge"],
.shop-page [class*="tag"] {
  background: rgba(42, 169, 104, 0.16) !important;
  color: #8aefba !important;
  border: 1px solid rgba(108, 225, 163, 0.16) !important;
}

/* ============================================================
   SORT / RESULTS BAR
   ============================================================ */

.shop-page [class*="sort"],
.shop-page [class*="toolbar"],
.shop-page [class*="results"] {
  color: rgba(210, 239, 222, 0.65);
}

/* ============================================================
   EMPTY STATE
   ============================================================ */

.shop-page [class*="empty"] {
  background:
    linear-gradient(
      145deg,
      rgba(8, 58, 43, 0.55),
      rgba(3, 35, 26, 0.65)
    ) !important;

  border: 1px solid rgba(108, 225, 163, 0.14) !important;
  color: #effff5 !important;
  backdrop-filter: blur(18px);
}

.shop-page [class*="empty"] p {
  color: rgba(210, 239, 222, 0.62) !important;
}

/* ============================================================
   ICONS
   ============================================================ */

.shop-page svg {
  color: #73e9ad;
}

.shop-page [class*="product-card"] svg,
.shop-page [class*="ProductCard"] svg {
  color: #7cebb2;
}

/* ============================================================
   SECTION DIVIDERS
   ============================================================ */

.shop-page hr {
  border: 0 !important;
  border-top: 1px solid rgba(108, 225, 163, 0.09) !important;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 900px) {
  .shop-page::before {
    background-size: 58px 58px;
  }

  .shop-page [class*="product-card"],
  .shop-page [class*="ProductCard"] {
