   ============================================================ */

.categories-page {
  --cat-bg: #031a14;
  --cat-bg-deep: #02140f;
  --cat-surface: rgba(7, 53, 40, 0.58);
  --cat-surface-hover: rgba(10, 70, 51, 0.72);
  --cat-border: rgba(108, 225, 163, 0.15);
  --cat-border-bright: rgba(108, 225, 163, 0.30);
  --cat-text: #f1fff7;
  --cat-muted: rgba(210, 239, 222, 0.67);
  --cat-accent: #6ee7a5;

  position: relative;
  isolation: isolate;
  min-height: 100vh;
  overflow: hidden;

  background:
    radial-gradient(
      ellipse 65% 35% at 85% 5%,
      rgba(40, 196, 121, 0.11),
      transparent 70%
    ),
    radial-gradient(
      ellipse 50% 45% at 5% 72%,
      rgba(25, 143, 88, 0.08),
      transparent 70%
    ),
    linear-gradient(
      180deg,
      #031c15 0%,
      #031913 45%,
      #02150f 100%
    ) !important;

  color: var(--cat-text);
}

/* Futuristic background grid */
.categories-page::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -2;
  pointer-events: none;

  background-image:
    linear-gradient(
      rgba(108, 225, 163, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(108, 225, 163, 0.035) 1px,
      transparent 1px
    );

  background-size: 72px 72px;
  opacity: 0.75;
}

/* Atmospheric glow */
