/* =========================================================
   GREENCORE — CUSTOMER ORDER EXPERIENCE
   Order History / Order Details / Tracking / Confirmation
   ========================================================= */

.orders-page,
.order-page {
  min-height: calc(100vh - 80px);
  padding: 48px 24px 80px;
  background:
    radial-gradient(circle at 15% 10%, rgba(16, 185, 129, 0.10), transparent 30%),
    radial-gradient(circle at 85% 25%, rgba(34, 211, 238, 0.07), transparent 28%),
    linear-gradient(180deg, #06110d 0%, #071713 48%, #04100c 100%);
  color: #ecfdf5;
}

.orders-page > *,
.order-page > * {
  position: relative;
  z-index: 1;
}

/* ---------- Shared page container ---------- */

.orders-page,
.order-page {
  position: relative;
  overflow: hidden;
}

.orders-page::before,
.order-page::before {
  content: "";
  position: absolute;
  width: 520px;
  height: 520px;
  top: -220px;
  right: -180px;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.08);
  filter: blur(90px);
  pointer-events: none;
}

.orders-page::after,
.order-page::after {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  bottom: -220px;
  left: -160px;
  border-radius: 50%;
  background: rgba(34, 211, 238, 0.045);
  filter: blur(90px);
  pointer-events: none;
}

/* =========================================================
   ORDER HISTORY
   ========================================================= */

.orders-card {
  width: min(1120px, 100%);
  margin: 0 auto;
  padding: 32px;
  border: 1px solid rgba(110, 231, 183, 0.14);
  border-radius: 28px;
  background:
    linear-gradient(
      145deg,
      rgba(10, 35, 27, 0.90),
      rgba(5, 20, 15, 0.78)
    );
  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(22px);
}

.orders-card h1,
.orders-card h2 {
  color: #f0fdf4;
}

.orders-heading,
.orders-card > header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.orders-heading h1,
.orders-card > header h1 {
  margin: 0;
  color: #f0fdf4;
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 750;
  letter-spacing: -0.035em;
}

.orders-heading p,
.orders-card > header p {
  margin: 8px 0 0;
  color: #8fb8a6;
  font-size: 14px;
}

.orders-page .account-order-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 38px;
  height: 30px;
  padding: 0 12px;
  border: 1px solid rgba(110, 231, 183, 0.18);
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.09);
  color: #86efac;
  font-size: 13px;
  font-weight: 700;
}

/* ---------- Order list ---------- */

.orders-page .order-list,
.orders-page .account-order-list {
  display: grid;
  gap: 14px;
}

.orders-page .order-card,
.orders-page .account-order-card {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 18px;
  min-height: 92px;
  padding: 18px 20px;
  border: 1px solid rgba(110, 231, 183, 0.10);
  border-radius: 20px;
  background: rgba(7, 29, 22, 0.68);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background 180ms ease,
    box-shadow 180ms ease;
}

.orders-page .order-card:hover,
.orders-page .account-order-card:hover {
  transform: translateY(-2px);
  border-color: rgba(110, 231, 183, 0.25);
  background: rgba(9, 39, 29, 0.82);
  box-shadow:
    0 14px 34px rgba(0, 0, 0, 0.20),
    0 0 24px rgba(16, 185, 129, 0.045);
}

.orders-page .order-icon,
.orders-page .account-order-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(110, 231, 183, 0.16);
  border-radius: 15px;
  background: rgba(16, 185, 129, 0.08);
  color: #6ee7b7;
}

.orders-page .order-main,
.orders-page .account-order-main {
  min-width: 0;
}

.orders-page .order-main a,
.orders-page .account-order-main a {
  color: #ecfdf5;
  text-decoration: none;
}

.orders-page .order-main a:hover,
.orders-page .account-order-main a:hover {
  color: #86efac;
}

.orders-page .order-id {
  color: #d1fae5;
  font-size: 15px;
  font-weight: 700;
}

.orders-page .order-date {
  margin-top: 5px;
  color: #76998a;
  font-size: 12px;
}

.orders-page .order-status,
.orders-page .account-order-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  min-height: 28px;
  padding: 4px 10px;
  border: 1px solid rgba(110, 231, 183, 0.14);
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.07);
  color: #86efac;
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.orders-page .order-total,
.orders-page .account-order-total {
  color: #f0fdf4;
  font-size: 17px;
  font-weight: 750;
  white-space: nowrap;
}

/* ---------- Empty / error states ---------- */

.orders-page .orders-empty,
.orders-page .account-empty-card,
.orders-page .orders-error,
.orders-page .account-error-card {
  padding: 54px 28px;
  border: 1px solid rgba(110, 231, 183, 0.10);
  border-radius: 22px;
  background: rgba(5, 25, 18, 0.62);
  text-align: center;
}

.orders-page .orders-empty h2,
.orders-page .account-empty-card h2 {
  margin: 0 0 8px;
  color: #d1fae5;
}

.orders-page .orders-empty p,
.orders-page .account-empty-card p {
  margin: 0;
  color: #76998a;
}

/* =========================================================
   ORDER DETAILS
   ========================================================= */

.order-details-hero {
  width: min(1120px, 100%);
  margin: 0 auto 22px;
  padding: 30px 32px;
  border: 1px solid rgba(110, 231, 183, 0.14);
  border-radius: 28px;
  background:
    linear-gradient(
      135deg,
      rgba(11, 45, 33, 0.88),
      rgba(5, 24, 18, 0.78)
    );
  box-shadow:
    0 22px 60px rgba(0, 0, 0, 0.30),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(20px);
}

.order-details-hero h1 {
  margin: 0;
  color: #f0fdf4;
  font-size: clamp(26px, 4vw, 40px);
  font-weight: 750;
  letter-spacing: -0.035em;
}

.order-details-hero p {
  margin: 8px 0 0;
  color: #82a898;
  font-size: 14px;
}

.order-details-hero .order-status {
  margin-top: 18px;
}

/* ---------- Detail panels ---------- */

.order-panel {
  width: min(1120px, 100%);
  margin: 0 auto 18px;
  padding: 26px;
  border: 1px solid rgba(110, 231, 183, 0.11);
  border-radius: 24px;
  background: rgba(6, 27, 20, 0.72);
  box-shadow:
    0 16px 42px rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
  backdrop-filter: blur(18px);
}

.order-panel h2,
.order-panel h3 {
  margin: 0;
  color: #dffbea;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.order-panel p {
  color: #82a898;
}

/* ---------- Items ---------- */

.order-items {
  display: grid;
  gap: 10px;
  margin-top: 18px;
}

.order-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 15px 16px;
  border: 1px solid rgba(110, 231, 183, 0.075);
  border-radius: 16px;
  background: rgba(4, 20, 15, 0.62);
}

.order-item strong {
  display: block;
  color: #d1fae5;
  font-size: 14px;
}

.order-item small {
  display: block;
  margin-top: 4px;
  color: #688b7c;
  font-size: 12px;
}

.order-item-price {
  color: #a7f3d0;
  font-weight: 700;
  white-space: nowrap;
}

/* ---------- Order summary ---------- */

.order-summary {
  display: grid;
  gap: 10px;
}

.order-summary-row {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  color: #8fb8a6;
  font-size: 14px;
}

.order-summary-row strong {
  color: #d1fae5;
}

.order-summary-total {
  margin-top: 8px;
  padding-top: 15px;
  border-top: 1px solid rgba(110, 231, 183, 0.10);
}

.order-summary-total span,
.order-summary-total strong {
  color: #f0fdf4;
  font-size: 18px;
  font-weight: 750;
}

/* =========================================================
   ORDER TRACKING
   ========================================================= */

.order-tracking {
  position: relative;
  margin-top: 22px;
  padding: 8px 0;
}

.order-tracking::before {
  content: "";
  position: absolute;
  top: 29px;
  left: 22px;
  right: 22px;
  height: 1px;
  background: rgba(110, 231, 183, 0.12);
}

.tracking-steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
}

.tracking-step {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  text-align: center;
}

.tracking-step-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid rgba(110, 231, 183, 0.13);
  border-radius: 50%;
  background: #071b14;
  color: #496f5f;
  box-shadow: 0 0 0 6px #071b14;
  transition:
    color 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    background 180ms ease;
}

.tracking-step.active .tracking-step-icon,
.tracking-step.completed .tracking-step-icon {
  border-color: rgba(110, 231, 183, 0.34);
  background: rgba(16, 185, 129, 0.12);
  color: #6ee7b7;
  box-shadow:
    0 0 0 6px #071b14,
    0 0 24px rgba(16, 185, 129, 0.14);
}

.tracking-step span {
  color: #5f8173;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.tracking-step.active span,
.tracking-step.completed span {
  color: #a7f3d0;
}

/* ---------- Shipping address ---------- */

.order-address {
  margin-top: 16px;
  padding: 16px 18px;
  border: 1px solid rgba(110, 231, 183, 0.08);
  border-radius: 16px;
  background: rgba(4, 20, 15, 0.55);
  color: #9bc0b0;
  line-height: 1.65;
}

/* ---------- Cancellation ---------- */

.order-cancel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 22px;
  padding: 17px 18px;
  border: 1px solid rgba(248, 113, 113, 0.13);
  border-radius: 18px;
  background: rgba(127, 29, 29, 0.08);
}

.order-cancel p {
  margin: 0;
  color: #b99595;
  font-size: 13px;
}

.order-cancel button {
  flex: 0 0 auto;
  min-height: 42px;
  padding: 0 18px;
  border: 1px solid rgba(248, 113, 113, 0.25);
  border-radius: 12px;
  background: rgba(127, 29, 29, 0.18);
  color: #fca5a5;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.order-cancel button:hover {
  transform: translateY(-1px);
  border-color: rgba(248, 113, 113, 0.42);
  background: rgba(127, 29, 29, 0.28);
}

.order-cancel button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

/* =========================================================
   ORDER CONFIRMATION
   ========================================================= */

.order-confirmation {
  width: min(900px, 100%);
  margin: 42px auto 0;
  padding: 44px 38px;
  border: 1px solid rgba(110, 231, 183, 0.15);
  border-radius: 30px;
  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(16, 185, 129, 0.11),
      transparent 42%
    ),
    linear-gradient(
      145deg,
      rgba(9, 38, 29, 0.92),
      rgba(5, 22, 16, 0.84)
    );
  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.38),
    0 0 60px rgba(16, 185, 129, 0.045),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  text-align: center;
  backdrop-filter: blur(24px);
}

