  .orders-page .order-card {
    grid-template-columns: 44px minmax(0,1fr) !important;
    padding: 16px !important;
  }

  .orders-page .account-order-total,
  .orders-page .order-total {
    grid-column: 2;
    justify-self: start;
  }

  .order-page .tracking-steps {
    grid-template-columns: repeat(3, 1fr) !important;
    row-gap: 23px;
  }

  .order-page .order-tracking::before {
    display: none !important;
  }

  .order-page .order-confirmation {
    padding: 42px 22px !important;
  }

  .order-page .order-cancel {
    align-items: stretch !important;
    flex-direction: column !important;
  }

  .order-page .order-cancel button {
    width: 100% !important;
  }
}

@media (max-width: 480px) {
  .orders-page,
  .order-page {
    padding: 35px 12px 65px !important;
  }

  .orders-page .orders-card h1 {
    font-size: 34px !important;
  }

  .order-page .order-details-hero,
  .order-page .order-panel {
    padding: 20px 17px !important;
    border-radius: 18px !important;
  }

  .order-page .tracking-steps {
    grid-template-columns: repeat(2, 1fr) !important;
  }

  .order-page .order-confirmation h1 {
    font-size: 35px !important;
  }

  .order-page .order-confirmation-actions {
    flex-direction: column !important;
  }

  .order-page .order-confirmation-actions a,
  .order-page .order-confirmation-actions button {
    width: 100% !important;
  }
}


/* ============================================================
   GREENCORE — FUTURISTIC ORDERS DASHBOARD
   Reference-inspired visual system
   ============================================================ */

.rp-orders-dashboard {
  position: relative;
  min-height: 100vh;
  padding: 72px 0 0 !important;
  overflow: hidden;
  color: #ecfff5;
  background:
    radial-gradient(
      900px 600px at 72% 18%,
      rgba(0, 255, 157, 0.075),
      transparent 65%
    ),
    radial-gradient(
      700px 600px at 5% 65%,
      rgba(0, 190, 120, 0.06),
      transparent 70%
    ),
    linear-gradient(
      180deg,
      #020b08 0%,
      #03130d 48%,
      #020a07 100%
    ) !important;
}

/* atmospheric grid */
.rp-orders-dashboard::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .42;
  background-image:
    radial-gradient(
      circle,
      rgba(80, 255, 178, .22) 1px,
      transparent 1px
    );
  background-size: 22px 22px;
  mask-image:
    linear-gradient(
      90deg,
      rgba(0,0,0,.8),
      transparent 40%,
      transparent 70%,
      rgba(0,0,0,.7)
    );
}

/* huge ambient glow */
.rp-orders-dashboard::after {
  content: "";
  position: absolute;
  width: 900px;
  height: 900px;
  top: -350px;
  right: -180px;
  border-radius: 50%;
  background: rgba(0, 255, 157, .035);
  filter: blur(130px);
  pointer-events: none;
}

.rp-orders-shell {
  position: relative;
  z-index: 2;
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}

/* ============================================================
   HERO
   ============================================================ */

.rp-orders-hero {
  position: relative;
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  min-height: 390px;
  align-items: center;
  gap: 30px;
}

.rp-orders-hero-copy {
  position: relative;
  z-index: 3;
}

.rp-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 13px;
  border: 1px solid rgba(73, 255, 169, .22);
  border-radius: 999px;
  background: rgba(0, 255, 157, .065);
  color: #52eda5;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .15em;
  box-shadow:
    0 0 24px rgba(0, 255, 157, .04),
    inset 0 1px 0 rgba(255,255,255,.03);
}

.rp-orders-hero h1 {
  max-width: 680px;
  margin: 22px 0 17px;
  color: #f2fff8 !important;
  font-size: clamp(48px, 6vw, 76px) !important;
  line-height: .94 !important;
  letter-spacing: -.065em !important;
  font-weight: 780 !important;
  text-shadow:
    0 0 40px rgba(110, 255, 188, .06);
}

.rp-orders-hero h1 span {
  color: #48f3a3;
}

.rp-orders-hero-copy > p {
  margin: 0;
  color: #7ea897 !important;
  font-size: 14px !important;
  line-height: 1.75 !important;
}

/* ============================================================
   STATS
   ============================================================ */

.rp-order-stats {
  display: flex;
  gap: 12px;
  margin-top: 30px;
}

.rp-order-stat {
  position: relative;
  display: grid;
  grid-template-columns: 43px auto;
  grid-template-rows: auto auto;
  column-gap: 12px;
  min-width: 158px;
  padding: 14px 16px;
  border: 1px solid rgba(86, 255, 178, .12);
  border-radius: 17px;
  background:
    linear-gradient(
      145deg,
      rgba(7, 40, 28, .85),
      rgba(3, 20, 14, .72)
    );
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025),
    0 15px 40px rgba(0,0,0,.16);
  backdrop-filter: blur(15px);
}

.rp-stat-icon {
  grid-row: 1 / span 2;
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  border: 1px solid rgba(79,255,174,.25);
  border-radius: 13px;
  background: rgba(0,255,157,.08);
  color: #63efad;
  box-shadow:
    0 0 20px rgba(0,255,157,.055);
}

.rp-order-stat strong {
  align-self: end;
  color: #edfff6;
  font-size: 21px;
  line-height: 1;
  font-weight: 760;
}

.rp-order-stat small {
  align-self: start;
  margin-top: 4px;
  color: #688d7d;
  font-size: 9px;
  font-weight: 650;
}

/* ============================================================
   HERO ART — CSS GENERATED
   ============================================================ */

.rp-orders-hero-art {
  position: relative;
  height: 390px;
  overflow: hidden;
}

.rp-orders-hero-art::before {
  content: "";
  position: absolute;
  width: 390px;
  height: 390px;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 50%;
  background:
    radial-gradient(
      circle,
      rgba(0,255,157,.10),
      rgba(0,255,157,.025) 35%,
      transparent 70%
    );
  filter: blur(5px);
}

.rp-orbit {
  position: absolute;
  left: 50%;
  top: 48%;
  border: 1px solid rgba(61, 255, 170, .13);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.rp-orbit-one {
  width: 320px;
  height: 145px;
  transform:
    translate(-50%, -50%)
    rotate(-18deg);
}

.rp-orbit-two {
  width: 390px;
  height: 185px;
  transform:
    translate(-50%, -50%)
    rotate(22deg);
  border-color: rgba(34, 211, 238, .07);
}

.rp-hero-package {
  position: absolute;
  top: 46%;
  left: 52%;
  display: grid;
  place-items: center;
  width: 150px;
  height: 150px;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(77,255,175,.30);
  border-radius: 22px;
  background:
    linear-gradient(
      145deg,
      rgba(16, 185, 129, .22),
      rgba(3, 31, 21, .9)
    );
  color: #6df4ae;
  box-shadow:
    0 0 55px rgba(0,255,157,.14),
    0 30px 80px rgba(0,0,0,.45),
    inset 0 1px 0 rgba(255,255,255,.07);
  transform-style: preserve-3d;
}

.rp-hero-package svg:last-child {
  position: absolute;
  bottom: 23px;
  right: 24px;
}

.rp-hero-message {
  position: absolute;
  top: 25%;
  right: 0;
  width: 180px;
}

.rp-hero-message small {
  display: block;
  color: #79a996;
  font-size: 11px;
}

.rp-hero-message strong {
  display: block;
  margin-top: 5px;
  color: #54efa5;
  font-size: 17px;
}

.rp-hero-message p {
  margin-top: 12px;
  color: #719688;
  font-size: 11px;
  line-height: 1.65;
}

.rp-hero-message::after {
  content: "";
  display: block;
  width: 25px;
  height: 2px;
  margin-top: 17px;
  background: #52eaa2;
  box-shadow: 0 0 15px rgba(82,234,162,.35);
}

/* ============================================================
   TOOLBAR
   ============================================================ */

.rp-orders-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin: 4px 0 17px;
}

.rp-order-filters {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
}

.rp-order-filters button {
  min-height: 38px;
  padding: 0 16px;
  border: 1px solid rgba(92,255,178,.10);
  border-radius: 999px;
  background: rgba(5,28,20,.68);
  color: #719789;
  font: inherit;
  font-size: 10px;
  font-weight: 720;
  cursor: pointer;
  transition: .2s ease;
}

.rp-order-filters button:hover {
  border-color: rgba(92,255,178,.22);
  color: #b9e9d1;
}

.rp-order-filters button.active {
  border-color: rgba(66,255,166,.55);
  background:
    linear-gradient(
      135deg,
      #39eda0,
      #16c982
    );
  color: #022217;
  box-shadow:
    0 0 25px rgba(57,237,160,.15);
}

.rp-order-search {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 190px;
  height: 38px;
  padding: 0 13px;
  border: 1px solid rgba(92,255,178,.11);
  border-radius: 12px;
  background: rgba(5,28,20,.65);
  color: #557c6b;
  backdrop-filter: blur(12px);
}

.rp-order-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #c9f6dc;
  font: inherit;
  font-size: 10px;
}

.rp-order-search input::placeholder {
  color: #527365;
}

/* ============================================================
   MAIN ORDER LAYOUT
   ============================================================ */

.rp-orders-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 278px;
  gap: 18px;
  align-items: start;
}

.rp-orders-list {
  display: grid;
  gap: 9px;
}

/* ============================================================
   ORDER ROW
   ============================================================ */

.rp-order-row {
  position: relative;
  display: grid;
  grid-template-columns: 86px minmax(190px, 1fr) 130px 145px;
  align-items: center;
  gap: 16px;
  min-height: 112px;
  padding: 13px 17px;
  border: 1px solid rgba(70,255,169,.13);
  border-radius: 17px;
  background:
    linear-gradient(
      110deg,
      rgba(5,34,24,.91),
      rgba(2,20,14,.76)
    );
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025),
    0 14px 45px rgba(0,0,0,.18);
  overflow: hidden;
  transition:
    transform .25s ease,
    border-color .25s ease,
    box-shadow .25s ease;
}

.rp-order-row::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(
      105deg,
      rgba(0,255,157,.035),
      transparent 38%
    );
}

.rp-order-row:hover {
  transform: translateY(-2px);
  border-color: rgba(72,255,173,.30);
  box-shadow:
    0 20px 55px rgba(0,0,0,.25),
    0 0 30px rgba(0,255,157,.035);
}

.rp-order-product-art {
  position: relative;
  display: grid;
  place-items: center;
  width: 76px;
  height: 78px;
  border: 1px solid rgba(82,255,175,.13);
  border-radius: 13px;
  background:
    radial-gradient(
      circle at 50% 25%,
      rgba(0,255,157,.13),
      transparent 65%
    ),
    #071c14;
  color: #53e5a1;
}

.rp-order-product-art::after {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(82,255,175,.045);
  border-radius: 9px;
}

.rp-order-info {
  min-width: 0;
}

.rp-order-number {
  color: #d7f9e7;
  font-size: 12px;
  font-weight: 760;
  letter-spacing: .02em;
}

.rp-order-date {
  margin-top: 7px;
  color: #769b8a;
  font-size: 10px;
}

.rp-order-items-count {
  margin-top: 6px;
  color: #4e7464;
  font-size: 9px;
}

.rp-order-middle {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 9px;
}

.rp-order-middle > strong {
  color: #ecfff5;
  font-size: 17px;
  font-weight: 760;
}

/* ============================================================
   STATUS PILLS
   ============================================================ */

.rp-order-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  min-height: 25px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .09em;
  text-transform: uppercase;
}

.rp-order-status.pending {
  border: 1px solid rgba(245,190,55,.25);
  background: rgba(245,190,55,.08);
  color: #f2c95b;
}

.rp-order-status.processing {
  border: 1px solid rgba(90,183,255,.25);
  background: rgba(90,183,255,.08);
  color: #72c8ff;
}

.rp-order-status.shipped {
  border: 1px solid rgba(37,196,255,.25);
  background: rgba(37,196,255,.08);
  color: #48d1ff;
}

.rp-order-status.delivered {
  border: 1px solid rgba(42,245,150,.28);
  background: rgba(42,245,150,.09);
  color: #4af3a4;
}

.rp-order-status.cancelled {
  border: 1px solid rgba(255,83,83,.27);
  background: rgba(255,83,83,.07);
  color: #ff7777;
}

/* ============================================================
   ORDER ACTIONS
   ============================================================ */

.rp-order-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
}

.rp-order-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid rgba(61,255,166,.30);
  border-radius: 11px;
  background: rgba(0,255,157,.045);
  color: #a4f5c9;
  font-size: 9px;
  font-weight: 750;
  text-decoration: none;
  transition: .2s ease;
}

.rp-order-actions a:hover {
  border-color: rgba(61,255,166,.55);
  background: rgba(0,255,157,.10);
  box-shadow: 0 0 22px rgba(0,255,157,.07);
}

.rp-order-actions button {
  min-height: 27px;
  border: 0;
  background: transparent;
  color: #6e8379;
  font: inherit;
  font-size: 9px;
  cursor: pointer;
}

.rp-order-actions button:hover {
  color: #e08383;
}

.rp-order-actions button:disabled {
  opacity: .5;
  cursor: wait;
}

/* ============================================================
   SIDEBAR
   ============================================================ */

.rp-orders-sidebar {
  display: grid;
  gap: 13px;
}

.rp-impact-card,
.rp-rewards-card {
  position: relative;
  overflow: hidden;
  padding: 22px;
  border: 1px solid rgba(55,255,165,.18);
  border-radius: 19px;
  background:
    radial-gradient(
      230px 180px at 100% 0%,
      rgba(0,255,157,.095),
      transparent 70%
    ),
    linear-gradient(
      145deg,
      rgba(7,40,28,.86),
      rgba(3,21,15,.78)
    );
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.035),
    0 20px 55px rgba(0,0,0,.22);
}

.rp-impact-card::after {
  content: "";
  position: absolute;
  width: 230px;
  height: 110px;
  right: -50px;
  bottom: 10px;
  border-top: 2px solid rgba(57,255,169,.35);
  border-radius: 50%;
  transform: rotate(-12deg);
  box-shadow:
    0 -10px 25px rgba(57,255,169,.06);
}

.rp-sidebar-icon {
  display: grid;
  place-items: center;
  width: 39px;
  height: 39px;
  margin-bottom: 19px;
  border: 1px solid rgba(76,255,174,.25);
  border-radius: 12px;
  background: rgba(0,255,157,.10);
  color: #59eda7;
}

.rp-impact-card small {
  display: block;
  color: #4de59e;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .15em;
}

.rp-impact-card > strong {
  display: block;
  margin-top: 12px;
  color: #f0fff7;
  font-size: 34px;
  line-height: 1;
  font-weight: 760;
}

.rp-impact-card p {
  max-width: 200px;
  margin: 10px 0 0;
  color: #729789;
  font-size: 10px;
  line-height: 1.6;
}

.rp-impact-line {
  width: 28px;
  height: 2px;
  margin-top: 23px;
  background: #4ff0a4;
  box-shadow: 0 0 15px rgba(79,240,164,.35);
}

.rp-impact-card em {
  display: block;
  max-width: 205px;
  margin-top: 17px;
  color: #789a8d;
  font-size: 9px;
  line-height: 1.6;
  font-style: normal;
}

.rp-rewards-card {
  padding-bottom: 20px;
}

.rp-rewards-card > strong {
  display: block;
  color: #a9f3ca;
  font-size: 12px;
}

.rp-rewards-card p {
  margin: 8px 0 17px;
  color: #688d7d;
  font-size: 9px;
  line-height: 1.6;
}

.rp-reward-progress {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255,255,255,.055);
}

.rp-reward-progress span {
  display: block;
  width: 64%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    #19c982,
    #55f0ac
  );
  box-shadow: 0 0 15px rgba(45,238,158,.22);
}

.rp-rewards-card > small {
  display: block;
  margin-top: 9px;
  color: #537668;
  font-size: 8px;
}

/* ============================================================
   LOADING / EMPTY / ERROR
   ============================================================ */

.rp-orders-loading,
.rp-orders-empty,
.rp-orders-error {
  border: 1px solid rgba(79,255,174,.11);
  border-radius: 19px;
  background: rgba(4,27,19,.68);
  text-align: center;
}

.rp-orders-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  min-height: 260px;
  color: #719687;
  font-size: 11px;
}

.rp-loading-orb {
  display: grid;
  place-items: center;
  width: 45px;
  height: 45px;
  border: 1px solid rgba(78,255,174,.25);
  border-radius: 50%;
  color: #5aefa8;
  animation: rp-order-spin 1.5s linear infinite;
}

@keyframes rp-order-spin {
  to {
    transform: rotate(360deg);
  }
}

.rp-orders-empty {
  padding: 60px 20px;
}

.rp-orders-empty > svg {
  color: #51e8a2;
}

.rp-orders-empty h2 {
  margin: 16px 0 7px;
  color: #eafff3;
  font-size: 20px;
}

.rp-orders-empty p {
  margin: 0;
  color: #698d7e;
  font-size: 11px;
}

.rp-orders-empty a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 20px;
  padding: 11px 16px;
  border: 1px solid rgba(68,255,170,.27);
  border-radius: 10px;
  background: rgba(0,255,157,.07);
  color: #88efba;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
}

.rp-orders-error {
  margin-bottom: 13px;
  padding: 13px 16px;
  border-color: rgba(255,91,91,.18);
  background: rgba(127,29,29,.09);
  color: #e99a9a;
  font-size: 10px;
  text-align: left;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1050px) {
  .rp-orders-hero {
    grid-template-columns: 1fr .7fr;
  }

  .rp-orders-layout {
    grid-template-columns: 1fr;
  }

  .rp-orders-sidebar {
    grid-template-columns: repeat(2, 1fr);
  }

  .rp-order-row {
    grid-template-columns: 76px minmax(0,1fr) 120px;
  }

  .rp-order-actions {
    grid-column: 2 / -1;
    flex-direction: row;
    justify-content: flex-start;
  }

  .rp-order-actions a {
    width: 150px;
  }
}

@media (max-width: 780px) {
  .rp-orders-dashboard {
    padding-top: 45px !important;
  }

  .rp-orders-shell {
    width: min(100% - 28px, 620px);
  }

  .rp-orders-hero {
    display: block;
    min-height: auto;
  }

  .rp-orders-hero h1 {
    font-size: clamp(40px, 12vw, 58px) !important;
  }

  .rp-orders-hero-art {
    height: 280px;
    margin-top: -10px;
  }

  .rp-order-stats {
    overflow-x: auto;
    padding-bottom: 5px;
  }

  .rp-order-stat {
    min-width: 145px;
  }

  .rp-orders-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .rp-order-search {
    width: 100%;
  }

  .rp-order-row {
    grid-template-columns: 65px minmax(0,1fr);
    gap: 12px;
    padding: 13px;
  }

  .rp-order-product-art {
    width: 65px;
    height: 68px;
  }

  .rp-order-middle {
    grid-column: 2;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .rp-order-actions {
    grid-column: 2;
  }

  .rp-order-actions a {
    width: 100%;
  }

  .rp-orders-sidebar {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .rp-orders-shell {
    width: calc(100% - 20px);
  }

  .rp-orders-hero h1 {
    font-size: 39px !important;
  }

  .rp-order-filters {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 5px;
  }

  .rp-order-filters button {
    flex: 0 0 auto;
  }

  .rp-order-row {
    grid-template-columns: 55px minmax(0,1fr);
  }

  .rp-order-product-art {
    width: 55px;
    height: 58px;
  }

  .rp-order-number {
    font-size: 10px;
  }

  .rp-order-middle {
    grid-column: 1 / -1;
  }

  .rp-order-actions {
    grid-column: 1 / -1;
  }

  .rp-orders-hero-art {
    transform: scale(.9);
    transform-origin: center;
  }
}


/* ============================================================
   GREENCORE — FUTURISTIC ORDER DETAILS
   /account/orders/:orderId
   ============================================================ */

.rp-order-details-page {
  position: relative;
  min-height: 100vh;
  padding: 86px 0 110px !important;
  overflow: hidden;
  color: #ecfff5;
  background:
    radial-gradient(
      900px 500px at 50% -120px,
      rgba(0, 255, 157, .075),
      transparent 65%
    ),
    radial-gradient(
      600px 500px at 100% 55%,
      rgba(0, 210, 145, .045),
      transparent 70%
    ),
    linear-gradient(
      180deg,
      #020b08 0%,
      #03130d 55%,
      #020a07 100%
    ) !important;
}

.rp-order-details-page::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .32;
  background-image:
    radial-gradient(
      circle,
      rgba(73, 255, 170, .18) 1px,
      transparent 1px
    );
  background-size: 24px 24px;
  mask-image: linear-gradient(
    to bottom,
    rgba(0,0,0,.65),
    transparent 80%
  );
}

.rp-order-details-page::after {
  content: "";
  position: absolute;
  width: 850px;
  height: 850px;
  top: 5%;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 50%;
  background: rgba(0,255,157,.025);
  filter: blur(120px);
  pointer-events: none;
}

.rp-detail-shell {
  position: relative;
  z-index: 2;
  width: min(1080px, calc(100% - 48px));
  margin: 0 auto;
}

/* ============================================================
   BACK BUTTON
   ============================================================ */

.rp-back-orders {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;
  color: #719889 !important;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none !important;
  transition: color .2s ease;
}

.rp-back-orders:hover {
  color: #6cf0ae !important;
}

/* ============================================================
   ORDER HEADER
   ============================================================ */

.rp-detail-header {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  min-height: 175px;
  padding: 29px 31px;
  margin-bottom: 14px;
  border: 1px solid rgba(82,255,175,.14);
  border-radius: 23px;
  background:
    radial-gradient(
      500px 190px at 0% 0%,
      rgba(0,255,157,.085),
      transparent 72%
    ),
    linear-gradient(
      135deg,
      rgba(7,39,28,.91),
      rgba(3,20,15,.80)
    );
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.035),
    0 25px 70px rgba(0,0,0,.22);
  backdrop-filter: blur(20px);
  overflow: hidden;
}

.rp-detail-header::after {
  content: "";
  position: absolute;
  width: 300px;
  height: 300px;
  right: -130px;
  top: -150px;
  border-radius: 50%;
  border: 1px solid rgba(65,255,169,.08);
  box-shadow:
    0 0 60px rgba(0,255,157,.025);
}

.rp-detail-header > div:first-child {
  position: relative;
  z-index: 2;
}

.rp-detail-header > div:first-child > span {
  display: block;
  margin-bottom: 10px;
  color: #4fe5a0;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .18em;
}

.rp-detail-header h1 {
  margin: 0;
  color: #f1fff7 !important;
  font-size: clamp(38px, 6vw, 58px) !important;
  line-height: .95 !important;
  letter-spacing: -.06em !important;
  font-weight: 790 !important;
  text-shadow: 0 0 30px rgba(100,255,180,.055);
}

.rp-detail-header p {
  margin: 11px 0 0 !important;
  color: #709789 !important;
  font-size: 11px !important;
}

.rp-detail-header-right {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.rp-detail-total {
  color: #effff7;
  font-size: 28px;
  font-weight: 780;
  letter-spacing: -.035em;
}

.rp-detail-status {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 0 12px;
  border: 1px solid rgba(245,190,55,.27);
  border-radius: 999px;
  background: rgba(245,190,55,.08);
  color: #f2c95b;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}

/* ============================================================
   GENERIC DETAIL PANEL
   ============================================================ */

.rp-detail-panel {
  position: relative;
  padding: 25px 27px;
  margin-bottom: 14px;
  border: 1px solid rgba(82,255,175,.105);
  border-radius: 21px;
  background:
    linear-gradient(
      145deg,
      rgba(6,31,22,.86),
      rgba(2,18,13,.76)
    );
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025),
    0 20px 55px rgba(0,0,0,.18);
  backdrop-filter: blur(19px);
}

.rp-panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 23px;
}

.rp-panel-heading > div > span {
  display: block;
  margin-bottom: 6px;
  color: #4cda98;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .17em;
}

.rp-panel-heading h2 {
  margin: 0 !important;
  color: #eafff3 !important;
  font-size: 18px !important;
  font-weight: 740 !important;
  letter-spacing: -.025em !important;
}

.rp-panel-heading > svg {
  color: #52e5a0;
  opacity: .8;
}

/* ============================================================
   TRACKING
   ============================================================ */

.rp-tracking {
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 4px;
  padding: 10px 0 5px;
}

.rp-tracking-line {
  position: absolute;
  top: 30px;
  left: 7%;
  right: 7%;
  height: 2px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(82,255,175,.08);
}

.rp-tracking-line span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    #16c982,
    #59efac
  );
  box-shadow:
    0 0 12px rgba(65,255,170,.35);
  transition: width .5s ease;
}

.rp-tracking-step {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  min-width: 0;
  text-align: center;
}

.rp-tracking-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(82,255,175,.10);
  border-radius: 50%;
  background: #061a13;
  color: #416556;
  box-shadow:
    0 0 0 6px #061a13;
  transition: .25s ease;
}

.rp-tracking-step span {
  color: #4d7060;
  font-size: 8px;
  font-weight: 750;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.rp-tracking-step.completed .rp-tracking-icon,
.rp-tracking-step.active .rp-tracking-icon {
  border-color: rgba(73,255,169,.36);
  background:
    radial-gradient(
      circle,
      rgba(0,255,157,.19),
      rgba(0,255,157,.045)
    );
  color: #68edaa;
  box-shadow:
    0 0 0 6px #061a13,
    0 0 25px rgba(0,255,157,.12);
}

.rp-tracking-step.completed span,
.rp-tracking-step.active span {
  color: #8aeeb8;
}

.rp-tracking-step.active .rp-tracking-icon {
  animation: rp-tracking-pulse 2s ease-in-out infinite;
}

@keyframes rp-tracking-pulse {
  0%, 100% {
    box-shadow:
      0 0 0 6px #061a13,
      0 0 20px rgba(0,255,157,.08);
  }

  50% {
    box-shadow:
      0 0 0 6px #061a13,
      0 0 34px rgba(0,255,157,.20);
  }
}

.rp-tracking-number {
  display: flex;
  align-items: center;
  gap: 12px;
  width: fit-content;
  margin-top: 25px;
  padding: 8px 12px;
  border: 1px solid rgba(82,255,175,.09);
  border-radius: 9px;
  background: rgba(0,255,157,.035);
}

.rp-tracking-number span {
  color: #507767;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .1em;
}

.rp-tracking-number strong {
  color: #9aefc0;
  font-size: 9px;
}

/* ============================================================
   ITEMS + SUMMARY GRID
   ============================================================ */

.rp-detail-grid {
  display: grid;
  grid-template-columns: 1.25fr .75fr;
  gap: 14px;
  align-items: start;
}

.rp-detail-grid .rp-detail-panel {
  height: 100%;
}

.rp-detail-items {
  display: grid;
  gap: 8px;
}

.rp-detail-item {
  display: grid;
  grid-template-columns: 43px minmax(0,1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 67px;
  padding: 11px 13px;
  border: 1px solid rgba(82,255,175,.065);
  border-radius: 14px;
  background: rgba(2,17,12,.57);
}

.rp-detail-item-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(82,255,175,.13);
  border-radius: 11px;
  background: rgba(0,255,157,.055);
  color: #55dda0;
}

.rp-detail-item > div:nth-child(2) {
  min-width: 0;
}

.rp-detail-item > div:nth-child(2) strong {
  display: block;
  color: #d9f9e7;
  font-size: 11px;
  font-weight: 700;
}

.rp-detail-item > div:nth-child(2) small {
  display: block;
  margin-top: 4px;
  color: #5e8171;
  font-size: 9px;
}

.rp-detail-item > strong:last-child {
  color: #8ef0ba;
  font-size: 12px;
  font-weight: 750;
  white-space: nowrap;
}

/* ============================================================
   SUMMARY
   ============================================================ */

.rp-summary {
  display: grid;
  gap: 5px;
}

.rp-summary > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 9px 0;
  color: #698c7d;
  font-size: 11px;
}

.rp-summary > div strong {
  color: #c9ead9;
  font-size: 11px;
  font-weight: 700;
}

.rp-summary > .total {
  margin-top: 8px;
  padding-top: 16px;
  border-top: 1px solid rgba(82,255,175,.09);
}

.rp-summary > .total span {
  color: #91b5a5;
  font-size: 12px;
  font-weight: 650;
}

.rp-summary > .total strong {
  color: #f0fff7;
  font-size: 20px;
  font-weight: 780;
}

/* ============================================================
   DELIVERY
   ============================================================ */

.rp-shipping-panel {
  margin-bottom: 14px;
}

.rp-address {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  min-height: 54px;
  padding: 15px 16px;
  border: 1px solid rgba(82,255,175,.07);
  border-radius: 13px;
  background: rgba(2,17,12,.52);
  color: #82a596;
  font-size: 11px;
  line-height: 1.7;
}

.rp-address svg {
  flex: 0 0 auto;
  margin-top: 2px;
  color: #56dfa0;
}

/* ============================================================
   CANCELLATION
   ============================================================ */

.rp-cancel-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 14px;
  padding: 16px 18px;
  border: 1px solid rgba(255,99,99,.12);
  border-radius: 15px;
  background:
    linear-gradient(
      100deg,
      rgba(127,29,29,.10),
      rgba(60,12,12,.04)
    );
}

.rp-cancel-panel > div:first-child {
  display: flex;
  align-items: center;
  gap: 12px;
}

.rp-cancel-panel > div:first-child > svg {
  color: #e78c8c;
}

.rp-cancel-panel strong {
  display: block;
  color: #d8b1b1;
  font-size: 11px;
}

.rp-cancel-panel p {
  margin: 4px 0 0;
  color: #876c6c;
  font-size: 9px;
}

.rp-cancel-panel button {
  flex: 0 0 auto;
  min-height: 38px;
  padding: 0 15px;
  border: 1px solid rgba(255,105,105,.25);
  border-radius: 10px;
  background: rgba(127,29,29,.13);
  color: #ed9c9c;
  font: inherit;
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
  transition: .2s ease;
}

.rp-cancel-panel button:hover {
  border-color: rgba(255,105,105,.43);
  background: rgba(127,29,29,.23);
}

.rp-cancel-panel button:disabled {
  opacity: .5;
  cursor: wait;
}

/* ============================================================
   BOTTOM ACTIONS
   ============================================================ */

.rp-detail-footer-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 19px;
}

.rp-detail-footer-actions button,
.rp-detail-footer-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid rgba(82,255,175,.11);
  border-radius: 11px;
  background: rgba(4,26,19,.65);
  color: #80a797;
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  transition: .2s ease;
}

.rp-detail-footer-actions button:hover,
.rp-detail-footer-actions a:hover {
  border-color: rgba(82,255,175,.25);
  color: #a9efc8;
  background: rgba(0,255,157,.055);
}

.rp-detail-footer-actions a {
  border-color: rgba(64,255,168,.25);
  background: rgba(0,255,157,.075);
  color: #91edba;
}

/* ============================================================
   LOADING / NOT FOUND
   ============================================================ */

.rp-detail-loading,
.rp-order-not-found {
  position: relative;
  z-index: 2;
  display: flex;
  min-height: 500px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 13px;
  color: #709487;
  font-size: 11px;
  text-align: center;
}

.rp-detail-loading > div,
.rp-order-not-found > svg {
  display: grid;
  place-items: center;
  width: 55px;
  height: 55px;
  border: 1px solid rgba(82,255,175,.19);
  border-radius: 50%;
  color: #55e6a1;
}

.rp-detail-loading > div {
  animation: rp-detail-loading 1.5s linear infinite;
}

@keyframes rp-detail-loading {
  to {
    transform: rotate(360deg);
  }
}

.rp-order-not-found h1 {
  margin: 3px 0 0;
  color: #eafff3;
  font-size: 27px;
}

.rp-order-not-found p {
  margin: 0;
  color: #668979;
}

.rp-order-not-found a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding: 10px 15px;
  border: 1px solid rgba(82,255,175,.18);
  border-radius: 10px;
  color: #83eab5;
  font-size: 10px;
  text-decoration: none;
}

/* ============================================================
   TABLET
   ============================================================ */

@media (max-width: 850px) {
  .rp-detail-grid {
    grid-template-columns: 1fr;
  }

  .rp-orders-shell {
    width: min(100% - 32px, 680px);
  }

  .rp-detail-shell {
    width: min(100% - 32px, 680px);
  }

  .rp-tracking {
    grid-template-columns: repeat(3, 1fr);
    row-gap: 28px;
  }

  .rp-tracking-line {
    display: none;
  }

  .rp-detail-header {
    align-items: flex-start;
  }
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 600px) {
  .rp-order-details-page {
    padding: 46px 0 80px !important;
  }

  .rp-detail-shell {
    width: calc(100% - 22px);
  }

  .rp-detail-header {
    flex-direction: column;
    padding: 22px 19px;
  }

  .rp-detail-header-right {
    width: 100%;
    align-items: flex-start;
  }

  .rp-detail-total {
    font-size: 24px;
  }

  .rp-detail-panel {
    padding: 20px 17px;
    border-radius: 18px;
  }

  .rp-tracking {
    grid-template-columns: repeat(2, 1fr);
    row-gap: 25px;
  }

  .rp-detail-item {
    grid-template-columns: 39px minmax(0,1fr);
  }

  .rp-detail-item > strong:last-child {
    grid-column: 2;
    justify-self: start;
  }

  .rp-cancel-panel {
    align-items: stretch;
    flex-direction: column;
  }

  .rp-cancel-panel button {
    width: 100%;
  }

  .rp-detail-footer-actions {
    flex-direction: column;
  }

  .rp-detail-footer-actions button,
  .rp-detail-footer-actions a {
    width: 100%;
  }
}

@media (max-width: 390px) {
  .rp-detail-header h1 {
    font-size: 34px !important;
  }

  .rp-tracking {
    grid-template-columns: 1fr 1fr;
  }

  .rp-tracking-step span {
    font-size: 7px;
  }
}


/* ============================================================
   CANCELLED ORDER — TERMINAL STATE
   ============================================================ */

.rp-cancelled-tracking {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: start;
  width: min(620px, 100%);
  margin: 4px auto 0;
  padding: 12px 35px 5px;
}

.rp-cancelled-track-line {
  position: absolute;
  top: 30px;
  left: 25%;
  right: 25%;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    rgba(73,255,169,.28),
    rgba(255,91,91,.30)
  );
}

.rp-cancelled-track-line span {
  display: block;
  width: 50%;
  height: 100%;
  background: #52e7a0;
  box-shadow: 0 0 12px rgba(82,231,160,.25);
}

.rp-cancelled-track-step {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.rp-cancelled-track-step .rp-tracking-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #061a13;
  box-shadow: 0 0 0 6px #061a13;
}

.rp-cancelled-track-step span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.rp-cancelled-track-step.completed .rp-tracking-icon {
  border: 1px solid rgba(73,255,169,.36);
  color: #68edaa;
}

.rp-cancelled-track-step.completed span {
  color: #81e8b2;
}

.rp-cancelled-track-step.cancelled .rp-tracking-icon {
  border: 1px solid rgba(255,91,91,.38);
  background: rgba(127,29,29,.12);
  color: #ff7d7d;
  box-shadow:
    0 0 0 6px #061a13,
    0 0 24px rgba(255,91,91,.08);
}

.rp-cancelled-track-step.cancelled span {
  color: #f08383;
}

.rp-cancelled-message {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 23px;
  padding: 12px 14px;
  border: 1px solid rgba(255,91,91,.12);
  border-radius: 12px;
  background: rgba(127,29,29,.055);
}

.rp-cancelled-message > svg {
  flex: 0 0 auto;
  color: #ef8585;
}

.rp-cancelled-message strong {
  display: block;
  color: #dba4a4;
  font-size: 10px;
}

.rp-cancelled-message span {
  display: block;
  margin-top: 3px;
  color: #806969;
  font-size: 9px;
}

.rp-cancelled-final-panel {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
  padding: 16px 18px;
  border: 1px solid rgba(255,91,91,.13);
  border-radius: 15px;
  background:
    linear-gradient(
      100deg,
      rgba(127,29,29,.09),
      rgba(50,12,12,.035)
    );
}

.rp-cancelled-final-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 39px;
  height: 39px;
  border: 1px solid rgba(255,91,91,.24);
  border-radius: 11px;
  background: rgba(127,29,29,.10);
  color: #ed8585;
}

.rp-cancelled-final-panel strong {
  display: block;
  color: #e1aaaa;
  font-size: 11px;
}

.rp-cancelled-final-panel p {
  margin: 4px 0 0;
  color: #856b6b;
  font-size: 9px;
  line-height: 1.5;
}

@media (max-width: 600px) {
  .rp-cancelled-tracking {
    padding-left: 10px;
    padding-right: 10px;
  }

  .rp-cancelled-track-line {
    left: 25%;
    right: 25%;
  }

  .rp-cancelled-message {
    align-items: flex-start;
  }

  .rp-cancelled-final-panel {
    align-items: flex-start;
  }
}


/* =========================================================
   GREENCORE ADMIN CONTROL CENTER
   ========================================================= */

.rp-admin-page {
  min-height: calc(100vh - 80px);
  padding: 128px 28px 90px;
  background:
    radial-gradient(circle at 15% 5%, rgba(52, 211, 153, 0.08), transparent 30%),
    radial-gradient(circle at 90% 25%, rgba(45, 212, 191, 0.055), transparent 28%),
    #03120e;
  color: #ecfdf5;
}

.rp-admin-shell {
  width: min(1400px, 100%);
  margin: 0 auto;
}

.rp-admin-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 34px;
}

.rp-admin-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #6ee7b7;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  margin-bottom: 12px;
}

.rp-admin-header h1 {
  margin: 0;
  font-size: clamp(34px, 5vw, 58px);
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.rp-admin-header p {
  margin: 14px 0 0;
  color: #8ca99f;
  font-size: 15px;
}

.rp-admin-refresh {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(110, 231, 183, 0.18);
  border-radius: 12px;
  padding: 11px 15px;
  background: rgba(7, 31, 25, 0.72);
  color: #c8fbea;
  cursor: pointer;
}

.rp-admin-refresh:hover {
  border-color: rgba(110, 231, 183, 0.4);
  background: rgba(10, 43, 34, 0.85);
}

.rp-admin-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
}

.rp-admin-stat-card,
.rp-admin-flow-card,
.rp-admin-command-panel,
.rp-admin-loading-panel,
.rp-admin-error-panel {
  border: 1px solid rgba(110, 231, 183, 0.12);
  background: linear-gradient(
    145deg,
    rgba(9, 37, 30, 0.82),
    rgba(3, 20, 16, 0.72)
  );
  box-shadow: 0 22px 60px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(18px);
}

.rp-admin-stat-card {
  min-height: 145px;
  padding: 21px;
  border-radius: 18px;
  position: relative;
  overflow: hidden;
}

.rp-admin-stat-card::after {
  content: "";
  position: absolute;
  width: 100px;
  height: 100px;
  right: -45px;
  bottom: -45px;
  border-radius: 50%;
  background: rgba(52, 211, 153, 0.07);
}

.rp-admin-stat-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: #6ee7b7;
  background: rgba(52, 211, 153, 0.08);
  border: 1px solid rgba(110, 231, 183, 0.12);
}

.rp-admin-stat-copy {
  display: flex;
  flex-direction: column;
  margin-top: 17px;
}

.rp-admin-stat-copy span {
  color: #78958c;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.rp-admin-stat-copy strong {
  margin-top: 5px;
  font-size: 28px;
  letter-spacing: -0.035em;
}

.rp-admin-stat-copy small {
  margin-top: 4px;
  color: #607b73;
}

.rp-admin-stat-arrow {
  position: absolute;
  right: 19px;
  top: 22px;
  color: #496c61;
}

.rp-admin-section {
  margin-top: 38px;
}

.rp-admin-section-heading {
  margin-bottom: 17px;
}

.rp-admin-section-heading span,
.rp-admin-command-panel span {
  color: #5fae91;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.rp-admin-section-heading h2 {
  margin: 6px 0 0;
  font-size: 24px;
  letter-spacing: -0.025em;
}

.rp-admin-flow-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
}

.rp-admin-flow-card {
  min-height: 126px;
  padding: 18px;
  border-radius: 15px;
}

.rp-admin-flow-card svg {
  color: #61dba9;
}

.rp-admin-flow-card span {
  display: block;
  margin-top: 15px;
  color: #78958c;
  font-size: 12px;
}

.rp-admin-flow-card strong {
  display: block;
  margin-top: 4px;
  font-size: 27px;
}

.rp-admin-command-panel {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 22px;
  border-radius: 18px;
}

.rp-admin-command-icon {
  flex: 0 0 auto;
  width: 50px;
  height: 50px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  color: #6ee7b7;
  background: rgba(52, 211, 153, 0.08);
  border: 1px solid rgba(110, 231, 183, 0.12);
}

.rp-admin-command-panel h3 {
  margin: 5px 0 5px;
  font-size: 19px;
}

.rp-admin-command-panel p {
  margin: 0;
  color: #78958c;
  line-height: 1.6;
}

.rp-admin-loading,
.rp-admin-loading-panel,
.rp-admin-error-panel {
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.rp-admin-loading {
  min-height: 100vh;
  background: #03120e;
  color: #a7c8bc;
}

.rp-admin-loading-orb {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(110, 231, 183, 0.2);
  border-top-color: #6ee7b7;
  border-radius: 50%;
  animation: rp-admin-spin 0.8s linear infinite;
}

.rp-admin-loading-panel,
.rp-admin-error-panel {
  border-radius: 18px;
  color: #9ab7ae;
}

.rp-admin-error-panel {
  justify-content: flex-start;
  padding: 24px;
  color: #fda4af;
}

.rp-admin-error-panel div {
  flex: 1;
}

.rp-admin-error-panel strong {
  color: #fecdd3;
}

.rp-admin-error-panel p {
  margin: 5px 0 0;
  color: #a98288;
}

.rp-admin-error-panel button {
  border: 1px solid rgba(253, 164, 175, 0.2);
  background: rgba(127, 29, 29, 0.2);
  color: #fecdd3;
  border-radius: 10px;
  padding: 9px 14px;
  cursor: pointer;
}

.rp-admin-spin {
  animation: rp-admin-spin 0.8s linear infinite;
}

@keyframes rp-admin-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 1050px) {
  .rp-admin-stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rp-admin-flow-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .rp-admin-page {
    padding: 105px 16px 60px;
  }

  .rp-admin-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .rp-admin-stats-grid,
  .rp-admin-flow-grid {
    grid-template-columns: 1fr;
  }

  .rp-admin-command-panel {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* =========================================================
   ADMIN PRODUCTS
   ========================================================= */

.rp-admin-primary-btn,
.rp-admin-secondary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 15px;
  border-radius: 11px;
  font: inherit;
  font-size: 13px;
  font-weight: 750;
  cursor: pointer;
  transition: 0.2s ease;
}

.rp-admin-primary-btn {
  border: 1px solid rgba(110, 231, 183, 0.3);
  background: linear-gradient(135deg, rgba(52, 211, 153, 0.18), rgba(16, 185, 129, 0.08));
  color: #c8fbea;
}

.rp-admin-primary-btn:hover {
  border-color: rgba(110, 231, 183, 0.55);
  transform: translateY(-1px);
}

.rp-admin-primary-btn:disabled {
  opacity: 0.55;
  cursor: wait;
  transform: none;
}

.rp-admin-secondary-btn {
  border: 1px solid rgba(110, 231, 183, 0.13);
  background: rgba(8, 30, 25, 0.7);
  color: #94b2a8;
}

.rp-admin-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 17px;
}

.rp-admin-search {
  flex: 1;
  max-width: 520px;
  min-height: 46px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  border: 1px solid rgba(110, 231, 183, 0.11);
  border-radius: 12px;
  background: rgba(5, 28, 22, 0.72);
  color: #64877b;
}

.rp-admin-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #d7f7eb;
  font: inherit;
}

.rp-admin-search input::placeholder {
  color: #4e6c63;
}

.rp-admin-filter {
  display: flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid rgba(110, 231, 183, 0.1);
  border-radius: 11px;
  background: rgba(5, 28, 22, 0.65);
}

.rp-admin-filter button {
  border: 0;
  border-radius: 8px;
  padding: 8px 12px;
  background: transparent;
  color: #67877d;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
}

.rp-admin-filter button.active {
  background: rgba(52, 211, 153, 0.11);
  color: #bdf5df;
}

.rp-admin-product-panel {
  overflow: hidden;
  border: 1px solid rgba(110, 231, 183, 0.12);
  border-radius: 18px;
  background: rgba(4, 23, 19, 0.75);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.17);
}

.rp-admin-table-heading {
  display: flex;
  align-items: center;
  padding: 20px 22px;
  border-bottom: 1px solid rgba(110, 231, 183, 0.08);
}

.rp-admin-table-heading div {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rp-admin-table-heading span {
  color: #55947c;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.17em;
}

.rp-admin-table-heading strong {
  font-size: 17px;
}

.rp-admin-product-row {
  display: grid;
  grid-template-columns: 46px minmax(220px, 1.8fr) minmax(100px, 0.7fr) minmax(130px, 0.9fr) 120px 92px 130px;
  align-items: center;
  gap: 15px;
  min-height: 82px;
  padding: 12px 20px;
  border-bottom: 1px solid rgba(110, 231, 183, 0.06);
}

.rp-admin-product-row:last-child {
  border-bottom: 0;
}

.rp-admin-product-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(110, 231, 183, 0.1);
  border-radius: 11px;
  background: rgba(52, 211, 153, 0.06);
  color: #5ed9a5;
}

.rp-admin-product-main,
.rp-admin-product-meta {
  min-width: 0;
}

.rp-admin-product-main {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rp-admin-product-main strong {
  color: #dcf9ed;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rp-admin-product-main span {
  color: #607f75;
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rp-admin-product-meta {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rp-admin-product-meta span {
  color: #4f7166;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.rp-admin-product-meta strong {
  color: #8eaea3;
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rp-admin-product-price {
  color: #bff6df;
  font-weight: 800;
}

.rp-admin-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 750;
}

.rp-admin-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.rp-admin-status.active {
  color: #62dca9;
}

.rp-admin-status.inactive {
  color: #81958f;
}

.rp-admin-product-actions {
  display: flex;
  justify-content: flex-end;
  gap: 5px;
}

.rp-admin-product-actions button,
.rp-admin-modal-header > button,
.rp-admin-alert button {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(110, 231, 183, 0.1);
  border-radius: 9px;
  background: rgba(7, 29, 24, 0.72);
  color: #76978c;
  cursor: pointer;
}

.rp-admin-product-actions button:hover,
.rp-admin-modal-header > button:hover {
  color: #c6f5e2;
  border-color: rgba(110, 231, 183, 0.28);
}

.rp-admin-empty {
  min-height: 250px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #54736a;
}

.rp-admin-empty strong {
  color: #91b0a5;
}

.rp-admin-empty span {
  font-size: 12px;
}

.rp-admin-alert {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 15px;
  padding: 12px 14px;
  border: 1px solid rgba(110, 231, 183, 0.14);
  border-radius: 11px;
  background: rgba(8, 42, 32, 0.65);
  color: #9be8c7;
  font-size: 13px;
}

.rp-admin-alert.error {
  border-color: rgba(251, 113, 133, 0.18);
  background: rgba(75, 20, 31, 0.3);
  color: #fda4af;
}

.rp-admin-alert span {
  flex: 1;
}

.rp-admin-alert button {
  width: 28px;
  height: 28px;
  border: 0;
  background: transparent;
}

.rp-admin-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(0, 8, 6, 0.76);
  backdrop-filter: blur(12px);
}

.rp-admin-modal {
  width: min(650px, 100%);
  max-height: min(850px, calc(100vh - 40px));
  overflow-y: auto;
  border: 1px solid rgba(110, 231, 183, 0.16);
  border-radius: 20px;
  background: linear-gradient(145deg, #08271f, #031711);
  box-shadow: 0 35px 100px rgba(0, 0, 0, 0.55);
}

.rp-admin-modal-header {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 23px;
  border-bottom: 1px solid rgba(110, 231, 183, 0.08);
}

.rp-admin-modal-header > div {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.rp-admin-modal-header span {
  color: #55a789;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.17em;
}

.rp-admin-modal-header h2 {
  margin: 0;
  font-size: 24px;
}

.rp-admin-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 22px;
}

.rp-admin-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: #7f9f94;
  font-size: 11px;
  font-weight: 700;
}

.rp-admin-form input,
.rp-admin-form textarea,
.rp-admin-form select,
.rp-admin-image-form input {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid rgba(110, 231, 183, 0.12);
  border-radius: 10px;
  outline: 0;
  background: rgba(2, 17, 13, 0.75);
  color: #d9f9ed;
  padding: 11px 12px;
  font: inherit;
  font-size: 13px;
}

.rp-admin-form textarea {
  resize: vertical;
}

.rp-admin-form input:focus,
.rp-admin-form textarea:focus,
.rp-admin-form select:focus,
.rp-admin-image-form input:focus {
  border-color: rgba(110, 231, 183, 0.4);
}

.rp-admin-form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.rp-admin-select-wrap {
  position: relative;
}

.rp-admin-select-wrap select {
  appearance: none;
  padding-right: 35px;
}

.rp-admin-select-wrap svg {
  position: absolute;
  right: 12px;
  top: 50%;
  pointer-events: none;
  transform: translateY(-50%);
  color: #5c7d72;
}

.rp-admin-checkbox {
  flex-direction: row !important;
  align-items: center;
  cursor: pointer;
}

.rp-admin-checkbox input {
  width: 16px;
  height: 16px;
  accent-color: #55d69f;
}

.rp-admin-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 4px;
}

.rp-admin-image-modal {
  width: min(760px, 100%);
}

.rp-admin-image-form {
  display: grid;
  grid-template-columns: 1.7fr 1fr auto;
  gap: 9px;
  padding: 20px 22px;
  border-bottom: 1px solid rgba(110, 231, 183, 0.08);
}

.rp-admin-image-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  padding: 22px;
}

.rp-admin-image-card {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1;
  border: 1px solid rgba(110, 231, 183, 0.12);
  border-radius: 13px;
  background: #041a14;
}

.rp-admin-image-card img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.rp-admin-image-card > span {
  position: absolute;
  left: 8px;
  top: 8px;
  padding: 5px 7px;
  border-radius: 6px;
  background: rgba(3, 24, 18, 0.88);
  color: #7ce4b6;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

@media (max-width: 1050px) {
  .rp-admin-product-row {
    grid-template-columns: 42px minmax(180px, 1.6fr) 100px 100px 110px;
  }

  .rp-admin-product-meta:nth-of-type(2),
  .rp-admin-product-price {
    display: none;
  }
}

@media (max-width: 720px) {
  .rp-admin-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .rp-admin-search {
    max-width: none;
  }

  .rp-admin-filter {
    width: fit-content;
  }

  .rp-admin-product-row {
    grid-template-columns: 42px 1fr auto;
    gap: 10px;
  }

  .rp-admin-product-meta,
  .rp-admin-product-price,
  .rp-admin-status {
    display: none;
  }

  .rp-admin-product-actions {
    grid-column: 3;
    grid-row: 1;
  }

  .rp-admin-form-grid,
  .rp-admin-image-form {
    grid-template-columns: 1fr;
  }

  .rp-admin-image-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rp-admin-modal-backdrop {
    padding: 10px;
  }
}

/* =========================================================
   ADMIN APPLICATION SHELL
   ========================================================= */

.rp-admin-shell {
  --admin-bg: #031c16;
  --admin-panel: rgba(7, 39, 31, 0.86);
  --admin-panel-soft: rgba(8, 49, 39, 0.62);
  --admin-border: rgba(76, 196, 148, 0.16);
  --admin-border-strong: rgba(76, 196, 148, 0.28);
  --admin-text: #effff8;
  --admin-muted: #76988c;
  --admin-accent: #4ee7a6;
  --admin-accent-soft: rgba(78, 231, 166, 0.12);

  min-height: 100vh;
  display: flex;
  background:
    radial-gradient(circle at 75% 5%, rgba(32, 131, 91, 0.13), transparent 28rem),
    radial-gradient(circle at 20% 80%, rgba(16, 107, 73, 0.08), transparent 30rem),
    var(--admin-bg);
  color: var(--admin-text);
}

.rp-admin-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 100;
  width: 258px;
  display: flex;
  flex-direction: column;
  padding: 22px 14px 14px;
  background:
    linear-gradient(180deg, rgba(4, 31, 25, 0.98), rgba(2, 22, 18, 0.99));
  border-right: 1px solid var(--admin-border);
  box-shadow: 16px 0 50px rgba(0, 0, 0, 0.18);
  transition: width 220ms ease, transform 220ms ease;
}

.rp-admin-shell.is-collapsed .rp-admin-sidebar {
  width: 78px;
}

.rp-admin-brand {
  min-height: 52px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 8px 20px;
}

.rp-admin-brand-mark {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: #031c16;
  background: linear-gradient(145deg, #71f4b5, #25bb7b);
  box-shadow: 0 10px 30px rgba(46, 220, 143, 0.18);
  font-size: 24px;
  font-weight: 900;
}

.rp-admin-brand-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  line-height: 1;
}

.rp-admin-brand-copy strong {
  font-size: 16px;
  letter-spacing: -0.03em;
}

.rp-admin-brand-copy span {
  margin-top: 6px;
  color: var(--admin-accent);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.rp-admin-nav-label {
  padding: 18px 12px 8px;
  color: #4e7166;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.15em;
}

.rp-admin-nav {
  display: grid;
  gap: 4px;
}

.rp-admin-nav-item {
  min-height: 45px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 11px;
  color: #83a79a;
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
  transition: 160ms ease;
}

.rp-admin-nav-item:hover {
  color: #e8fff5;
  background: rgba(78, 231, 166, 0.055);
  border-color: rgba(78, 231, 166, 0.08);
}

.rp-admin-nav-item.active {
  color: #ecfff7;
  background:
    linear-gradient(90deg, rgba(54, 205, 137, 0.15), rgba(54, 205, 137, 0.035));
  border-color: rgba(78, 231, 166, 0.19);
  box-shadow: inset 3px 0 0 #4ee7a6;
}

.rp-admin-nav-item.active svg:first-child {
  color: var(--admin-accent);
}

.rp-admin-nav-item .nav-arrow {
  margin-left: auto;
  opacity: 0;
  transform: translateX(-4px);
  transition: 160ms ease;
}

.rp-admin-nav-item:hover .nav-arrow,
.rp-admin-nav-item.active .nav-arrow {
  opacity: 0.7;
  transform: translateX(0);
}

.rp-admin-shell.is-collapsed .rp-admin-nav-item {
  justify-content: center;
  padding: 0;
}

.rp-admin-shell.is-collapsed .rp-admin-nav-item .nav-arrow {
  display: none;
}

.rp-admin-sidebar-spacer {
  flex: 1;
}

.rp-admin-user-card {
  min-height: 58px;
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 12px 0 10px;
  padding: 9px;
  border: 1px solid var(--admin-border);
  border-radius: 13px;
  background: rgba(7, 43, 34, 0.66);
}

.rp-admin-avatar,
.rp-admin-top-avatar {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #05251c;
  background: linear-gradient(145deg, #8bffc7, #3bd892);
  font-size: 11px;
  font-weight: 900;
}

.rp-admin-user-info {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.rp-admin-user-info strong {
  overflow: hidden;
  color: #eafff5;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-admin-user-info span {
  margin-top: 3px;
  color: #609182;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.rp-admin-logout {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 8px;
  color: #73998b;
  background: transparent;
  cursor: pointer;
}

.rp-admin-logout:hover {
  color: #ff8e8e;
  background: rgba(255, 100, 100, 0.08);
}

.rp-admin-collapse {
  min-height: 39px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 11px;
  border: 1px solid var(--admin-border);
  border-radius: 10px;
  color: #648b7d;
  background: transparent;
  cursor: pointer;
  font-size: 10px;
  font-weight: 700;
}

.rp-admin-collapse:hover {
  color: #d8fff0;
  border-color: var(--admin-border-strong);
  background: rgba(78, 231, 166, 0.045);
}

.rp-admin-shell.is-collapsed .rp-admin-collapse {
  justify-content: center;
  padding: 0;
}

.rp-admin-main {
  width: calc(100% - 258px);
  min-width: 0;
  margin-left: 258px;
  transition: width 220ms ease, margin-left 220ms ease;
}

.rp-admin-shell.is-collapsed .rp-admin-main {
  width: calc(100% - 78px);
  margin-left: 78px;
}

.rp-admin-topbar {
  height: 72px;
  position: sticky;
  top: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 30px;
  border-bottom: 1px solid var(--admin-border);
  background: rgba(3, 25, 20, 0.82);
  backdrop-filter: blur(18px);
}

.rp-admin-breadcrumb {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #547a6d;
  font-size: 11px;
}

.rp-admin-breadcrumb strong {
  color: #b8d9cd;
  font-weight: 700;
}

.rp-admin-topbar-right {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
}

.rp-admin-live {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #70a193;
  font-size: 10px;
  font-weight: 700;
}

.rp-admin-live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4ee7a6;
  box-shadow: 0 0 0 4px rgba(78, 231, 166, 0.08), 0 0 15px rgba(78, 231, 166, 0.45);
}

.rp-admin-top-avatar {
  width: 34px;
  height: 34px;
  flex-basis: 34px;
  font-size: 10px;
}

.rp-admin-content {
  width: min(1440px, 100%);
  min-height: calc(100vh - 72px);
  margin: 0 auto;
  padding: 38px 42px 70px;
}

.rp-admin-mobile-menu,
.rp-admin-mobile-close,
.rp-admin-mobile-backdrop {
  display: none;
}

@media (max-width: 1000px) {
  .rp-admin-sidebar {
    transform: translateX(-100%);
    width: 258px;
  }

  .rp-admin-sidebar.is-mobile-open {
    transform: translateX(0);
  }

  .rp-admin-mobile-backdrop.is-visible {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 90;
    background: rgba(0, 0, 0, 0.55);
    backdrop-filter: blur(4px);
  }

  .rp-admin-main,
  .rp-admin-shell.is-collapsed .rp-admin-main {
    width: 100%;
    margin-left: 0;
  }

  .rp-admin-mobile-menu,
  .rp-admin-mobile-close {
    display: grid;
    place-items: center;
    border: 0;
    border-radius: 9px;
    color: #9bc2b4;
    background: rgba(78, 231, 166, 0.06);
    cursor: pointer;
  }

  .rp-admin-mobile-menu {
    width: 38px;
    height: 38px;
  }

  .rp-admin-mobile-close {
    width: 34px;
    height: 34px;
    margin-left: auto;
  }

  .rp-admin-content {
    padding: 30px 24px 60px;
  }

  .rp-admin-topbar {
    padding: 0 20px;
  }
}

@media (max-width: 640px) {
  .rp-admin-live {
    display: none;
  }

  .rp-admin-breadcrumb span,
  .rp-admin-breadcrumb svg {
    display: none;
  }

  .rp-admin-content {
    padding: 22px 15px 45px;
  }
}


/* =========================================================
   ADMIN PAGE LAYOUT RESET
   Keep admin screens as application/data pages.
   These rules intentionally override older marketing/hero
   compositions that may share generic class names.
   ========================================================= */

.rp-admin-content {
  box-sizing: border-box;
  overflow-x: hidden;
}

.rp-admin-content > * {
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
}

.rp-admin-content h1,
.rp-admin-content h2,
.rp-admin-content h3,
.rp-admin-content p {
  max-width: none;
}

.rp-admin-dashboard,
.rp-admin-products-page,
.rp-admin-orders-page {
  position: relative !important;
  width: 100% !important;
  max-width: none !important;
  min-height: 0 !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: none !important;
  overflow: visible !important;
}

.rp-admin-dashboard::before,
.rp-admin-dashboard::after,
.rp-admin-products-page::before,
.rp-admin-products-page::after {
  pointer-events: none;
}

.rp-admin-page-heading {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  width: 100%;
  margin: 0 0 28px;
  padding: 0;
}

.rp-admin-eyebrow {
  margin-bottom: 9px;
  color: #50e7a7;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .16em;
}

.rp-admin-page-heading h1 {
  margin: 0;
  color: #f0fff8;
  font-size: clamp(38px, 4vw, 58px);
  line-height: .98;
  letter-spacing: -.055em;
}

.rp-admin-page-heading p {
  max-width: 560px;
  margin: 12px 0 0;
  color: #72998b;
  font-size: 13px;
  line-height: 1.55;
}

.rp-admin-action-button {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex: 0 0 auto;
  padding: 0 14px;
  border: 1px solid rgba(78, 231, 166, .2);
  border-radius: 10px;
  color: #dffff1;
  background: rgba(78, 231, 166, .07);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
}

.rp-admin-action-button:hover {
  border-color: rgba(78, 231, 166, .35);
  background: rgba(78, 231, 166, .12);
}

.rp-admin-action-button:disabled {
  opacity: .6;
  cursor: wait;
}

.rp-spin {
  animation: rp-admin-spin .8s linear infinite;
}

@keyframes rp-admin-spin {
  to {
    transform: rotate(360deg);
  }
}

/* Dashboard cards should sit in a normal grid. */
.rp-admin-dashboard .rp-admin-metrics,
.rp-admin-dashboard .rp-admin-stat-grid,
.rp-admin-dashboard .rp-admin-dashboard-grid {
  position: relative !important;
  width: 100% !important;
  max-width: none !important;
  height: auto !important;
  min-height: 0 !important;
  transform: none !important;
}

/* Products page: normal catalog workspace. */
.rp-admin-products-page {
  display: block !important;
}

.rp-admin-products-page > *,
.rp-admin-products-page .rp-admin-products-grid,
.rp-admin-products-page .rp-admin-product-list,
.rp-admin-products-page .rp-admin-products-card {
  box-sizing: border-box;
  max-width: 100%;
}

/* =========================================================
   ADMIN ORDERS
   ========================================================= */

.rp-admin-orders-page {
  display: block;
}

.rp-admin-order-stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.rp-admin-order-stat {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border: 1px solid rgba(78, 231, 166, .13);
  border-radius: 14px;
  color: #dffaf0;
  background: linear-gradient(
    145deg,
    rgba(8, 47, 37, .82),
    rgba(4, 31, 25, .72)
  );
  text-align: left;
  cursor: pointer;
}

.rp-admin-order-stat:hover,
.rp-admin-order-stat.active {
  border-color: rgba(78, 231, 166, .34);
  background: linear-gradient(
    145deg,
    rgba(12, 64, 49, .9),
    rgba(5, 36, 28, .82)
  );
}

.rp-admin-stat-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(78, 231, 166, .14);
  border-radius: 10px;
  color: #54e9aa;
  background: rgba(78, 231, 166, .07);
}

.rp-admin-order-stat span:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.rp-admin-order-stat small {
  color: #628d7e;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .07em;
}

.rp-admin-order-stat strong {
  margin-top: 4px;
  color: #edfff7;
  font-size: 22px;
  line-height: 1;
}

.rp-admin-orders-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.rp-admin-search {
  min-height: 43px;
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 13px;
  border: 1px solid rgba(78, 231, 166, .13);
  border-radius: 11px;
  background: rgba(5, 35, 28, .72);
}

.rp-admin-search svg {
  flex: 0 0 auto;
  color: #557e70;
}

.rp-admin-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  color: #dffaf0;
  background: transparent;
  font: inherit;
  font-size: 12px;
}

.rp-admin-search input::placeholder {
  color: #54796d;
}

.rp-admin-status-filter,
.rp-admin-status-select {
  position: relative;
}

.rp-admin-status-filter select,
.rp-admin-status-select select {
  appearance: none;
  border: 1px solid rgba(78, 231, 166, .13);
  outline: 0;
  color: #bfe8da;
  background: #062c23;
  cursor: pointer;
}

.rp-admin-status-filter select {
  min-height: 43px;
  min-width: 150px;
  padding: 0 34px 0 13px;
  border-radius: 11px;
  font-size: 11px;
  font-weight: 700;
}

.rp-admin-status-filter svg,
.rp-admin-status-select svg {
  position: absolute;
  pointer-events: none;
  color: #638e80;
}

.rp-admin-status-filter svg {
  top: 14px;
  right: 11px;
}

.rp-admin-error {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(255, 113, 113, .18);
  border-radius: 10px;
  color: #ffb4b4;
  background: rgba(105, 28, 28, .18);
  font-size: 11px;
}

.rp-admin-orders-card {
  overflow: hidden;
  border: 1px solid rgba(78, 231, 166, .13);
  border-radius: 15px;
  background: rgba(4, 29, 23, .78);
  box-shadow: 0 22px 60px rgba(0, 0, 0, .12);
}

.rp-admin-table-header,
.rp-admin-order-row {
  display: grid;
  grid-template-columns: 1.25fr 1.4fr .55fr .8fr .9fr 1.55fr;
  gap: 14px;
  align-items: center;
  padding: 0 18px;
}

.rp-admin-table-header {
  min-height: 43px;
  border-bottom: 1px solid rgba(78, 231, 166, .1);
  color: #50786a;
  background: rgba(78, 231, 166, .025);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .12em;
}

.rp-admin-order-row {
  min-height: 74px;
  border-bottom: 1px solid rgba(78, 231, 166, .07);
  color: #8eb4a5;
  font-size: 11px;
}

.rp-admin-order-row:last-child {
  border-bottom: 0;
}

.rp-admin-order-row:hover {
  background: rgba(78, 231, 166, .025);
}

.rp-admin-order-row > div {
  min-width: 0;
}

.rp-admin-order-row strong {
  color: #e4fff4;
  font-size: 11px;
}

.rp-admin-order-row small {
  display: block;
  overflow: hidden;
  margin-top: 4px;
  color: #4f786a;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-admin-customer-cell {
  display: flex;
  align-items: center;
  gap: 9px;
}

.rp-admin-customer-cell strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-admin-customer-avatar {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(78, 231, 166, .17);
  border-radius: 50%;
  color: #65efb1;
  background: rgba(78, 231, 166, .07);
  font-size: 10px;
  font-weight: 900;
}

.rp-admin-order-status-cell {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.rp-admin-status {
  min-height: 25px;
  display: inline-flex;
  align-items: center;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 800;
  white-space: nowrap;
}

.rp-admin-status.pending {
  color: #e7c987;
  border-color: rgba(231, 201, 135, .16);
  background: rgba(231, 201, 135, .07);
}

.rp-admin-status.confirmed,
.rp-admin-status.processing {
  color: #7ed9ff;
  border-color: rgba(126, 217, 255, .15);
  background: rgba(126, 217, 255, .06);
}

.rp-admin-status.shipped {
  color: #a9a1ff;
  border-color: rgba(169, 161, 255, .16);
  background: rgba(169, 161, 255, .07);
}

.rp-admin-status.delivered {
  color: #67efad;
  border-color: rgba(103, 239, 173, .16);
  background: rgba(103, 239, 173, .07);
}

.rp-admin-status.cancelled {
  color: #ff9999;
  border-color: rgba(255, 153, 153, .15);
  background: rgba(255, 153, 153, .06);
}

.rp-admin-status-select select {
  width: 31px;
  height: 29px;
  padding: 0;
  border-radius: 8px;
  color: transparent;
  background: rgba(78, 231, 166, .045);
}

.rp-admin-status-select svg {
  top: 8px;
  right: 8px;
}

.rp-admin-status-select select:disabled {
  opacity: .45;
  cursor: wait;
}

.rp-admin-table-empty {
  min-height: 260px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  color: #587f71;
}

.rp-admin-table-empty strong {
  color: #b8dace;
  font-size: 13px;
}

.rp-admin-table-empty span {
  font-size: 10px;
}

@media (max-width: 1100px) {
  .rp-admin-order-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .rp-admin-table-header,
  .rp-admin-order-row {
    grid-template-columns: 1.2fr 1.35fr .55fr .8fr 1.55fr;
  }

  .rp-admin-table-header > div:nth-child(5),
  .rp-admin-order-row > div:nth-child(5) {
    display: none;
  }
}

@media (max-width: 760px) {
  .rp-admin-page-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .rp-admin-order-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rp-admin-orders-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .rp-admin-status-filter select {
    width: 100%;
  }

  .rp-admin-table-header {
    display: none;
  }

  .rp-admin-order-row {
    grid-template-columns: 1fr 1fr;
    gap: 13px;
    padding: 16px;
  }

  .rp-admin-order-row > div:nth-child(3),
  .rp-admin-order-row > div:nth-child(4),
  .rp-admin-order-row > div:nth-child(5) {
    display: none;
  }

  .rp-admin-order-status-cell {
    justify-content: flex-end;
  }
}

@media (max-width: 480px) {
  .rp-admin-order-stats {
    grid-template-columns: 1fr;
  }

  .rp-admin-order-row {
    grid-template-columns: 1fr;
  }

  .rp-admin-order-status-cell {
    justify-content: flex-start;
  }
}


/* =========================================================
   GREENCORE FUTURISTIC ADMIN PAGES
   ========================================================= */

.rp-admin-modern-page {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
}

.rp-admin-page-loading {
  min-height: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: #70998b;
  font-size: 12px;
}

.rp-admin-modern-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 28px;
}

.rp-admin-modern-eyebrow {
  display: block;
  margin-bottom: 9px;
  color: #4ee7a6;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .17em;
}

.rp-admin-modern-heading h1 {
  margin: 0;
  color: #effff7;
  font-size: clamp(43px, 5vw, 64px);
  line-height: .94;
  letter-spacing: -.065em;
}

.rp-admin-modern-heading h1 span {
  color: #dffff1;
}

.rp-admin-modern-heading p {
  margin: 12px 0 0;
  color: #75998c;
  font-size: 12px;
  line-height: 1.55;
}

.rp-admin-modern-refresh,
.rp-admin-modern-primary {
  min-height: 41px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 11px;
  font-weight: 800;
}

.rp-admin-modern-refresh {
  padding: 0 14px;
  border: 1px solid rgba(78,231,166,.2);
  color: #bdebdc;
  background: rgba(78,231,166,.055);
}

.rp-admin-modern-refresh:hover {
  border-color: rgba(78,231,166,.38);
  background: rgba(78,231,166,.1);
}

.rp-admin-modern-primary {
  padding: 0 17px;
  border: 1px solid rgba(91,241,173,.32);
  color: #05271d;
  background: linear-gradient(145deg,#62f2ae,#1fbd7a);
  box-shadow: 0 10px 28px rgba(27,201,126,.13);
}

.rp-admin-modern-primary:hover {
  transform: translateY(-1px);
  filter: brightness(1.06);
}

.rp-admin-modern-error {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 16px;
  padding: 12px 14px;
  border: 1px solid rgba(255,111,111,.2);
  border-radius: 10px;
  color: #ffb2b2;
  background: rgba(112,27,27,.18);
  font-size: 11px;
}

.rp-admin-modern-metrics {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.rp-admin-modern-metric {
  position: relative;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 13px;
  min-height: 105px;
  padding: 16px;
