/* =========================================================
   ADMIN SHELL — FULL VIEWPORT ALIGNMENT FIX
   ========================================================= */

/*
 * The customer application has its own centered/max-width layout.
 * Admin must NOT inherit those constraints.
 */

html,
body,
#root {
  width: 100%;
  min-width: 100%;
  min-height: 100%;
  margin: 0;
}

body {
  overflow-x: hidden;
}

/* Admin root shell */
.rp-admin-shell {
  position: relative;
  width: 100vw;
  min-width: 100vw;
  min-height: 100vh;
  margin: 0;
  padding: 0;
  overflow-x: hidden;
  background:
    radial-gradient(
      circle at 72% 10%,
      rgba(20, 105, 73, .10),
      transparent 28%
    ),
    linear-gradient(
      135deg,
      #021a14 0%,
      #031f18 48%,
      #021912 100%
    );
}

/* Fixed admin sidebar */
.rp-admin-sidebar {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  bottom: 0 !important;
  width: 230px !important;
  max-width: 230px !important;
  min-width: 230px !important;
  height: 100vh !important;
  z-index: 100 !important;
  box-sizing: border-box;
  overflow-y: auto;
  overflow-x: hidden;
}

/* Admin workspace beside sidebar */
.rp-admin-main {
  position: relative !important;
  width: calc(100vw - 230px) !important;
  min-width: 0 !important;
  max-width: none !important;
  min-height: 100vh;
  margin-left: 230px !important;
  padding: 0 !important;
  box-sizing: border-box;
  background: transparent !important;
}

/* Admin top bar */
.rp-admin-topbar {
  position: sticky !important;
  top: 0 !important;
  z-index: 90 !important;
  width: 100% !important;
  max-width: none !important;
  margin: 0 !important;
  box-sizing: border-box;
}

/* Actual admin page content */
.rp-admin-content {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
  margin: 0 !important;
  box-sizing: border-box;
}

/*
 * The content itself stays comfortably readable while the shell
 * owns the complete viewport. This prevents a white gutter.
 */
.rp-admin-modern-page {
  width: min(
    calc(100% - 56px),
    1240px
  ) !important;
  max-width: 1240px !important;
  margin: 0 auto !important;
  box-sizing: border-box;
}

/* Prevent old application containers from constraining admin pages */
.rp-admin-shell .container,
.rp-admin-shell .page-container,
.rp-admin-shell .app-container,
.rp-admin-shell main,
.rp-admin-shell section {
  max-width: none;
}

/* Admin background must reach the actual viewport edge */
.rp-admin-shell::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(
      circle at 78% 18%,
      rgba(55, 225, 155, .055),
      transparent 25%
    ),
    radial-gradient(
      circle at 48% 90%,
      rgba(27, 153, 104, .045),
      transparent 30%
    );
}

/* Remove accidental light background around admin */
body:has(.rp-admin-shell) {
  background: #021a14 !important;
}

/* Desktop */
@media (min-width: 1100px) {
  .rp-admin-sidebar {
    width: 230px !important;
    min-width: 230px !important;
  }

  .rp-admin-main {
    width: calc(100vw - 230px) !important;
    margin-left: 230px !important;
  }
}

/* Tablet */
@media (max-width: 1099px) {
  .rp-admin-sidebar {
    width: 210px !important;
    min-width: 210px !important;
  }

  .rp-admin-main {
    width: calc(100vw - 210px) !important;
    margin-left: 210px !important;
  }

  .rp-admin-modern-page {
    width: calc(100% - 36px) !important;
  }
}

/* Mobile */
@media (max-width: 760px) {
  .rp-admin-sidebar {
    width: 0 !important;
    min-width: 0 !important;
    transform: translateX(-100%);
  }

  .rp-admin-main {
    width: 100vw !important;
    margin-left: 0 !important;
  }

  .rp-admin-modern-page {
    width: calc(100% - 24px) !important;
  }
}

