/* =========================================================
   ADMIN INVENTORY
   ========================================================= */

.rp-admin-inventory-toolbar {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 12px;
  padding: 13px;
  border: 1px solid rgba(78,231,166,.13);
  border-radius: 15px;
  background: rgba(4,30,24,.75);
}

.rp-admin-inventory-table {
  overflow-x: auto;
}

.rp-admin-inventory-table-head,
.rp-admin-inventory-row {
  min-width: 1050px;
  display: grid;
  grid-template-columns:
    2fr
    1.15fr
    .55fr
    .65fr
    .7fr
    .65fr
    .8fr
    1.15fr;
  gap: 12px;
  align-items: center;
  padding: 0 17px;
}

.rp-admin-inventory-table-head {
  min-height: 42px;
  border-bottom: 1px solid rgba(78,231,166,.09);
  color: #4c7769;
  background: rgba(78,231,166,.018);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .12em;
}

.rp-admin-inventory-row {
  min-height: 78px;
  border-bottom: 1px solid rgba(78,231,166,.065);
  color: #779d90;
  font-size: 9px;
}

.rp-admin-inventory-row:hover {
  background: rgba(78,231,166,.025);
}

.rp-admin-inventory-location {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.rp-admin-inventory-location strong {
  overflow: hidden;
  color: #b7d9cd;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-admin-inventory-location small {
  margin-top: 4px;
  color: #4f786a;
  font-size: 7px;
}

.inventory-number {
  color: #dcfff0;
  font-size: 11px;
}

.inventory-number.muted {
  color: #72978a;
  font-weight: 600;
}

.inventory-number.available {
  color: #58e8a6;
}

.rp-admin-modern-status.inventory-healthy {
  color: #5ee7a5;
  background: rgba(94,231,165,.07);
}

.rp-admin-modern-status.inventory-low {
  color: #f2c76e;
  background: rgba(242,199,110,.07);
}

.rp-admin-modern-status.inventory-out {
  color: #ff8585;
  background: rgba(255,133,133,.07);
}

.rp-admin-modern-status.inventory-inactive {
  color: #8b9e98;
  background: rgba(139,158,152,.07);
}

.rp-admin-inventory-actions {
  display: flex;
  align-items: center;
  gap: 5px;
}

.rp-admin-inventory-actions button {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(78,231,166,.11);
  border-radius: 8px;
  color: #6d9587;
  background: rgba(78,231,166,.035);
  cursor: pointer;
}

.rp-admin-inventory-actions button:hover {
  color: #dffff1;
  border-color: rgba(78,231,166,.28);
  background: rgba(78,231,166,.08);
}

.rp-admin-inventory-actions button:disabled {
  opacity: .35;
  cursor: not-allowed;
}

.rp-admin-inventory-note {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 12px;
  padding: 13px 15px;
  border: 1px solid rgba(78,231,166,.1);
  border-radius: 12px;
  color: #608a7c;
  background: rgba(78,231,166,.025);
  font-size: 9px;
  line-height: 1.5;
}

.rp-admin-inventory-note > div {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #4ee7a6;
  background: rgba(78,231,166,.07);
}

.rp-admin-inventory-modal {
  width: min(480px,100%);
  overflow: hidden;
  border: 1px solid rgba(78,231,166,.2);
  border-radius: 17px;
  background:
    radial-gradient(circle at 80% 0%,rgba(34,136,93,.13),transparent 35%),
    #052a21;
  box-shadow: 0 35px 100px rgba(0,0,0,.4);
}

.rp-admin-inventory-modal.history {
  width: min(650px,100%);
}

.rp-admin-movement-body {
  padding: 20px;
}

.rp-admin-movement-product {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 20px;
  padding: 13px;
  border: 1px solid rgba(78,231,166,.1);
  border-radius: 10px;
  color: #4ee7a6;
  background: rgba(78,231,166,.035);
}

.rp-admin-movement-product > div {
  display: flex;
  flex-direction: column;
}

.rp-admin-movement-product strong {
  color: #dffff1;
  font-size: 11px;
}

.rp-admin-movement-product small {
  margin-top: 4px;
  color: #5d8879;
  font-size: 8px;
}

.rp-admin-movement-body > label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: #71998b;
  font-size: 9px;
  font-weight: 800;
}

.rp-admin-movement-body input {
  height: 43px;
  box-sizing: border-box;
  padding: 0 12px;
  border: 1px solid rgba(78,231,166,.13);
  border-radius: 9px;
  outline: 0;
  color: #e1fff3;
  background: rgba(1,20,16,.7);
  font-size: 12px;
}

.rp-admin-history-list {
  max-height: 430px;
  overflow-y: auto;
}

.rp-admin-history-row {
  display: grid;
  grid-template-columns: 1fr auto 150px;
  gap: 15px;
  align-items: center;
  min-height: 62px;
  padding: 0 20px;
  border-bottom: 1px solid rgba(78,231,166,.065);
}

.rp-admin-history-row > div {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.rp-admin-history-row strong {
  color: #dffbef;
  font-size: 10px;
  text-transform: capitalize;
}

.rp-admin-history-row small {
  margin-top: 4px;
  overflow: hidden;
  color: #547c6e;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-admin-history-row > small {
  text-align: right;
}

.movement-positive {
  color: #59e8a6 !important;
}

.movement-negative {
  color: #ff8e8e !important;
}

@media (max-width: 800px) {
  .rp-admin-inventory-toolbar {
    flex-wrap: wrap;
  }

  .rp-admin-inventory-toolbar .rp-admin-product-search {
    flex-basis: 100%;
  }
}


