/* =========================================================
   INVENTORY — ADMIN SHELL / PAGE COMPOSITION
   ========================================================= */

.rp-admin-modern-page {
  min-height: calc(100vh - 64px);
  padding-top: 38px;
  padding-bottom: 46px;
}

.rp-admin-modern-heading.products-heading {
  min-height: 118px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 22px;
}

.rp-admin-modern-heading.products-heading h1 {
  margin: 5px 0 7px;
  font-size: clamp(42px, 4.2vw, 64px);
  line-height: .94;
  letter-spacing: -.055em;
}

.rp-admin-modern-heading.products-heading p {
  margin: 0;
  max-width: 620px;
  color: #6c9788;
  font-size: 11px;
  line-height: 1.55;
}

.rp-admin-inline-loading {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-left: 10px;
  color: #43d99a;
  font-size: 8px;
  white-space: nowrap;
  vertical-align: middle;
}

.rp-admin-modern-refresh {
  flex: 0 0 auto;
}

/* Inventory metrics should match the Products/Dashboard cards. */
.rp-admin-modern-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.rp-admin-modern-metric {
  position: relative;
  min-height: 92px;
  overflow: hidden;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px;
  box-sizing: border-box;
  border: 1px solid rgba(78,231,166,.13);
  border-radius: 14px;
  background:
    radial-gradient(
      circle at 100% 100%,
      rgba(43,182,125,.11),
      transparent 30%
    ),
    rgba(4,31,24,.78);
}

.rp-admin-modern-metric::after {
  content: "";
  position: absolute;
  right: -22px;
  bottom: -28px;
  width: 66px;
  height: 66px;
  border-radius: 50%;
  background: rgba(55,218,151,.055);
}

.rp-admin-modern-metric-icon {
  position: relative;
  z-index: 1;
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(78,231,166,.15);
  border-radius: 10px;
  color: #4ee7a6;
  background: rgba(78,231,166,.055);
}

.rp-admin-modern-metric-icon.warning {
  color: #eac76e;
  border-color: rgba(234,199,110,.14);
  background: rgba(234,199,110,.045);
}

.rp-admin-modern-metric > div:last-child {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.rp-admin-modern-metric span {
  display: block;
  color: #557d70;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.rp-admin-modern-metric strong {
  display: block;
  margin-top: 3px;
  color: #e8fff5;
  font-size: 25px;
  line-height: 1;
  letter-spacing: -.035em;
}

.rp-admin-modern-metric small {
  display: block;
  margin-top: 5px;
  color: #41685d;
  font-size: 7px;
}

/* Toolbar */
.rp-admin-inventory-toolbar {
  min-height: 54px;
  box-sizing: border-box;
  margin-bottom: 12px;
  padding: 7px;
  border-radius: 13px;
  background: rgba(4,31,24,.72);
}

.rp-admin-product-search {
  height: 38px;
}

.rp-admin-product-search input {
  color: #bfe8d9;
}

.rp-admin-product-search input::placeholder {
  color: #41695d;
}

/* Table container */
.rp-admin-product-table-card.rp-admin-inventory-table {
  border: 1px solid rgba(78,231,166,.12);
  border-radius: 14px;
  background:
    linear-gradient(
      180deg,
      rgba(5,36,28,.64),
      rgba(2,25,20,.78)
    );
}

/* Give the inventory table a proper dense admin appearance. */
.rp-admin-inventory-row {
  min-height: 70px;
}

.rp-admin-product-identity {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.rp-admin-product-thumb {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(78,231,166,.13);
  border-radius: 9px;
  color: #4ee7a6;
  background: rgba(78,231,166,.045);
}

.rp-admin-product-identity > div:last-child {
  min-width: 0;
}

.rp-admin-product-identity strong {
  display: block;
  overflow: hidden;
  color: #d7f6ea;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-admin-product-identity small {
