  margin-top: 3px;
  color: #456d61;
  font-size: 7px;
}

.rp-admin-product-table-footer {
  min-height: 38px;
  display: flex;
  align-items: center;
  padding: 0 17px;
  box-sizing: border-box;
  color: #456c60;
  font-size: 7px;
}

/* Remove any accidental light page surface from inventory. */
body:has(.rp-admin-shell),
body:has(.rp-admin-modern-page) {
  background: #021a14 !important;
}

@media (max-width: 950px) {
  .rp-admin-modern-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rp-admin-modern-heading.products-heading {
    align-items: flex-start;
  }
