    grid-template-columns: 1fr;
  }
}


/* =========================================================
   GREENCORE ADMIN — ORDER STATUS PICKER
   ========================================================= */

.rp-admin-order-status-cell {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 150px;
  overflow: visible;
}

.rp-admin-status-picker {
  position: relative;
  display: inline-flex;
  z-index: 20;
}

.rp-admin-status-trigger {
  width: 34px;
  height: 30px;
  padding: 0;
  border: 1px solid rgba(108, 230, 165, 0.18);
  border-radius: 9px;
  background: rgba(9, 42, 32, 0.72);
  color: rgba(221, 255, 238, 0.78);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  cursor: pointer;
  transition:
    width 180ms ease,
    border-color 180ms ease,
    background 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}

.rp-admin-status-trigger:hover,
.rp-admin-status-trigger.open {
  width: 38px;
  border-color: rgba(101, 235, 168, 0.48);
  background: rgba(17, 72, 53, 0.92);
  box-shadow:
    0 0 0 1px rgba(101, 235, 168, 0.06),
    0 8px 24px rgba(0, 0, 0, 0.22);
}

.rp-admin-status-trigger:active {
  transform: translateY(1px);
}

.rp-admin-status-trigger:disabled {
  opacity: 0.65;
  cursor: wait;
}

.rp-admin-status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: block;
  box-shadow: 0 0 8px currentColor;
}

.rp-admin-status-dot.pending {
  color: #e6c66b;
  background: currentColor;
}

.rp-admin-status-dot.confirmed {
  color: #70d9a0;
  background: currentColor;
}

.rp-admin-status-dot.processing {
  color: #70c7ff;
  background: currentColor;
}

.rp-admin-status-dot.shipped {
  color: #83b7ff;
  background: currentColor;
}

.rp-admin-status-dot.delivered {
  color: #68e6a4;
  background: currentColor;
}

.rp-admin-status-dot.cancelled {
  color: #ef7777;
  background: currentColor;
}

.rp-admin-status-chevron {
  transition: transform 180ms ease;
  opacity: 0.7;
}

.rp-admin-status-trigger.open .rp-admin-status-chevron {
  transform: rotate(180deg);
}

.rp-admin-status-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 184px;
  padding: 6px;
  border: 1px solid rgba(103, 230, 168, 0.22);
  border-radius: 14px;
  background:
    linear-gradient(
      145deg,
      rgba(8, 42, 31, 0.98),
      rgba(3, 24, 19, 0.99)
    );
  box-shadow:
    0 20px 45px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(95, 226, 161, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  animation: rp-status-menu-in 150ms ease-out;
  z-index: 100;
}

.rp-admin-status-menu::before {
  content: "";
  position: absolute;
  top: -5px;
  right: 12px;
  width: 9px;
  height: 9px;
  background: #082a20;
  border-left: 1px solid rgba(103, 230, 168, 0.22);
  border-top: 1px solid rgba(103, 230, 168, 0.22);
  transform: rotate(45deg);
}

.rp-admin-status-option {
  position: relative;
  width: 100%;
  min-height: 38px;
  padding: 7px 9px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: rgba(225, 248, 237, 0.74);
  display: flex;
  align-items: center;
  gap: 9px;
  text-align: left;
  cursor: pointer;
  transition:
    background 150ms ease,
    color 150ms ease,
    transform 150ms ease;
}

.rp-admin-status-option:hover {
  background: rgba(91, 222, 157, 0.09);
  color: #ecfff5;
  transform: translateX(2px);
}

.rp-admin-status-option.selected {
  background: rgba(91, 222, 157, 0.13);
  color: #effff6;
}

.rp-admin-status-option-icon {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.045);
}

.rp-admin-status-option-icon.pending {
  color: #e6c66b;
}

.rp-admin-status-option-icon.confirmed {
  color: #70d9a0;
}

.rp-admin-status-option-icon.processing {
  color: #70c7ff;
}

.rp-admin-status-option-icon.shipped {
  color: #83b7ff;
}

.rp-admin-status-option-icon.delivered {
  color: #68e6a4;
}

.rp-admin-status-option-icon.cancelled {
  color: #ef7777;
}

.rp-admin-status-option-label {
  flex: 1;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.rp-admin-status-option-check {
  color: #6ce6a5;
  opacity: 0.95;
}

@keyframes rp-status-menu-in {
  from {
    opacity: 0;
    transform: translateY(-5px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 900px) {
  .rp-admin-status-menu {
    right: auto;
    left: 0;
  }

  .rp-admin-status-menu::before {
    right: auto;
    left: 12px;
  }
}

/* Fix status dropdown stacking between order rows */
.rp-admin-order-row {
  position: relative;
  z-index: 1;
}

.rp-admin-order-row:has(.rp-admin-status-trigger.open) {
  z-index: 1000;
}

.rp-admin-order-row:has(.rp-admin-status-trigger.open) .rp-admin-status-picker {
  z-index: 1001;
}

.rp-admin-order-row:has(.rp-admin-status-trigger.open) .rp-admin-status-menu {
  z-index: 1002;
  isolation: isolate;
  background: linear-gradient(
    145deg,
    rgb(8, 42, 31),
    rgb(3, 24, 19)
  );
}

/* Prevent controls from neighbouring rows visually bleeding through */
.rp-admin-status-menu,
.rp-admin-status-menu::before {
  opacity: 1;
}



/* Cancelled admin orders are permanently locked */
.rp-admin-status-trigger.locked {
  cursor: not-allowed;
  opacity: 0.72;
  border-color: rgba(239, 119, 119, 0.16);
  background: rgba(60, 25, 25, 0.42);
}

.rp-admin-status-trigger.locked:hover {
  width: 34px;
  border-color: rgba(239, 119, 119, 0.22);
  background: rgba(60, 25, 25, 0.52);
  box-shadow: none;
  transform: none;
}

/* =========================================================
   GREENCORE INVENTORY — CLEAR STOCK ACTIONS
   ========================================================= */

.rp-admin-inventory-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  white-space: nowrap;
}

.rp-admin-inventory-actions button {
  min-height: 32px;
  padding: 0 10px;
