}

.shipment-status-shipped {
  color: #65caff;
  background: rgba(63, 170, 232, 0.08);
  border-color: rgba(63, 170, 232, 0.16);
}

.shipment-status-in_transit {
  color: #54d9ff;
  background: rgba(48, 185, 221, 0.08);
  border-color: rgba(48, 185, 221, 0.16);
}

.shipment-status-out_for_delivery {
  color: #d5a6ff;
  background: rgba(171, 101, 232, 0.08);
