  gap: 16px;
  color: rgba(169, 207, 193, 0.62);
  font-size: 10px;
}

.rp-admin-shipment-pagination {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rp-admin-shipment-pagination button,
.rp-admin-shipment-pagination span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  border-radius: 9px;
}

.rp-admin-shipment-pagination button {
  border: 1px solid rgba(47, 208, 136, 0.16);
