}

.rp-admin-shipment-address,
.rp-admin-shipment-notes {
  margin-top: 12px;
}

.rp-admin-shipment-modal-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 22px;
}

.rp-admin-shipment-modal-actions button {
  min-height: 38px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(56, 227, 145, 0.30);
  border-radius: 10px;
  background: rgba(21, 138, 87, 0.16);
  color: #eafff6;
  cursor: pointer;
  font: inherit;
  font-size: 10px;
  font-weight: 800;
}

.rp-admin-shipment-modal-actions button:hover {
  background: rgba(30, 157, 99, 0.25);
}

.rp-admin-shipment-modal-actions button.danger {
  color: #ffaaaa;
  border-color: rgba(239, 91, 91, 0.30);
