/* =========================================================
   GREENCORE ADMIN SETTINGS
   ========================================================= */

.rp-admin-settings-page {
  min-height: 100%;
  padding: 44px 38px 58px;
  box-sizing: border-box;
  color: #eafff6;
  overflow-x: hidden;
}

.rp-admin-settings-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}

.rp-admin-settings-hero h1 {
  margin: 8px 0;
  color: #f1fff9;
  font-size: clamp(38px, 4vw, 54px);
  line-height: 1;
  letter-spacing: -0.045em;
}

.rp-admin-settings-hero p {
  margin: 0;
  color: rgba(185, 220, 207, 0.66);
  font-size: 14px;
}

.rp-admin-settings-save {
  min-height: 42px;
  padding: 0 18px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(57, 230, 148, 0.35);
  border-radius: 11px;
  background: rgba(26, 142, 89, 0.18);
  color: #eafff6;
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
}

.rp-admin-settings-save:hover {
  border-color: rgba(65, 239, 155, 0.65);
  background: rgba(28, 157, 99, 0.27);
}

.rp-admin-settings-success {
  min-height: 42px;
  margin-bottom: 18px;
  padding: 0 15px;
  display: flex;
  align-items: center;
  gap: 9px;
  box-sizing: border-box;
  border: 1px solid rgba(56, 227, 145, 0.22);
  border-radius: 11px;
  background: rgba(31, 181, 113, 0.08);
  color: #69e9aa;
  font-size: 11px;
}

.rp-admin-settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.rp-admin-settings-card {
  min-width: 0;
  padding: 22px;
  box-sizing: border-box;
  border: 1px solid rgba(47, 211, 136, 0.19);
  border-radius: 17px;
  background:
    radial-gradient(circle at 100% 0%, rgba(33, 194, 122, 0.045), transparent 38%),
    rgba(2, 38, 28, 0.70);
}

.rp-admin-settings-card-heading {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 22px;
}

.rp-admin-settings-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: #4be8a0;
  border: 1px solid rgba(59, 227, 146, 0.20);
  background: rgba(30, 187, 115, 0.09);
}

.rp-admin-settings-icon.security {
  color: #72caff;
}

.rp-admin-settings-icon.notification {
  color: #e7c35d;
}

.rp-admin-settings-icon.operations {
  color: #8fe2bb;
}

.rp-admin-settings-icon.system {
  color: #b789ff;
}

.rp-admin-settings-card-heading h2 {
  margin: 1px 0 4px;
  color: #effff8;
  font-size: 16px;
}

.rp-admin-settings-card-heading p {
  margin: 0;
  color: rgba(169, 207, 193, 0.55);
  font-size: 10px;
}

.rp-admin-settings-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.rp-admin-settings-form-grid label,
.rp-admin-settings-toggle {
  position: relative;
  min-width: 0;
}

.rp-admin-settings-form-grid label.full {
  grid-column: 1 / -1;
}

.rp-admin-settings-form-grid label > span,
.rp-admin-settings-toggle > div > span {
  display: block;
  margin-bottom: 7px;
  color: rgba(160, 202, 185, 0.50);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.10em;
}

.rp-admin-settings-form-grid input,
.rp-admin-settings-form-grid select {
  width: 100%;
  height: 40px;
  padding: 0 12px;
  box-sizing: border-box;
  border: 1px solid rgba(47, 210, 136, 0.16);
  border-radius: 10px;
  outline: none;
  background: rgba(2, 29, 22, 0.62);
  color: #eafff6;
  font: inherit;
  font-size: 11px;
}

.rp-admin-settings-form-grid input:focus,
.rp-admin-settings-form-grid select:focus {
  border-color: rgba(59, 231, 148, 0.50);
  box-shadow: 0 0 0 3px rgba(46, 221, 140, 0.05);
}

.rp-admin-settings-form-grid input::placeholder {
  color: rgba(162, 202, 187, 0.35);
}

.rp-admin-settings-form-grid select option {
  background: #052b20;
  color: #eafff6;
}

.rp-admin-settings-input-with-icon {
  position: relative;
}

.rp-admin-settings-input-with-icon > svg {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(94, 217, 160, 0.58);
  pointer-events: none;
}

.rp-admin-settings-input-with-icon input {
  padding-left: 37px;
}

.rp-admin-settings-account-meta {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-top: 16px;
}

.rp-admin-settings-account-meta > div {
  padding: 12px;
  border: 1px solid rgba(48, 207, 134, 0.11);
  border-radius: 10px;
  background: rgba(9, 65, 46, 0.22);
}

.rp-admin-settings-account-meta span {
  display: block;
  margin-bottom: 5px;
  color: rgba(160, 202, 185, 0.45);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.rp-admin-settings-account-meta strong {
  color: #dff8ed;
  font-size: 10px;
}

.settings-active,
.settings-enabled,
.system-online {
  display: inline-flex !important;
  align-items: center;
  gap: 6px;
}

.settings-active i,
.settings-enabled i,
.system-online i {
  width: 6px;
  height: 6px;
  display: inline-block;
  border-radius: 50%;
  background: #45e99b;
  box-shadow: 0 0 8px rgba(69, 233, 155, 0.8);
}

.rp-admin-settings-security-row {
  min-height: 67px;
  padding: 12px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 11px;
  border: 1px solid rgba(48, 207, 134, 0.11);
  border-radius: 11px;
  background: rgba(7, 62, 44, 0.22);
}

.rp-admin-settings-security-row + .rp-admin-settings-security-row {
  margin-top: 10px;
}

.settings-security-symbol {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #69caff;
  background: rgba(68, 181, 236, 0.08);
}

.rp-admin-settings-security-row > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.rp-admin-settings-security-row strong,
.rp-admin-settings-security-row span {
  display: block;
}

.rp-admin-settings-security-row strong {
  color: #eafff6;
  font-size: 11px;
}

.rp-admin-settings-security-row > div:nth-child(2) span {
  margin-top: 4px;
  color: rgba(169, 207, 193, 0.48);
  font-size: 9px;
}

.rp-admin-settings-security-row button {
  min-height: 32px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid rgba(55, 216, 140, 0.20);
  border-radius: 8px;
  background: rgba(21, 117, 77, 0.24);
  color: #dff9ed;
  cursor: pointer;
  font: inherit;
  font-size: 9px;
  font-weight: 700;
}

.settings-enabled {
  color: #55e5a0;
  font-size: 9px;
  white-space: nowrap;
}

.rp-admin-settings-toggle-list {
  display: flex;
  flex-direction: column;
}

.rp-admin-settings-toggle {
  min-height: 63px;
  padding: 12px 2px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 14px;
  border-bottom: 1px solid rgba(49, 205, 133, 0.09);
  cursor: pointer;
}

.rp-admin-settings-toggle:last-child {
  border-bottom: 0;
}

.rp-admin-settings-toggle > div {
  min-width: 0;
  flex: 1;
}

.rp-admin-settings-toggle strong {
  display: block;
  margin-bottom: 4px;
  color: #eafff6;
  font-size: 11px;
}

.rp-admin-settings-toggle > div > span {
  margin: 0;
  color: rgba(169, 207, 193, 0.48);
  font-size: 9px;
  letter-spacing: normal;
  font-weight: 400;
}

.rp-admin-settings-toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.settings-toggle-ui {
  position: relative;
  width: 38px;
  height: 21px;
  flex: 0 0 38px;
  border-radius: 999px;
  background: rgba(111, 143, 132, 0.25);
  border: 1px solid rgba(164, 207, 192, 0.12);
  transition: 160ms ease;
}

.settings-toggle-ui::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: rgba(224, 245, 237, 0.70);
  transition: 160ms ease;
}

.rp-admin-settings-toggle input:checked + .settings-toggle-ui {
  background: rgba(36, 197, 124, 0.27);
  border-color: rgba(58, 230, 148, 0.40);
}

.rp-admin-settings-toggle input:checked + .settings-toggle-ui::after {
  left: 20px;
  background: #51eaa1;
  box-shadow: 0 0 8px rgba(81, 234, 161, 0.45);
}

.operation-toggle {
  margin-top: 16px;
  padding: 14px 0 0;
  border-top: 1px solid rgba(49, 205, 133, 0.09);
  border-bottom: 0;
}

.rp-admin-system-list {
  display: flex;
  flex-direction: column;
}

.rp-admin-system-list > div {
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid rgba(49, 205, 133, 0.09);
}

.rp-admin-system-list > div:last-child {
  border-bottom: 0;
}

.rp-admin-system-list > div > div {
  display: flex;
  align-items: center;
  gap: 9px;
  color: rgba(194, 225, 213, 0.72);
  font-size: 10px;
}

.rp-admin-system-list > div > div svg {
  color: rgba(92, 222, 163, 0.68);
}

.rp-admin-system-list strong {
  color: rgba(225, 248, 239, 0.72);
  font-size: 9px;
}

.rp-admin-system-list .system-online {
  color: #51e5a0;
}

@media (max-width: 1050px) {
  .rp-admin-settings-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 700px) {
  .rp-admin-settings-page {
    padding: 30px 18px 44px;
  }

  .rp-admin-settings-hero {
    flex-direction: column;
  }

  .rp-admin-settings-save {
    width: 100%;
    justify-content: center;
  }

  .rp-admin-settings-form-grid {
    grid-template-columns: 1fr;
  }

  .rp-admin-settings-form-grid label.full {
    grid-column: auto;
  }

  .rp-admin-settings-account-meta {
    grid-template-columns: 1fr;
  }

  .rp-admin-settings-security-row {
    align-items: flex-start;
    flex-wrap: wrap;
  }
}


