  box-sizing: border-box !important;

  background:
    linear-gradient(
      180deg,
      #032b21 0%,
      #021f19 55%,
      #011a15 100%
    ) !important;

  border-right: 1px solid rgba(57,230,160,.13) !important;
}

/* Sidebar inner containers must not create giant vertical gaps */
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar > *,
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar nav,
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar .rp-admin-nav {
  width: 100% !important;
  box-sizing: border-box !important;
}

/* Brand / logo */
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar .rp-admin-brand {
  width: 48px !important;
  min-width: 48px !important;
  height: 48px !important;
  min-height: 48px !important;
  margin: 0 auto 25px !important;
  padding: 0 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  border-radius: 14px !important;
}

/* Hide brand text */
.rp-admin-layout.sidebar-collapsed .rp-admin-brand span,
.rp-admin-layout.sidebar-collapsed .rp-admin-brand strong,
.rp-admin-layout.sidebar-collapsed .rp-admin-brand small,
.rp-admin-layout.sidebar-collapsed .rp-admin-brand div:not(:has(svg)) {
  display: none !important;
}

/* Navigation is a compact vertical rail */
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar nav,
.rp-admin-layout.sidebar-collapsed .rp-admin-nav {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 7px !important;
  flex: 0 0 auto !important;
}

/* Remove section spacing */
.rp-admin-layout.sidebar-collapsed .rp-admin-nav-title,
.rp-admin-layout.sidebar-collapsed .rp-admin-section-title {
  display: none !important;
}

/* Icon buttons */
.rp-admin-layout.sidebar-collapsed .rp-admin-nav a,
.rp-admin-layout.sidebar-collapsed .rp-admin-nav button {
  width: 50px !important;
  min-width: 50px !important;
  max-width: 50px !important;
  height: 44px !important;
  min-height: 44px !important;

  margin: 0 auto !important;
  padding: 0 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  gap: 0 !important;
  border-radius: 11px !important;
}

/* Hide labels */
.rp-admin-layout.sidebar-collapsed .rp-admin-nav a span,
.rp-admin-layout.sidebar-collapsed .rp-admin-nav button span {
  display: none !important;
}

/* Center icons */
.rp-admin-layout.sidebar-collapsed .rp-admin-nav svg {
  width: 19px !important;
  height: 19px !important;
  margin: 0 !important;
}

/* Bottom controls stay at bottom, but compact */
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar-bottom {
  margin-top: auto !important;
  width: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 8px !important;
}

/* User card */
.rp-admin-layout.sidebar-collapsed .rp-admin-user {
  width: 50px !important;
  min-width: 50px !important;
  height: 50px !important;
  min-height: 50px !important;

  margin: 0 auto !important;
  padding: 0 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  border-radius: 13px !important;
}

/* Hide email / role / logout text */
.rp-admin-layout.sidebar-collapsed .rp-admin-user span,
.rp-admin-layout.sidebar-collapsed .rp-admin-user strong,
.rp-admin-layout.sidebar-collapsed .rp-admin-user p,
.rp-admin-layout.sidebar-collapsed .rp-admin-user button {
  display: none !important;
}

/* Collapse button */
.rp-admin-layout.sidebar-collapsed .rp-admin-collapse {
  width: 50px !important;
  min-width: 50px !important;
  height: 40px !important;
  min-height: 40px !important;

  margin: 0 auto !important;
  padding: 0 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  border-radius: 10px !important;
}

/* Hide collapse text */
.rp-admin-layout.sidebar-collapsed .rp-admin-collapse span {
  display: none !important;
}

/* Main content gets exactly the compact rail width */
.rp-admin-layout.sidebar-collapsed .rp-admin-main,
.rp-admin-layout.sidebar-collapsed main {
  margin-left: 76px !important;
  width: calc(100% - 76px) !important;
}

/* Smooth transition */
.rp-admin-sidebar,
.rp-admin-main,
.rp-admin-layout main {
  transition:
    width .22s ease,
    margin-left .22s ease !important;
}

/* Never allow collapsed sidebar children to stretch the rail */
.rp-admin-layout.sidebar-collapsed .rp-admin-sidebar * {
  max-width: 100% !important;
}

@media (max-width: 760px) {
  .rp-admin-layout.sidebar-collapsed .rp-admin-sidebar {
    width: 68px !important;
    min-width: 68px !important;
    max-width: 68px !important;
  }

  .rp-admin-layout.sidebar-collapsed .rp-admin-main,
  .rp-admin-layout.sidebar-collapsed main {
    margin-left: 68px !important;
    width: calc(100% - 68px) !important;
  }
}

/* =========================================================
   GREENCORE ADMIN — ACTUAL COLLAPSED SIDEBAR
   State: .rp-admin-shell.is-collapsed
   ========================================================= */

/* Shell */
.rp-admin-shell {
  --admin-sidebar-width: 220px;
}

.rp-admin-shell.is-collapsed {
  --admin-sidebar-width: 76px;
}

/* Sidebar */
.rp-admin-shell .rp-admin-sidebar {
  width: var(--admin-sidebar-width) !important;
  min-width: var(--admin-sidebar-width) !important;
  max-width: var(--admin-sidebar-width) !important;
  transition:
    width .25s cubic-bezier(.4,0,.2,1),
    min-width .25s cubic-bezier(.4,0,.2,1) !important;
  overflow: hidden !important;
}

/* Main area automatically follows sidebar */
.rp-admin-shell .rp-admin-main {
  width: calc(100% - var(--admin-sidebar-width)) !important;
  margin-left: var(--admin-sidebar-width) !important;
  transition:
    width .25s cubic-bezier(.4,0,.2,1),
    margin-left .25s cubic-bezier(.4,0,.2,1) !important;
}

/* =========================================================
   COLLAPSED STATE
   ========================================================= */

.rp-admin-shell.is-collapsed .rp-admin-sidebar {
  width: 76px !important;
  min-width: 76px !important;
  max-width: 76px !important;
  padding: 14px 9px !important;
  box-sizing: border-box !important;
  background:
    linear-gradient(180deg, #032d23 0%, #02241c 55%, #011c16 100%) !important;
  border-right: 1px solid rgba(57,230,160,.12) !important;
}

/* Brand becomes a clean logo tile */
.rp-admin-shell.is-collapsed .rp-admin-brand {
  width: 50px !important;
  min-width: 50px !important;
  height: 50px !important;
  min-height: 50px !important;
  margin: 0 auto 25px !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  border-radius: 14px !important;
  background: rgba(57,230,160,.055) !important;
  border: 1px solid rgba(57,230,160,.17) !important;
}

/* Center logo mark */
.rp-admin-shell.is-collapsed .rp-admin-brand-mark {
  width: 36px !important;
  height: 36px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
}

/* Hide text and mobile close button */
.rp-admin-shell.is-collapsed .rp-admin-brand-copy,
.rp-admin-shell.is-collapsed .rp-admin-mobile-close {
  display: none !important;
}

/* Navigation label disappears */
.rp-admin-shell.is-collapsed .rp-admin-nav-label {
  display: none !important;
}

/* Navigation groups */
.rp-admin-shell.is-collapsed .rp-admin-nav {
  width: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 7px !important;
  margin: 0 !important;
}

/* Navigation links */
.rp-admin-shell.is-collapsed .rp-admin-nav-item {
  position: relative !important;
  width: 50px !important;
  min-width: 50px !important;
  max-width: 50px !important;
  height: 44px !important;
  min-height: 44px !important;
  margin: 0 auto !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 11px !important;
  gap: 0 !important;
}

/* Only icons remain */
.rp-admin-shell.is-collapsed .rp-admin-nav-item span,
.rp-admin-shell.is-collapsed .rp-admin-nav-item .nav-arrow {
  display: none !important;
}

.rp-admin-shell.is-collapsed .rp-admin-nav-item svg {
  width: 19px !important;
  height: 19px !important;
  margin: 0 !important;
  flex: 0 0 auto !important;
}

/* Hover */
.rp-admin-shell.is-collapsed .rp-admin-nav-item:hover {
  background: rgba(57,230,160,.08) !important;
  border-color: rgba(57,230,160,.18) !important;
  color: #59e9af !important;
}

/* Active */
.rp-admin-shell.is-collapsed .rp-admin-nav-item.active {
  background:
    linear-gradient(
      135deg,
      rgba(57,230,160,.14),
      rgba(57,230,160,.035)
    ) !important;
  border: 1px solid rgba(57,230,160,.28) !important;
  color: #59e9af !important;
  box-shadow:
    inset 2px 0 0 #4ce8aa,
    0 5px 18px rgba(0,0,0,.08) !important;
}

/* Keep the divider/spacer compact */
.rp-admin-shell.is-collapsed .rp-admin-sidebar-spacer {
  flex: 1 1 auto !important;
  min-height: 20px !important;
}

/* =========================================================
   USER CARD
   ========================================================= */

.rp-admin-shell.is-collapsed .rp-admin-user-card {
  width: 50px !important;
  min-width: 50px !important;
  max-width: 50px !important;
  height: 50px !important;
  min-height: 50px !important;
  margin: 8px auto !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 13px !important;
  background: rgba(57,230,160,.045) !important;
  border: 1px solid rgba(57,230,160,.14) !important;
}

.rp-admin-shell.is-collapsed .rp-admin-user-info,
.rp-admin-shell.is-collapsed .rp-admin-logout {
  display: none !important;
}

.rp-admin-shell.is-collapsed .rp-admin-avatar {
  width: 34px !important;
  height: 34px !important;
  min-width: 34px !important;
  min-height: 34px !important;
  margin: 0 !important;
  display: grid !important;
  place-items: center !important;
}

/* =========================================================
   COLLAPSE BUTTON
   ========================================================= */

.rp-admin-shell.is-collapsed .rp-admin-collapse {
  width: 50px !important;
  min-width: 50px !important;
  max-width: 50px !important;
  height: 40px !important;
  min-height: 40px !important;
  margin: 0 auto !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 0 !important;
  border-radius: 10px !important;
  border: 1px solid rgba(57,230,160,.15) !important;
  background: rgba(57,230,160,.035) !important;
}

.rp-admin-shell.is-collapsed .rp-admin-collapse span {
  display: none !important;
}

.rp-admin-shell.is-collapsed .rp-admin-collapse:hover {
  background: rgba(57,230,160,.09) !important;
  border-color: rgba(57,230,160,.30) !important;
  color: #59e9af !important;
}

/* Content fills the space immediately */
.rp-admin-shell.is-collapsed .rp-admin-content {
  width: 100% !important;
  max-width: none !important;
}

/* =========================================================
   DESKTOP ONLY
   ========================================================= */

@media (min-width: 761px) {
  .rp-admin-shell.is-collapsed .rp-admin-mobile-backdrop {
    display: none !important;
  }
}

/* Mobile should use the existing mobile drawer behavior */
@media (max-width: 760px) {
  .rp-admin-shell,
  .rp-admin-shell.is-collapsed {
    --admin-sidebar-width: 0px;
  }

  .rp-admin-shell .rp-admin-main {
    width: 100% !important;
    margin-left: 0 !important;
  }
}

/* =========================================================
   GREENCORE — PRODUCT REVIEWS & RATINGS
   ========================================================= */

.product-reviews-section {
  margin-top: 72px;
  padding: 42px;
  border: 1px solid rgba(110, 231, 183, 0.14);
  border-radius: 28px;
  background:
    radial-gradient(circle at 85% 10%, rgba(34, 197, 94, 0.08), transparent 30%),
    linear-gradient(145deg, rgba(5, 35, 27, 0.92), rgba(3, 25, 20, 0.96));
  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.product-reviews-header {
  margin-bottom: 30px;
}

.product-reviews-header h2 {
  margin: 10px 0 6px;
  color: #f0fdf4;
  font-size: clamp(26px, 3vw, 38px);
  line-height: 1.1;
  letter-spacing: -0.035em;
}

.product-reviews-header p {
  margin: 0;
  color: rgba(209, 250, 229, 0.62);
}

.product-rating-overview {
  display: grid;
  grid-template-columns: minmax(190px, 0.8fr) minmax(300px, 1.2fr);
  gap: 42px;
  padding: 28px;
  margin-bottom: 28px;
  border: 1px solid rgba(110, 231, 183, 0.11);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.025);
}

.product-rating-score {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 8px;
}

.product-rating-score > strong {
  color: #ecfdf5;
  font-size: 58px;
  line-height: 1;
  letter-spacing: -0.06em;
}

.product-rating-score > span:last-child {
  color: rgba(209, 250, 229, 0.55);
  font-size: 13px;
}

.rating-stars {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: #6ee7a0;
}

.review-star-static,
.review-star-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
}

.review-star-static {
  cursor: default;
}

.review-star-button {
  cursor: pointer;
  transition:
    transform 0.18s ease,
    color 0.18s ease;
}

.review-star-button:hover {
  transform: scale(1.14);
  color: #86efac;
}

.review-star-button:disabled {
  opacity: 1;
}

.rating-distribution {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
}

.rating-distribution-row {
  display: grid;
  grid-template-columns: 12px 16px minmax(80px, 1fr) 30px;
  align-items: center;
  gap: 8px;
  color: rgba(209, 250, 229, 0.7);
  font-size: 13px;
}

.rating-distribution-row > svg {
  color: #6ee7a0;
}

.rating-distribution-row small {
  color: rgba(209, 250, 229, 0.45);
  text-align: right;
}

.rating-bar {
  height: 7px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.07);
}

.rating-bar > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #34d399, #86efac);
  transition: width 0.35s ease;
}

.product-review-form,
.product-review-login {
  margin-bottom: 28px;
  padding: 28px;
  border: 1px solid rgba(110, 231, 183, 0.12);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.025);
}

.product-review-form-header h3,
.product-review-login h3 {
  margin: 0 0 5px;
  color: #ecfdf5;
  font-size: 19px;
}

.product-review-form-header p,
.product-review-login p {
  margin: 0 0 22px;
  color: rgba(209, 250, 229, 0.55);
  font-size: 14px;
}

.review-rating-picker {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
  color: rgba(236, 253, 245, 0.72);
  font-size: 14px;
}

.product-review-form input,
.product-review-form textarea {
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 14px;
  padding: 14px 16px;
  border: 1px solid rgba(110, 231, 183, 0.12);
  border-radius: 13px;
  outline: none;
  background: rgba(0, 0, 0, 0.16);
  color: #ecfdf5;
  font: inherit;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.product-review-form input::placeholder,
.product-review-form textarea::placeholder {
  color: rgba(209, 250, 229, 0.34);
}

.product-review-form input:focus,
.product-review-form textarea:focus {
  border-color: rgba(110, 231, 183, 0.45);
  background: rgba(0, 0, 0, 0.22);
  box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.07);
}

.product-review-form textarea {
  min-height: 130px;
  resize: vertical;
}

.review-form-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.product-review-form .product-detail-add,
.product-review-login .product-detail-add {
  width: auto;
  min-width: 150px;
  justify-content: center;
  border: 0;
  text-decoration: none;
}

.product-review-form .product-detail-add:disabled {
  cursor: wait;
  opacity: 0.55;
}

.review-cancel-button {
  min-height: 46px;
  padding: 0 18px;
  border: 1px solid rgba(110, 231, 183, 0.15);
  border-radius: 12px;
  background: transparent;
  color: rgba(236, 253, 245, 0.7);
  cursor: pointer;
}

.product-review-login {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.product-review-login .product-detail-add {
  display: inline-flex;
  align-items: center;
  margin-top: 2px;
}

.product-review-message {
  margin: 12px 0;
  padding: 12px 15px;
  border: 1px solid rgba(110, 231, 183, 0.1);
  border-radius: 11px;
  background: rgba(52, 211, 153, 0.06);
  color: rgba(209, 250, 229, 0.78);
  font-size: 13px;
}

.product-review-message.error {
  border-color: rgba(248, 113, 113, 0.2);
  background: rgba(248, 113, 113, 0.06);
  color: #fecaca;
}

.product-review-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.product-review-card {
  padding: 24px;
  border: 1px solid rgba(110, 231, 183, 0.1);
  border-radius: 19px;
  background: rgba(0, 0, 0, 0.13);
  transition:
    border-color 0.2s ease,
    transform 0.2s ease,
    background 0.2s ease;
}

.product-review-card:hover {
  border-color: rgba(110, 231, 183, 0.18);
  background: rgba(0, 0, 0, 0.17);
  transform: translateY(-1px);
}

.product-review-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.product-review-card-top > div {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.product-review-card-top strong {
  color: #ecfdf5;
  font-size: 15px;
}

.product-review-card-top time {
  color: rgba(209, 250, 229, 0.38);
  font-size: 12px;
  white-space: nowrap;
}

.product-review-card h3 {
  margin: 17px 0 7px;
  color: #ecfdf5;
  font-size: 16px;
}

.product-review-card > p {
  margin: 0;
  color: rgba(209, 250, 229, 0.64);
  font-size: 14px;
  line-height: 1.7;
}

.product-review-actions {
  display: flex;
  gap: 8px;
  margin-top: 17px;
}

.product-review-actions button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border: 1px solid rgba(110, 231, 183, 0.1);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.025);
  color: rgba(209, 250, 229, 0.55);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  transition:
    color 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease;
}

.product-review-actions button:hover {
  border-color: rgba(110, 231, 183, 0.24);
  background: rgba(52, 211, 153, 0.06);
  color: #a7f3d0;
}

.product-review-actions button:last-child:hover {
  border-color: rgba(248, 113, 113, 0.2);
  background: rgba(248, 113, 113, 0.05);
  color: #fca5a5;
}

.product-review-actions button:disabled {
  cursor: wait;
  opacity: 0.45;
}

.product-review-empty {
  display: flex;
  min-height: 150px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 30px;
  border: 1px dashed rgba(110, 231, 183, 0.12);
  border-radius: 18px;
  text-align: center;
  color: rgba(209, 250, 229, 0.5);
}

.product-review-empty svg {
  margin-bottom: 9px;
  color: #6ee7a0;
}

.product-review-empty h3 {
  margin: 0 0 5px;
  color: #ecfdf5;
  font-size: 17px;
}

.product-review-empty p {
  margin: 0;
  font-size: 13px;
}

@media (max-width: 760px) {
  .product-reviews-section {
    margin-top: 45px;
    padding: 22px;
    border-radius: 20px;
  }

  .product-rating-overview {
    grid-template-columns: 1fr;
    gap: 26px;
    padding: 21px;
  }

  .product-rating-score {
    align-items: center;
  }

  .product-review-form,
  .product-review-login {
    padding: 21px;
  }

  .review-rating-picker {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }

  .product-review-card {
    padding: 19px;
  }

  .product-review-card-top {
    flex-direction: column;
    gap: 10px;
  }
}


/* Review star visibility fix */
.rating-stars {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.review-star-button,
.review-star-static {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.review-star-button {
  border: 0;
  background: transparent;
  padding: 2px;
  margin: 0;
  cursor: pointer;
  transition: transform 0.15s ease, color 0.15s ease, opacity 0.15s ease;
}

.review-star-button:hover {
