/* GreenCore Contact Page */
.contact-page {
  min-height: 100vh;
  padding: 32px 20px 80px;
  background:
    radial-gradient(circle at 12% 10%, rgba(42, 211, 145, 0.08), transparent 30%),
    radial-gradient(circle at 88% 25%, rgba(42, 211, 145, 0.06), transparent 28%),
    #031c16;
}

.contact-page-container {
  width: min(1180px, 100%);
  margin: 0 auto;
}

.contact-back-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #b8d8ce;
  text-decoration: none;
  font-size: 14px;
  margin-bottom: 32px;
}

.contact-back-link:hover {
  color: #63e6b2;
}

.contact-hero {
  position: relative;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  min-height: 430px;
  overflow: hidden;
  border: 1px solid rgba(87, 211, 163, 0.18);
  border-radius: 28px;
  background: rgba(5, 39, 31, 0.76);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.22);
}

.contact-hero-content {
  position: relative;
  z-index: 2;
  padding: 70px 64px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.contact-kicker,
.contact-section-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #62e3ae;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.contact-hero h1 {
  max-width: 680px;
  margin: 18px 0 18px;
  color: #effff9;
  font-size: clamp(42px, 6vw, 72px);
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.contact-hero h1 span {
  color: #62e3ae;
}

.contact-hero-content > p {
  max-width: 610px;
  margin: 0;
  color: #a9c9bf;
  font-size: 17px;
  line-height: 1.7;
}

.contact-hero-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.contact-hero-links a {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #d9f8ed;
  text-decoration: none;
  border: 1px solid rgba(87, 211, 163, 0.2);
  border-radius: 999px;
  padding: 11px 16px;
  background: rgba(11, 63, 49, 0.45);
  font-size: 13px;
}

.contact-hero-links a:hover {
  border-color: rgba(87, 211, 163, 0.45);
  color: #62e3ae;
}

.contact-hero-art {
  position: relative;
  min-height: 430px;
  display: grid;
  place-items: center;
  overflow: hidden;
}

.contact-orbit {
  position: absolute;
  border: 1px solid rgba(88, 225, 174, 0.16);
  border-radius: 50%;
}

.contact-orbit-one {
  width: 310px;
  height: 310px;
}

.contact-orbit-two {
  width: 430px;
  height: 430px;
}

.contact-leaf-icon {
  width: 190px;
  height: 190px;
  display: grid;
  place-items: center;
  color: #62e3ae;
  border: 1px solid rgba(98, 227, 174, 0.25);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(49, 190, 139, 0.16), rgba(5, 39, 31, 0.2));
  box-shadow: 0 0 80px rgba(51, 211, 155, 0.12);
}

.contact-eco-badge {
  position: absolute;
  right: 8%;
  bottom: 15%;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px 13px;
  border: 1px solid rgba(98, 227, 174, 0.2);
  border-radius: 999px;
  background: rgba(4, 31, 24, 0.85);
  color: #9ee6cb;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.contact-grid {
  display: grid;
  grid-template-columns: 0.82fr 1.18fr;
  gap: 26px;
  margin-top: 26px;
}

.contact-info-column,
.contact-form-card {
  border: 1px solid rgba(87, 211, 163, 0.16);
  border-radius: 24px;
  background: rgba(4, 35, 28, 0.72);
}

.contact-info-column {
  padding: 38px;
}

.contact-info-column h2,
.contact-form-card h2,
.contact-bottom-cta h2 {
  margin: 8px 0 10px;
  color: #effff9;
  font-size: 30px;
  letter-spacing: -0.025em;
}

.contact-info-intro {
  margin: 0 0 28px;
  color: #91b8aa;
  line-height: 1.7;
}

.contact-info-cards {
  display: grid;
  gap: 10px;
}

.contact-info-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px;
  border: 1px solid rgba(87, 211, 163, 0.12);
  border-radius: 14px;
  background: rgba(8, 54, 42, 0.42);
  color: inherit;
  text-decoration: none;
}

.contact-info-card:hover {
  border-color: rgba(87, 211, 163, 0.3);
}

.contact-info-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: rgba(45, 210, 151, 0.1);
  color: #62e3ae;
}

.contact-info-card span:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.contact-info-card small {
  color: #71998d;
  font-size: 11px;
}

.contact-info-card strong {
  color: #ddf8ef;
  font-size: 14px;
}

.contact-help-card {
  display: flex;
  gap: 13px;
  margin-top: 20px;
  padding: 17px;
  border-radius: 15px;
  background: rgba(44, 190, 139, 0.07);
  color: #62e3ae;
}

.contact-help-card strong {
  display: block;
  color: #dff9ef;
  font-size: 14px;
}

.contact-help-card p {
  margin: 5px 0 0;
  color: #86afa1;
  font-size: 12px;
  line-height: 1.6;
}

.contact-form-card {
  padding: 38px;
}

.contact-form-heading {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 26px;
  color: #62e3ae;
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.contact-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.contact-form label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: #b7d5cb;
  font-size: 12px;
  font-weight: 700;
}

.contact-form input,
.contact-form select,
.contact-form textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid rgba(87, 211, 163, 0.16);
  border-radius: 12px;
  outline: none;
  background: rgba(2, 27, 21, 0.72);
  color: #eafff7;
  padding: 13px 14px;
  font: inherit;
  font-size: 13px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.contact-form textarea {
  resize: vertical;
  min-height: 150px;
}

.contact-form input::placeholder,
.contact-form textarea::placeholder {
  color: #55796e;
}

.contact-form select {
  appearance: auto;
}

.contact-form input:focus,
.contact-form select:focus,
.contact-form textarea:focus {
  border-color: rgba(98, 227, 174, 0.55);
  box-shadow: 0 0 0 3px rgba(98, 227, 174, 0.07);
}

.contact-submit-button,
.contact-secondary-button,
.contact-cta-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  width: fit-content;
  border: 0;
  border-radius: 12px;
  padding: 13px 19px;
  background: #08724f;
  color: #f0fff9;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  text-decoration: none;
  transition: transform 0.2s ease, background 0.2s ease;
}

.contact-submit-button:hover,
.contact-secondary-button:hover,
.contact-cta-button:hover {
  background: #0a8b61;
  transform: translateY(-1px);
}

.contact-form-note {
  margin: -3px 0 0;
  color: #5f887b;
  font-size: 11px;
}

.contact-success {
  min-height: 370px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: #62e3ae;
}

.contact-success h3 {
  margin: 18px 0 8px;
  color: #effff9;
  font-size: 24px;
}

.contact-success p {
  max-width: 400px;
  margin: 0 0 22px;
  color: #91b8aa;
  line-height: 1.7;
}

.contact-secondary-button {
  background: transparent;
  border: 1px solid rgba(87, 211, 163, 0.24);
}

.contact-bottom-cta {
  margin-top: 26px;
  padding: 34px 38px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  border: 1px solid rgba(87, 211, 163, 0.16);
  border-radius: 22px;
  background: rgba(5, 39, 31, 0.7);
}

.contact-bottom-cta p {
  margin: 0;
  color: #87afa1;
}

@media (max-width: 850px) {
  .contact-hero,
  .contact-grid {
    grid-template-columns: 1fr;
  }

  .contact-hero-content {
    padding: 48px 32px 25px;
  }

  .contact-hero-art {
    min-height: 270px;
  }

  .contact-info-column,
  .contact-form-card {
    padding: 28px;
  }

  .contact-bottom-cta {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 600px) {
  .contact-page {
    padding: 20px 12px 50px;
  }

  .contact-hero {
    border-radius: 20px;
  }

  .contact-hero h1 {
    font-size: 42px;
  }

  .contact-form-row {
    grid-template-columns: 1fr;
  }

  .contact-hero-links {
    flex-direction: column;
    align-items: flex-start;
  }

  .contact-info-column,
  .contact-form-card {
    padding: 22px;
    border-radius: 18px;
  }

  .contact-bottom-cta {
    padding: 26px 22px;
  }
}


.contact-form-error {
  padding: 12px 14px;
  border: 1px solid rgba(239, 100, 100, 0.3);
  border-radius: 12px;
  background: rgba(120, 30, 30, 0.15);
  color: #ffb4b4;
  font-size: 12px;
  line-height: 1.5;
}

.contact-submit-button:disabled {
  opacity: 0.65;
  cursor: not-allowed;
  transform: none;
}

/* =========================================================
   GREENCORE FUTURISTIC PRODUCT EXPERIENCE
   Final visual override layer
   ========================================================= */

.product-details-page {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(circle at 12% 18%, rgba(40, 220, 150, .07), transparent 28%),
    radial-gradient(circle at 88% 32%, rgba(34, 211, 238, .055), transparent 30%),
    linear-gradient(135deg, #021914 0%, #031f18 48%, #021610 100%);
}

.product-details-page::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  opacity: .32;
  background-image:
    linear-gradient(rgba(96, 255, 190, .055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(96, 255, 190, .055) 1px, transparent 1px);
  background-size: 52px 52px;
  mask-image: linear-gradient(to bottom, black, transparent 88%);
}

.product-details-container {
  position: relative;
}

.product-details-layout {
  gap: clamp(30px, 4vw, 64px);
  align-items: start;
}

/* Main product media */
.product-detail-gallery-main {
  position: relative;
  min-height: 590px;
  overflow: hidden;
  border: 1px solid rgba(105, 255, 194, .22) !important;
  border-radius: 30px !important;
  background:
    radial-gradient(circle at 50% 42%, rgba(255,255,255,.09), transparent 42%),
    linear-gradient(145deg, rgba(11, 70, 51, .72), rgba(2, 30, 23, .92)) !important;
  box-shadow:
    0 30px 90px rgba(0,0,0,.28),
    inset 0 1px 0 rgba(255,255,255,.08),
    0 0 0 1px rgba(67, 255, 181, .035);
  backdrop-filter: blur(18px);
}

.product-detail-gallery-main::before {
  content: "";
  position: absolute;
  inset: 14px;
  z-index: 2;
  pointer-events: none;
  border: 1px solid rgba(108, 255, 194, .08);
  border-radius: 22px;
}

.product-detail-gallery-main::after {
  content: "GREENCORE • CIRCULAR PRODUCT";
  position: absolute;
  left: 28px;
  bottom: 23px;
  z-index: 4;
  padding: 8px 12px;
  border: 1px solid rgba(107, 255, 192, .16);
  border-radius: 999px;
  background: rgba(2, 35, 27, .68);
  color: rgba(157, 255, 216, .68);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .16em;
  backdrop-filter: blur(12px);
}

.product-detail-gallery-image {
  width: 100% !important;
  height: 590px !important;
  display: block;
  object-fit: contain !important;
  object-position: center;
  padding: 34px;
  border-radius: 28px;
  filter: saturate(.96) contrast(1.02);
  transition:
    transform .6s cubic-bezier(.2,.7,.2,1),
    filter .35s ease;
}

.product-detail-gallery-main:hover .product-detail-gallery-image {
  transform: scale(1.025);
  filter: saturate(1.04) contrast(1.04);
}

/* Futuristic navigation buttons */
.product-detail-gallery-nav {
  width: 46px !important;
  height: 46px !important;
  z-index: 5;
  border: 1px solid rgba(102, 255, 193, .22) !important;
  border-radius: 14px !important;
  background: rgba(2, 31, 24, .78) !important;
  color: #75f4b4 !important;
  box-shadow:
    0 10px 30px rgba(0,0,0,.25),
    inset 0 1px 0 rgba(255,255,255,.07);
  backdrop-filter: blur(14px);
  transition: all .25s ease;
}

.product-detail-gallery-nav:hover {
  transform: translateY(-2px) scale(1.05);
  border-color: rgba(101, 255, 190, .55) !important;
  background: rgba(7, 67, 49, .9) !important;
  box-shadow:
    0 12px 35px rgba(0,0,0,.32),
    0 0 24px rgba(61, 244, 159, .13);
}

/* Counter */
.product-detail-gallery-counter {
  z-index: 5;
  border: 1px solid rgba(105, 255, 194, .16);
  border-radius: 999px;
  padding: 8px 13px;
  background: rgba(2, 32, 24, .72);
  color: rgba(215, 255, 235, .82);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;
  backdrop-filter: blur(14px);
}

/* Thumbnail strip */
.product-detail-gallery-thumbnails {
  display: grid !important;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 11px !important;
  margin-top: 14px !important;
  padding: 10px !important;
  border: 1px solid rgba(104, 255, 193, .12);
  border-radius: 21px;
  background: rgba(3, 35, 27, .58);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.045),
    0 14px 40px rgba(0,0,0,.16);
  backdrop-filter: blur(16px);
}

.product-detail-gallery-thumbnail {
  position: relative;
  min-width: 0;
  height: 82px !important;
  overflow: hidden;
  border: 1px solid rgba(106, 255, 193, .11) !important;
  border-radius: 14px !important;
  background: rgba(8, 57, 43, .7) !important;
