.product-detail-gallery-thumbnail:hover {
  transform: translateY(-3px);
  opacity: .9;
  border-color: rgba(104, 255, 193, .38) !important;
}

.product-detail-gallery-thumbnail.active {
  opacity: 1 !important;
  border-color: #62efaa !important;
