.gallery-page [class*="hero-globe"],
.gallery-page [class*="hero-art"],
.gallery-page [class*="hero-visual"],
.gallery-page [class*="hero-decoration"],
.gallery-page [class*="gallery-orb"],
.gallery-page [class*="gallery-globe"],
.gallery-page [class*="gallery-decoration"],
.gallery-page [class*="hero-side"] {
  display: none !important;
}

/* Hide the old decorative People / Ideas / Impact block */
.gallery-page [class*="People"],
.gallery-page [class*="people"],
.gallery-page [class*="hero-words"],
.gallery-page [class*="hero-caption"],
.gallery-page [class*="hero-side-text"] {
  display: none !important;
}

/* Give the hero a clean futuristic atmosphere */
.gallery-page .gallery-hero,
.gallery-page [class*="gallery-hero"] {
  position: relative;
  overflow: hidden;
  isolation: isolate;
}

/* Subtle ambient glow — CSS only */
.gallery-page .gallery-hero::before {
  content: "";
  position: absolute;
  width: 520px;
  height: 520px;
  right: 4%;
  top: -230px;
  border-radius: 50%;
  background:
    radial-gradient(
      circle,
      rgba(35, 220, 139, 0.16) 0%,
      rgba(35, 220, 139, 0.07) 32%,
      rgba(35, 220, 139, 0.025) 55%,
      transparent 72%
    );
  filter: blur(8px);
  pointer-events: none;
  z-index: -1;
}

/* Small futuristic ring instead of the huge old graphic */
.gallery-page .gallery-hero::after {
  content: "";
  position: absolute;
  width: 280px;
  height: 280px;
  right: 12%;
  top: -145px;
  border: 1px solid rgba(68, 230, 155, 0.16);
  border-radius: 50%;
  box-shadow:
    0 0 70px rgba(30, 210, 125, 0.08),
    inset 0 0 50px rgba(30, 210, 125, 0.035);
  pointer-events: none;
  z-index: -1;
}

/* Keep hero content properly centered */
.gallery-page .gallery-hero > * {
  position: relative;
  z-index: 2;
}

/* Prevent oversized decorative SVGs from escaping the hero */
.gallery-page .gallery-hero svg {
  max-width: 100%;
}

/* Mobile: remove decorative ring entirely */
@media (max-width: 768px) {
  .gallery-page .gallery-hero::before,
  .gallery-page .gallery-hero::after {
    display: none;
  }
}
